INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39281, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "abstract", "definition": "物事に接して心に生じる、ある感じや気持ち。", "primary_collocate": null, "pronunciation": "かん", "ipa": "kaɴ", "syllable_count": 2, "sentences": [{"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "感", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "感", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "コンクリートの打ちっぱなしという素材感を活かした設計は、入居者のコミュニティ形成に多大な社会的影響を与えました。", "target_word": "感", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "力強く円を描くことで、言葉にできない思春期の焦燥感が、少しずつ紙の上へ溶け出していくようだった。", "target_word": "感", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "感", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "試合に勝って、達成感があった。", "target_word": "感", "complexity_tier": "T3", "furigana": "たっせいかん", "sentence_source": "generated"}, {"text": "彼の声には不思議な安心感がある。", "target_word": "感", "complexity_tier": "T3", "furigana": "ふしぎ あんしんかん", "sentence_source": "generated"}, {"text": "発表の前は緊張感で手が冷たい。", "target_word": "感", "complexity_tier": "T3", "furigana": "はっぴょう まえ きんちょうかん て つめ", "sentence_source": "generated"}, {"text": "新しい制服は清潔感がある。", "target_word": "感", "complexity_tier": "T3", "furigana": "あたら せいふく せいけつかん", "sentence_source": "generated"}, {"text": "この部屋には少し圧迫感を感じる。", "target_word": "感", "complexity_tier": "T3", "furigana": "へや あっぱくかん かん", "sentence_source": "generated"}], "morphological_forms": [{"form": "安心感", "label": "派生"}, {"form": "達成感", "label": "派生"}, {"form": "存在感", "label": "派生"}, {"form": "緊張感", "label": "派生"}], "register": "formal", "sense_fingerprint": "接尾辞 | 名詞について生じる感じや気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 直面 (Zipf 3.86), 超越 (Zipf 3.64), 支える (Zipf 3.98)','sentence 1 above tier T1: contains vocabulary far above tier T1: 愉楽 (Zipf 1.65)','sentence 2 above tier T1: contains vocabulary far above tier T1: 打ちっぱなし (Zipf 2.18)','sentence 3 above tier T1: 3 words above tier T1 (max 2): 力強く (Zipf 3.37), 思春 (Zipf 3.69), 焦燥 (Zipf 2.87)','sentence 4 above tier T1: contains vocabulary far above tier T1: 切片 (Zipf 1.86)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36183, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "言葉や記号、動作などによって示される内容や価値。", "primary_collocate": null, "pronunciation": "いみ", "ipa": "imi", "syllable_count": 2, "sentences": [{"text": "これは事業の終了ではなく、資本の循環と新たな創造への移行を意味する重要なプロセスだ。", "target_word": "意味", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "意味", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "結果として、建築は静的な物体ではなく、見る者によって絶えず意味が更新される開かれた場として再定義されるのです。", "target_word": "意味", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "企業はこれらの色彩が持つ記号的意味を深く理解し、自社のアイデンティティを消費者の心に効果的に植え付けようとしている。", "target_word": "意味", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "彼女の人生におけるこの学校の初日は、単なる物理的な場所の移動を意味するものではない。", "target_word": "意味", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この言葉の意味がわからない。", "target_word": "意味", "complexity_tier": "T3", "furigana": "ことば いみ", "sentence_source": "generated"}, {"text": "辞書で意味を調べている。", "target_word": "意味", "complexity_tier": "T3", "furigana": "じしょ いみ しら", "sentence_source": "generated"}, {"text": "赤信号は止まれという意味だ。", "target_word": "意味", "complexity_tier": "T3", "furigana": "あかしんごう と いみ", "sentence_source": "generated"}, {"text": "彼の笑顔の意味を考えた。", "target_word": "意味", "complexity_tier": "T3", "furigana": "かれ えがお いみ かんが", "sentence_source": "generated"}, {"text": "練習しないと意味がないよ。", "target_word": "意味", "complexity_tier": "T3", "furigana": "れんしゅう いみ", "sentence_source": "generated"}], "morphological_forms": [{"form": "意味する", "label": "派生"}, {"form": "意味深い", "label": "派生"}, {"form": "無意味", "label": "派生"}, {"form": "意味合い", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 言葉や行為が示す内容や価値", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 静的 (Zipf 3.04), 物体 (Zipf 3.86), 絶えず (Zipf 3.47)','sentence 3 above tier T1: 4 words above tier T1 (max 2): 色彩 (Zipf 3.83), 記号 (Zipf 3.85), アイデンティティ (Zipf 3.53), 植え付けよ (Zipf 3.26)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38363, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物が育つもとになる、小さな粒。また、物事が生まれるもと。", "primary_collocate": null, "pronunciation": "たね", "ipa": "tane", "syllable_count": 2, "sentences": [{"text": "スタートアップは、革新的なアイデアを種として創業される。", "target_word": "種", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "その過程は、微生物を培養する「種起こし」から始まります。", "target_word": "種", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "種", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "静謐な工房において、作り手は野生酵母と乳酸菌の共生するサワードウの種起こしから営為を開始する。", "target_word": "種", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "数日かけて培養されたルヴァン種は、独特の酸味と芳醇な香りを纏い、パンの骨格を形成する。", "target_word": "種", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "春に花の種を土にまいた。", "target_word": "種", "complexity_tier": "T3", "furigana": "はる はな たね つち", "sentence_source": "generated"}, {"text": "このパンは自家製の種で作る。", "target_word": "種", "complexity_tier": "T3", "furigana": "じかせい たね つく", "sentence_source": "generated"}, {"text": "種から小さな芽が出てきた。", "target_word": "種", "complexity_tier": "T3", "furigana": "たね ちい め で", "sentence_source": "generated"}, {"text": "祖母は毎年トマトの種を集める。", "target_word": "種", "complexity_tier": "T3", "furigana": "そぼ まいとし たね あつ", "sentence_source": "generated"}, {"text": "種を水につけておいた。", "target_word": "種", "complexity_tier": "T3", "furigana": "たね みず", "sentence_source": "generated"}], "morphological_forms": [{"form": "種子", "label": "派生"}, {"form": "品種", "label": "派生"}, {"form": "一粒", "label": "助数詞"}, {"form": "種まき", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 植物や物事が生まれるもと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 営為 (Zipf 1.88)','sentence 4 above tier T2: 5 words above tier T2 (max 3): 培養 (Zipf 3.6), ルヴァン (Zipf 2.53), 酸味 (Zipf 3.39), 芳醇 (Zipf 2.57), 纏い (Zipf 2.78)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35431, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を支えるもとになる、しっかりした部分。土台。", "primary_collocate": null, "pronunciation": "きばん", "ipa": "kibaɴ", "syllable_count": 3, "sentences": [{"text": "初期段階では、投資家からの資金調達を通じて事業の基盤を固め、市場での急速な成長を目指す。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この効率的な生産システムは、私たちの食生活を支える基盤となっているのです。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "近年、パラメトリックデザインの理論は、都市主義の分野において重要な基盤となりつつあります。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "家族は私の生活の基盤だ。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "かぞく わたし せいかつ きばん", "sentence_source": "generated"}, {"text": "この町は農業が経済の基盤です。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "まち のうぎょう けいざい きばん", "sentence_source": "generated"}, {"text": "信頼は友情の基盤になる。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "しんらい ゆうじょう きばん", "sentence_source": "generated"}, {"text": "基盤がしっかりした会社で働く。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "きばん かいしゃ はたら", "sentence_source": "generated"}, {"text": "新しい生活の基盤を作っている。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "あたら せいかつ きばん つく", "sentence_source": "generated"}, {"text": "基礎練習がチームの基盤を支える。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "きそれんしゅう きばん ささ", "sentence_source": "generated"}], "morphological_forms": [{"form": "基盤的", "label": "派生"}, {"form": "生活基盤", "label": "派生"}, {"form": "経済基盤", "label": "派生"}, {"form": "基盤整備", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事を支えるしっかりした土台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35977, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物事を必要としたり、実現したいと強く願ったりする。", "primary_collocate": null, "pronunciation": "もとめる", "ipa": "motomeɾɯ", "syllable_count": 4, "sentences": [{"text": "誰に何を求めているか分析し、適切な言葉で発信することで、小さくても確実なファンを獲得できます。", "target_word": "求め", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "企業は、単純な作業だけでなく、創造性や対人スキルを求められる役割へ従業員をシフトさせなければならない。", "target_word": "求め", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "変化に適応し、自らの価値を高め続ける姿勢が、これからの職場では強く求められる。", "target_word": "求め", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "現実の太陽は橙色だが、私が記憶の中で求める太陽は、情熱的で切ない赤色でなければならない。", "target_word": "求める", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "現実的な設計図とは異なるが、その絵には彼が求める理想の世界が詰まっている。", "target_word": "求める", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "彼は先生に助けを求めた。", "target_word": "求め", "complexity_tier": "T3", "furigana": "かれ せんせい たす もと", "sentence_source": "generated"}, {"text": "人々は平和を求めている。", "target_word": "求め", "complexity_tier": "T3", "furigana": "ひとびと へいわ もと", "sentence_source": "generated"}, {"text": "店長は明るい店員を求める。", "target_word": "求める", "complexity_tier": "T3", "furigana": "てんちょう あか てんいん もと", "sentence_source": "generated"}, {"text": "みんなに意見を求められた。", "target_word": "求め", "complexity_tier": "T3", "furigana": "いけん もと", "sentence_source": "generated"}, {"text": "自由を求めて旅に出た。", "target_word": "求め", "complexity_tier": "T3", "furigana": "じゆう もと たび で", "sentence_source": "generated"}], "morphological_forms": [{"form": "求めた", "label": "活用"}, {"form": "求めて", "label": "活用"}, {"form": "求めない", "label": "活用"}, {"form": "求められる", "label": "活用"}, {"form": "求め", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 必要として強く願い得ようとする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36163, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を細かい要素に分けて、その性質や関係を明らかにすること。", "primary_collocate": null, "pronunciation": "ぶんせき", "ipa": "bɯɴseki", "syllable_count": 4, "sentences": [{"text": "誰に何を求めているか分析し、適切な言葉で発信することで、小さくても確実なファンを獲得できます。", "target_word": "分析", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "分析", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "次いで、分岐や終点といった特徴点の配列を精密に分析する。", "target_word": "分析", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "真実を解き明かすための静謐かつ論理的なプロセス、それこそが指紋分析の真髄と言えよう。", "target_word": "分析", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "社会経済現象の真の駆動力は、還元主義的な分析の彼方、ネットワーク全体の創発的特性の内にこそ宿っていると言えよう。", "target_word": "分析", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "試合のデータを分析している。", "target_word": "分析", "complexity_tier": "T3", "furigana": "しあい ぶんせき", "sentence_source": "generated"}, {"text": "先生の分析はとても正確だった。", "target_word": "分析", "complexity_tier": "T3", "furigana": "せんせい ぶんせき せいかく", "sentence_source": "generated"}, {"text": "アンケートの結果を分析した。", "target_word": "分析", "complexity_tier": "T3", "furigana": "けっか ぶんせき", "sentence_source": "generated"}, {"text": "分析の結果、問題が見つかった。", "target_word": "分析", "complexity_tier": "T3", "furigana": "ぶんせき けっか もんだい み", "sentence_source": "generated"}, {"text": "彼は人の気持ちの分析が得意だ。", "target_word": "分析", "complexity_tier": "T3", "furigana": "かれ ひと きも ぶんせき とくい", "sentence_source": "generated"}], "morphological_forms": [{"form": "分析する", "label": "派生"}, {"form": "分析的", "label": "派生"}, {"form": "分析力", "label": "派生"}, {"form": "分析者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 要素に分けて性質を明らかにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: 4 words above tier T2 (max 3): 解き明かす (Zipf 2.8), 静謐 (Zipf 2.66), 指紋 (Zipf 3.67), 真髄 (Zipf 2.84)','sentence 4 above tier T2: contains vocabulary far above tier T2: 創発 (Zipf 2.41)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35851, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や機械などが互いにつながり、情報をやり取りするしくみ。", "primary_collocate": null, "pronunciation": "ねっとわーく", "ipa": "netːowaːkɯ", "syllable_count": 6, "sentences": [{"text": "既存の緑地と有機的にネットワークを形成することで生態系の回廊としての機能を補完し、ひいては地域全体の環境リテラシーを向上させる原動力となり得るのである。", "target_word": "ネットワーク", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "単なる出資にとどまらず、経営戦略やネットワークを提供することで、市場に新たな価値を生むイノベーションを加速させるのだ。", "target_word": "ネットワーク", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "社会経済現象の真の駆動力は、還元主義的な分析の彼方、ネットワーク全体の創発的特性の内にこそ宿っていると言えよう。", "target_word": "ネットワーク", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "ネットワーク", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "学校のネットワークがつながらない。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "がっこう", "sentence_source": "generated"}, {"text": "彼は広いネットワークを持っている。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "かれ ひろ も", "sentence_source": "generated"}, {"text": "ネットワークを使って情報を集めた。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "つか じょうほう あつ", "sentence_source": "generated"}, {"text": "町の人々のネットワークが役に立った。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "まち ひとびと やく た", "sentence_source": "generated"}, {"text": "新しいネットワークを作りたい。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "あたら つく", "sentence_source": "generated"}, {"text": "このネットワークは安全です。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "あんぜん", "sentence_source": "generated"}], "morphological_forms": [{"form": "ネットワーク化", "label": "派生"}, {"form": "人的ネットワーク", "label": "派生"}, {"form": "ネットワーク作り", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 互いにつながり情報を交わすしくみ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 5 words above tier T2 (max 3): 緑地 (Zipf 3.09), 回廊 (Zipf 3.11), ひいては (Zipf 3.24), リテラシー (Zipf 3.08), 原動力 (Zipf 3.4)','sentence 2 above tier T2: contains vocabulary far above tier T2: 創発 (Zipf 2.41)','sentence 3 above tier T2: 6 words above tier T2 (max 3): 知見 (Zipf 3.42), 人的 (Zipf 3.67), 触発 (Zipf 3.32), ひいては (Zipf 3.24), 変革 (Zipf 3.6), 原動力 (Zipf 3.4)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36933, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "最近の数年の間。", "primary_collocate": null, "pronunciation": "きんねん", "ipa": "kinneɴ", "syllable_count": 4, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "近年", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "近年、精密農業の導入が小規模農家の経営に新たな可能性をもたらしています。", "target_word": "近年", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "近年、センサーやデータ解析技術を活用した「精密農業」が注目されています。", "target_word": "近年", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "近年、パラメトリックデザインの理論は、都市主義の分野において重要な基盤となりつつあります。", "target_word": "近年", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "近年、外国人の観光客が増えている。", "target_word": "近年", "complexity_tier": "T3", "furigana": "きんねん がいこくじん かんこうきゃく ふ", "sentence_source": "generated"}, {"text": "近年の夏はとても暑い。", "target_word": "近年", "complexity_tier": "T3", "furigana": "きんねん なつ あつ", "sentence_source": "generated"}, {"text": "近年になって町が変わった。", "target_word": "近年", "complexity_tier": "T3", "furigana": "きんねん まち か", "sentence_source": "generated"}, {"text": "この問題は近年よく話題になる。", "target_word": "近年", "complexity_tier": "T3", "furigana": "もんだい きんねん わだい", "sentence_source": "generated"}, {"text": "近年まれに見る大雪だった。", "target_word": "近年", "complexity_tier": "T3", "furigana": "きんねん み おおゆき", "sentence_source": "generated"}, {"text": "近年は本を読む人が減った。", "target_word": "近年", "complexity_tier": "T3", "furigana": "きんねん ほん よ ひと へ", "sentence_source": "generated"}], "morphological_forms": [{"form": "近年来", "label": "派生"}, {"form": "近年中", "label": "派生"}, {"form": "近年の", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | ここ数年の最近の期間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 無秩序 (Zipf 2.99), 希薄 (Zipf 3.22), 歯止め (Zipf 3.18), 顕在 (Zipf 3.05)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37927, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "量や内容が十分にあり、満ち足りているようす。", "primary_collocate": null, "pronunciation": "ゆたか", "ipa": "jɯtaka", "syllable_count": 3, "sentences": [{"text": "これらは視覚的な雑音を減らし、心の豊かさを追求する手段となっています。", "target_word": "豊か", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "一連の科学的な変化を経て、風味豊かなパンが完成するのです。", "target_word": "豊か", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "単なるエネルギー源に過ぎなかった穀物が、生命の維持と豊かな食体験を同時に叶える食文化へと昇華される。", "target_word": "豊か", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "過酷な自然環境と向き合いながら、彼は今日も黙々と作業を続け、やがて訪れる豊かな実りの季節を心待ちにしている。", "target_word": "豊か", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "この国は自然が豊かだ。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "くに しぜん ゆたか", "sentence_source": "generated"}, {"text": "彼女は表情が豊かです。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "かのじょ ひょうじょう ゆたか", "sentence_source": "generated"}, {"text": "本を読むと心が豊かになる。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "ほん よ こころ ゆたか", "sentence_source": "generated"}, {"text": "豊かな森に鳥がたくさんいる。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "ゆたか もり とり", "sentence_source": "generated"}, {"text": "村の生活は豊かではなかった。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "むら せいかつ ゆたか", "sentence_source": "generated"}, {"text": "想像力が豊かな子どもだ。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "そうぞうりょく ゆたか こ", "sentence_source": "generated"}], "morphological_forms": [{"form": "豊かな", "label": "活用"}, {"form": "豊かに", "label": "活用"}, {"form": "豊かだった", "label": "活用"}, {"form": "豊かさ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 量や内容が十分で満ちている", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: 4 words above tier T2 (max 3): 向き合い (Zipf 3.11), 黙々と (Zipf 3.25), 実り (Zipf 3.12), 心待ち (Zipf 3.01)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37435, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あることを土台や根拠とする。", "primary_collocate": null, "pronunciation": "もとづく", "ipa": "motodzɯkɯ", "syllable_count": 4, "sentences": [{"text": "ミニマリストの思想に基づき、必要な要素だけを残すことで、居住者はより穏やかな日常を送ることができます。", "target_word": "基づき", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "建築を単なる機能の集合体ではなく、記号が織りなすテキストとして読み解く態度が、ポスト構造主義に基づく批評の核心です。", "target_word": "基づく", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "基づき", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "これは心理学に基づいた人間の無意識の反応を利用したものだ。", "target_word": "基づい", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "この話は事実に基づいている。", "target_word": "基づい", "complexity_tier": "T3", "furigana": "はなし じじつ もと", "sentence_source": "generated"}, {"text": "調査に基づいて計画を立てた。", "target_word": "基づい", "complexity_tier": "T3", "furigana": "ちょうさ もと けいかく た", "sentence_source": "generated"}, {"text": "規則に基づく判断が必要だ。", "target_word": "基づく", "complexity_tier": "T3", "furigana": "きそく もと はんだん ひつよう", "sentence_source": "generated"}, {"text": "経験に基づいた意見を言う。", "target_word": "基づい", "complexity_tier": "T3", "furigana": "けいけん もと いけん い", "sentence_source": "generated"}, {"text": "データに基づき結果を出した。", "target_word": "基づき", "complexity_tier": "T3", "furigana": "もと けっか だ", "sentence_source": "generated"}, {"text": "彼の考えは何にも基づかない。", "target_word": "基づか", "complexity_tier": "T3", "furigana": "かれ かんが なに もと", "sentence_source": "generated"}], "morphological_forms": [{"form": "基づき", "label": "活用"}, {"form": "基づいて", "label": "活用"}, {"form": "基づいた", "label": "活用"}, {"form": "基づかない", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | あることを根拠や土台とする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53272, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いくつかの要素を組み合わせて、一つのまとまりを作り出す。", "primary_collocate": null, "pronunciation": "おりなす", "ipa": "oɾinasɯ", "syllable_count": 4, "sentences": [{"text": "建築を単なる機能の集合体ではなく、記号が織りなすテキストとして読み解く態度が、ポスト構造主義に基づく批評の核心です。", "target_word": "織りなす", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "むしろ、それらの相互作用が織りなす複雑適応システムにおいては、正負のフィードバックを介した非線形なダイナミクスが、予測不可能なマクロな秩序、すなわち創発をもたらすのである。", "target_word": "織りなす", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "織りなす", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "織りなす", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "光と影が織りなす景色が美しい。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "ひかり かげ お けしき うつく", "sentence_source": "generated"}, {"text": "多くの人の思いが物語を織りなす。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "おお ひと おも ものがたり お", "sentence_source": "generated"}, {"text": "音と色が織りなした世界に感動した。", "target_word": "織りなし", "complexity_tier": "T3", "furigana": "おと いろ お せかい かんどう", "sentence_source": "generated"}, {"text": "山と川が織りなして美しい町になる。", "target_word": "織りなし", "complexity_tier": "T3", "furigana": "やま かわ お うつく まち", "sentence_source": "generated"}, {"text": "出会いと別れが人生を織りなす。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "であ わか じんせい お", "sentence_source": "generated"}, {"text": "四季が織りなす風景を楽しむ。", "target_word": "織りなす", "complexity_tier": "T3", "furigana": "しき お ふうけい たの", "sentence_source": "generated"}], "morphological_forms": [{"form": "織りなした", "label": "活用"}, {"form": "織りなして", "label": "活用"}, {"form": "織りなされる", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 要素を組み合わせ全体を作り出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35405, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を構成する各部分の配置や相互の関係。", "primary_collocate": null, "pronunciation": "こうぞう", "ipa": "koːzoː", "syllable_count": 4, "sentences": [{"text": "建築を単なる機能の集合体ではなく、記号が織りなすテキストとして読み解く態度が、ポスト構造主義に基づく批評の核心です。", "target_word": "構造", "complexity_tier": "T3", "furigana": "こうぞう", "sentence_source": "mined"}, {"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "構造", "complexity_tier": "T3", "furigana": "こうぞう", "sentence_source": "mined"}, {"text": "熟練したソムリエは、グラス内で展開される鉱物的な輪郭や土壌由来の複雑な香気構造を解読し、視覚や嗅覚を超えた土地的コンテキストを味覚的に再構成する。", "target_word": "構造", "complexity_tier": "T3", "furigana": "こうぞう", "sentence_source": "mined"}, {"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "構造", "complexity_tier": "T3", "furigana": "こうぞう", "sentence_source": "mined"}, {"text": "この橋の構造はとても丈夫だ。", "target_word": "構造", "complexity_tier": "T3", "furigana": "こうぞう", "sentence_source": "generated"}, {"text": "体の構造を理科で学んでいる。", "target_word": "構造", "complexity_tier": "T3", "furigana": "からだ こうぞう りか まな", "sentence_source": "generated"}, {"text": "文の構造を先生が説明した。", "target_word": "構造", "complexity_tier": "T3", "furigana": "ぶん こうぞう せんせい せつめい", "sentence_source": "generated"}, {"text": "家の構造が地震に強い。", "target_word": "構造", "complexity_tier": "T3", "furigana": "いえ こうぞう じしん つよ", "sentence_source": "generated"}, {"text": "会社の構造を変える必要がある。", "target_word": "構造", "complexity_tier": "T3", "furigana": "かいしゃ こうぞう か ひつよう", "sentence_source": "generated"}, {"text": "複雑な構造の機械を見た。", "target_word": "構造", "complexity_tier": "T3", "furigana": "ふくざつ こうぞう きかい み", "sentence_source": "generated"}], "morphological_forms": [{"form": "構造的", "label": "派生"}, {"form": "構造化", "label": "派生"}, {"form": "構造上", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 部分の組み立てと関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 香気 (Zipf 2.11)','sentence 3 above tier T2: 6 words above tier T2 (max 3): 知見 (Zipf 3.42), 人的 (Zipf 3.67), 触発 (Zipf 3.32), ひいては (Zipf 3.24), 変革 (Zipf 3.6), 原動力 (Zipf 3.4)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
