INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35533, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "農業を仕事にしている人。作物を育てたり、家畜を飼ったりして生活する人。", "primary_collocate": null, "pronunciation": "のうか", "ipa": "noːka", "syllable_count": 3, "sentences": [{"text": "近年、精密農業の導入が小規模農家の経営に新たな可能性をもたらしています。", "target_word": "農家", "complexity_tier": "T3", "furigana": "のうか", "sentence_source": "mined"}, {"text": "高校を卒業したばかりの10代の彼が選んだ道は、地方の有機農家で働くことでした。", "target_word": "農家", "complexity_tier": "T3", "furigana": "のうか", "sentence_source": "mined"}, {"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "農家", "complexity_tier": "T3", "furigana": "のうか", "sentence_source": "mined"}, {"text": "夜が明け、太陽が農場を照らし始める朝、農家の男は鶏舎へと足を運ぶ。", "target_word": "農家", "complexity_tier": "T3", "furigana": "のうか", "sentence_source": "mined"}, {"text": "祖父は米を作る農家だ。", "target_word": "農家", "complexity_tier": "T3", "furigana": "そふ こめ つく のうか", "sentence_source": "generated"}, {"text": "農家の朝はとても早い。", "target_word": "農家", "complexity_tier": "T3", "furigana": "のうか あさ はや", "sentence_source": "generated"}, {"text": "村には農家が十軒ある。", "target_word": "農家", "complexity_tier": "T3", "furigana": "むら のうか じゅっけん", "sentence_source": "generated"}, {"text": "農家から野菜を買った。", "target_word": "農家", "complexity_tier": "T3", "furigana": "のうか やさい か", "sentence_source": "generated"}, {"text": "雨が少なくて農家が困っている。", "target_word": "農家", "complexity_tier": "T3", "furigana": "あめ すく のうか こま", "sentence_source": "generated"}, {"text": "将来は農家になりたい。", "target_word": "農家", "complexity_tier": "T3", "furigana": "しょうらい のうか", "sentence_source": "generated"}], "morphological_forms": [{"form": "軒", "label": "助数詞"}, {"form": "農家さん", "label": "派生"}, {"form": "兼業農家", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 農業で生活する人や家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38293, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ある条件の中で、最も適していて良いこと。", "primary_collocate": null, "pronunciation": "さいてき", "ipa": "saitekʲi", "syllable_count": 4, "sentences": [{"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "最適", "complexity_tier": "T3", "furigana": "さいてき", "sentence_source": "mined"}, {"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "最適", "complexity_tier": "T3", "furigana": "さいてき", "sentence_source": "mined"}, {"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "最適", "complexity_tier": "T3", "furigana": "さいてき", "sentence_source": "mined"}, {"text": "これにより、ムダを省きながら収量の「最適化」を図ることができます。", "target_word": "最適", "complexity_tier": "T3", "furigana": "さいてき", "sentence_source": "mined"}, {"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "最適", "complexity_tier": "T3", "furigana": "さいてき", "sentence_source": "mined"}, {"text": "ここは勉強に最適な場所だ。", "target_word": "最適", "complexity_tier": "T3", "furigana": "べんきょう さいてき ばしょ", "sentence_source": "generated"}, {"text": "この服は旅行に最適だ。", "target_word": "最適", "complexity_tier": "T3", "furigana": "ふく りょこう さいてき", "sentence_source": "generated"}, {"text": "最適な方法を考えている。", "target_word": "最適", "complexity_tier": "T3", "furigana": "さいてき ほうほう かんが", "sentence_source": "generated"}, {"text": "秋は運動に最適な季節だ。", "target_word": "最適", "complexity_tier": "T3", "furigana": "あき うんどう さいてき きせつ", "sentence_source": "generated"}, {"text": "温度を最適に保っている。", "target_word": "最適", "complexity_tier": "T3", "furigana": "おんど さいてき たも", "sentence_source": "generated"}], "morphological_forms": [{"form": "最適な", "label": "活用"}, {"form": "最適に", "label": "活用"}, {"form": "最適だ", "label": "活用"}, {"form": "最適化", "label": "派生"}, {"form": "最適解", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 条件に最もよく合う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35809, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が続いていく性質や状態。長く維持できること。", "primary_collocate": null, "pronunciation": "じぞく", "ipa": "dʑizokɯ", "syllable_count": 3, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "持続", "complexity_tier": "T3", "furigana": "じぞく", "sentence_source": "mined"}, {"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "持続", "complexity_tier": "T3", "furigana": "じぞく", "sentence_source": "mined"}, {"text": "また、限られた環境で効率的に生産を行う「資源管理」の観点からも、持続可能な食料供給の実現において重要な役割を果たしています。", "target_word": "持続", "complexity_tier": "T3", "furigana": "じぞく", "sentence_source": "mined"}, {"text": "テクノロジー産業の持続的発展において、ベンチャーキャピタルの存在は極めて不可欠である。", "target_word": "持続", "complexity_tier": "T3", "furigana": "じぞく", "sentence_source": "mined"}, {"text": "集中力の持続は難しい。", "target_word": "持続", "complexity_tier": "T3", "furigana": "しゅうちゅうりょく じぞく むずか", "sentence_source": "generated"}, {"text": "この薬は効果が持続する。", "target_word": "持続", "complexity_tier": "T3", "furigana": "くすり こうか じぞく", "sentence_source": "generated"}, {"text": "練習を持続することが大切だ。", "target_word": "持続", "complexity_tier": "T3", "furigana": "れんしゅう じぞく たいせつ", "sentence_source": "generated"}, {"text": "痛みが三日も持続した。", "target_word": "持続", "complexity_tier": "T3", "furigana": "いた みっか じぞく", "sentence_source": "generated"}, {"text": "元気の持続には睡眠が必要だ。", "target_word": "持続", "complexity_tier": "T3", "furigana": "げんき じぞく すいみん ひつよう", "sentence_source": "generated"}, {"text": "好調が持続している。", "target_word": "持続", "complexity_tier": "T3", "furigana": "こうちょう じぞく", "sentence_source": "generated"}], "morphological_forms": [{"form": "持続する", "label": "活用"}, {"form": "持続的", "label": "派生"}, {"form": "持続可能", "label": "派生"}, {"form": "持続力", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 状態が長く続くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35827, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "危険や損失が生じる可能性。将来の悪い結果の見込み。", "primary_collocate": null, "pronunciation": "りすく", "ipa": "ɾisɯkɯ", "syllable_count": 3, "sentences": [{"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "りすく", "sentence_source": "mined"}, {"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "りすく", "sentence_source": "mined"}, {"text": "ベンチャーキャピタルは、将来性のあるスタートアップへリスクを取って資金調達を行い、その成長を支援する重要な役割を担っている。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "りすく", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "りすく", "sentence_source": "mined"}, {"text": "不確実性の高い技術的課題に挑む起業家に対し、リスクマネーを供給することで、彼らは市場の失敗を補完し、破壊的なイノベーションの萌芽を育むのである。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "りすく", "sentence_source": "mined"}, {"text": "この計画にはリスクがある。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "リスクを減らす工夫をした。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "へ くふう", "sentence_source": "generated"}, {"text": "病気のリスクが高くなる。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "びょうき たか", "sentence_source": "generated"}, {"text": "彼はリスクを恐れない。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "かれ おそ", "sentence_source": "generated"}, {"text": "リスクの少ない方法を選ぼう。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "すく ほうほう えら", "sentence_source": "generated"}], "morphological_forms": [{"form": "リスク管理", "label": "派生"}, {"form": "ハイリスク", "label": "派生"}, {"form": "ノーリスク", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 悪い結果が起こる可能性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: スタグフレーション (Zipf 1.93)','sentence 3 above tier T2: 4 words above tier T2 (max 3): 絶えず (Zipf 3.47), イノベーション (Zipf 3.6), 突発 (Zipf 3.44), 顕現 (Zipf 2.9)','sentence 4 above tier T2: contains vocabulary far above tier T2: 萌芽 (Zipf 2.48)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35859, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "そのものが本来持っている、最も重要で基本的な性質。", "primary_collocate": null, "pronunciation": "ほんしつ", "ipa": "hoɴɕitsɯ", "syllable_count": 4, "sentences": [{"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ", "sentence_source": "mined"}, {"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ", "sentence_source": "mined"}, {"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ", "sentence_source": "mined"}, {"text": "それこそが、静謐な自宅の工房において初学者が向き合う、ロボット製作の本質である。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ", "sentence_source": "mined"}, {"text": "問題の本質を考えてみよう。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ", "sentence_source": "generated"}, {"text": "彼は話の本質をすぐに見抜いた。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ", "sentence_source": "generated"}, {"text": "友情の本質は信頼だと思う。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ", "sentence_source": "generated"}, {"text": "本質が見えないと答えは出ない。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ", "sentence_source": "generated"}, {"text": "この本は学びの本質を教えてくれる。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ", "sentence_source": "generated"}, {"text": "本質的な違いはどこにあるのか。", "target_word": "本質", "complexity_tier": "T3", "furigana": "ほんしつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "本質的", "label": "派生"}, {"form": "本質的な", "label": "派生"}, {"form": "本質論", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の最も根本的な性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 愉楽 (Zipf 1.65)','sentence 2 above tier T3: 7 words above tier T3 (max 3): モデリング (Zipf 3.39), 仕立て屋 (Zipf 2.64), 矜持 (Zipf 2.79), 温もり (Zipf 3.24), 冷徹 (Zipf 3.22), 絶え間 (Zipf 3.08)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
