INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52248, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "静かで落ち着いていること。物音がなく、心が安らぐ様子。", "primary_collocate": null, "pronunciation": "せいひつ", "ipa": "seːhitsɯ", "syllable_count": 4, "sentences": [{"text": "我々成人が往々にして見落とす、静謐なる成長の過程を、彼はただ純粋な慈愛をもって見守っているのだ。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "せいひつ", "sentence_source": "mined"}, {"text": "真実を解き明かすための静謐かつ論理的なプロセス、それこそが指紋分析の真髄と言えよう。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "せいひつ", "sentence_source": "mined"}, {"text": "それこそが、静謐な自宅の工房において初学者が向き合う、ロボット製作の本質である。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "せいひつ", "sentence_source": "mined"}, {"text": "静謐な工房において、作り手は野生酵母と乳酸菌の共生するサワードウの種起こしから営為を開始する。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "せいひつ", "sentence_source": "mined"}, {"text": "朝の寺は静謐な空気に満ちていた。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "せいひつ", "sentence_source": "generated"}, {"text": "森の中はとても静謐だった。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "せいひつ", "sentence_source": "generated"}, {"text": "静謐な湖を見て心が落ち着いた。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "せいひつ", "sentence_source": "generated"}, {"text": "図書館の静謐さが好きだ。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "せいひつ", "sentence_source": "generated"}, {"text": "夜の町は静謐に包まれている。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "せいひつ", "sentence_source": "generated"}, {"text": "静謐な時間を大切にしたい。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "せいひつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "静謐な", "label": "活用"}, {"form": "静謐に", "label": "活用"}, {"form": "静謐だ", "label": "活用"}, {"form": "静謐さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 静かで穏やかに落ち着いたさま", "collocate_groun