INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35705, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある結果に至るまでの、一連の流れや段階。", "primary_collocate": null, "pronunciation": "かてい", "ipa": "katei", "syllable_count": 3, "sentences": [{"text": "我々成人が往々にして見落とす、静謐なる成長の過程を、彼はただ純粋な慈愛をもって見守っているのだ。", "target_word": "過程", "complexity_tier": "T3", "furigana": "かてい", "sentence_source": "mined"}, {"text": "その過程は、微生物を培養する「種起こし」から始まります。", "target_word": "過程", "complexity_tier": "T3", "furigana": "かてい", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "過程", "complexity_tier": "T3", "furigana": "かてい", "sentence_source": "mined"}, {"text": "やがて成長の過程において、植物は時折厳しい気候に晒されながらも、力強く茎を伸ばしていく。", "target_word": "過程", "complexity_tier": "T3", "furigana": "かてい", "sentence_source": "mined"}, {"text": "結果より過程が大切だ。", "target_word": "過程", "complexity_tier": "T3", "furigana": "かてい", "sentence_source": "generated"}, {"text": "練習の過程で多くを学んだ。", "target_word": "過程", "complexity_tier": "T3", "furigana": "かてい", "sentence_source": "generated"}, {"text": "パンができる過程を見学した。", "target_word": "過程", "complexity_tier": "T3", "furigana": "かてい", "sentence_source": "generated"}, {"text": "考えた過程をノートに書こう。", "target_word": "過程", "complexity_tier": "T3", "furigana": "かてい", "sentence_source": "generated"}, {"text": "その過程は思ったより長かった。", "target_word": "過程", "complexity_tier": "T3", "furigana": "かてい", "sentence_source": "generated"}, {"text": "失敗も成長の過程の一つだ。", "target_word": "過程", "complexity_tier": "T3", "furigana": "かてい", "sentence_source": "generated"}], "morphological_forms": [{"form": "過程で", "label": "派生"}, {"form": "過程を", "label": "派生"}, {"form": "成長過程", "label": "派生"}, {"form": "製造過程", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 結果に至るまでの一連の段階", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 見落とす (Zipf 2.36)','sentence 2 above tier T2: 4 words above tier T2 (max 3): 絶えず (Zipf 3.47), イノベーション (Zipf 3.6), 突発 (Zipf 3.44), 顕現 (Zipf 2.9)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
