, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 往々 (Zipf 3.12), 見落とす (Zipf 2.36), 静謐 (Zipf 2.66), 慈愛 (Zipf 3.0)','sentence 1 above tier T3: 6 words above tier T3 (max 3): 打算 (Zipf 2.82), 人為 (Zipf 3.32), 介在 (Zipf 2.95), 渇望 (Zipf 2.92), 眼前 (Zipf 2.87), 事物 (Zipf 2.75)','sentence 2 above tier T3: 4 words above tier T3 (max 3): 木漏れ日 (Zipf 2.6), 照らす (Zipf 3.37), 黙々と (Zipf 3.25), 一体化 (Zipf 3.35)','sentence 4 above tier T3: 4 words above tier T3 (max 3): 厳冬 (Zipf 2.45), 冷た (Zipf 3.17), 介さ (Zipf 3.09), 余念 (Zipf 2.8)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52132, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地球や星、銀河など、すべての天体を含む広大な空間。", "primary_collocate": null, "pronunciation": "うちゅう", "ipa": "ɯtɕɯː", "syllable_count": 3, "sentences": [{"text": "鉢という限定された宇宙の中で、命は水という恩恵を糧に、時を重ねてその緑を深めていく。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "うちゅう", "sentence_source": "mined"}, {"text": "裏庭の片隅に設えられた僅かな土塊、すなわち小さな花壇は、幼き子にとって広大な宇宙の縮図であった。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "うちゅう", "sentence_source": "mined"}, {"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "うちゅう", "sentence_source": "mined"}, {"text": "その姿は、まさに宇宙の摂理そのものを体現しているかのようであった。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "うちゅう", "sentence_source": "mined"}, {"text": "いつか宇宙へ行ってみたい。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "うちゅう", "sentence_source": "generated"}, {"text": "宇宙には多くの星がある。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "うちゅう", "sentence_source": "generated"}, {"text": "宇宙はとても広いと思う。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "うちゅう", "sentence_source": "generated"}, {"text": "彼は宇宙の本を読んでいる。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "うちゅう", "sentence_source": "generated"}, {"text": "宇宙から見た地球は青い。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "うちゅう", "sentence_source": "generated"}, {"text": "宇宙の始まりについて学んだ。", "target_word": "宇宙", "complexity_tier": "T3", "furigana": "うちゅう", "sentence_source": "generated"}], "morphological_forms": [{"form": "宇宙人", "label": "派生"}, {"form": "宇宙船", "label": "派生"}, {"form": "宇宙飛行士", "label": "派生"}, {"form": "宇宙的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | すべての天体を含む広大な空間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 設え (Zipf 2.0), 土塊 (Zipf 1.72)','sentence 2 above tier T2: contains vocabulary far above tier T2: 描き出す (Zipf 2.48)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37073, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "それぞれの人や物を、一つ一つ別々に指す言葉。", "primary_collocate": null, "pronunciation": "ここ", "ipa": "ko̞ko̞", "syllable_count": 2, "sentences": [{"text": "大学教育の現場において、教授陣が個々の学修到達度を最大化するためにこのシステムを如何に設計し、運用するかが問われているのである。", "target_word": "個々", "complexity_tier": "T3", "furigana": "ここ", "sentence_source": "mined"}, {"text": "このような活動は、個々の企業利益だけでなく、社会全体の経済発展を牽引する原動力ともなっている。", "target_word": "個々", "complexity_tier": "T3", "furigana": "ここ", "sentence_source": "mined"}, {"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "個々", "complexity_tier": "T3", "furigana": "ここ", "sentence_source": "mined"}, {"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "個々", "complexity_tier": "T3", "furigana": "ここ", "sentence_source": "mined"}, {"text": "個々の意見を大切にしよう。", "target_word": "個々", "complexity_tier": "T3", "furigana": "ここ の いけん たいせつ", "sentence_source": "generated"}, {"text": "先生は個々の生徒を見ている。", "target_word": "個々", "complexity_tier": "T3", "furigana": "ここ せんせい せいと み", "sentence_source": "generated"}, {"text": "個々に話を聞いてみた。", "target_word": "個々", "complexity_tier": "T3", "furigana": "ここ はなし き", "sentence_source": "generated"}, {"text": "個々の力は小さいです。", "target_word": "個々", "complexity_tier": "T3", "furigana": "ここ ちから ちい", "sentence_source": "generated"}, {"text": "問題の中身は個々に違っている。", "target_word": "個々", "complexity_tier": "T3", "furigana": "ここ もんだい なかみ ちが", "sentence_source": "generated"}, {"text": "個々が努力すれば、チームは強くなる。", "target_word": "個々", "complexity_tier": "T3", "furigana": "ここ どりょく つよ", "sentence_source": "generated"}], "morphological_forms": [{"form": "個々人", "label": "派生"}, {"form": "個々別々", "label": "派生"}, {"form": "個々の", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 一つ一つ別々のもの・人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: 4 words above tier T3 (max 3): サプライ (Zipf 3.19), ミクロ (Zipf 3.34), 局所 (Zipf 3.35), 線形 (Zipf 2.97)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36341, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "時間や力などの無駄が少なく、うまく成果を出せる度合い。", "primary_collocate": null, "pronunciation": "こうりつ", "ipa": "ko̞ːɾʲitsɯ", "syllable_count": 4, "sentences": [{"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "効率", "complexity_tier": "T3", "furigana": "こうりつ", "sentence_source": "mined"}, {"text": "この効率的な生産システムは、私たちの食生活を支える基盤となっているのです。", "target_word": "効率", "complexity_tier": "T3", "furigana": "こうりつ", "sentence_source": "mined"}, {"text": "また、限られた環境で効率的に生産を行う「資源管理」の観点からも、持続可能な食料供給の実現において重要な役割を果たしています。", "target_word": "効率", "complexity_tier": "T3", "furigana": "こうりつ", "sentence_source": "mined"}, {"text": "現代の商業的なベーキングにおいては往々にして画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "効率", "complexity_tier": "T3", "furigana": "こうりつ", "sentence_source": "mined"}, {"text": "この方法は効率がいい。", "target_word": "効率", "complexity_tier": "T3", "furigana": "こうりつ ほうほう", "sentence_source": "generated"}, {"text": "効率を考えて、順番を決めた。", "target_word": "効率", "complexity_tier": "T3", "furigana": "こうりつ かんが じゅんばん き", "sentence_source": "generated"}, {"text": "新しい機械で効率が上がった。", "target_word": "効率", "complexity_tier": "T3", "furigana": "こうりつ あたら きかい あ", "sentence_source": "generated"}, {"text": "勉強の効率を高めたい。", "target_word": "効率", "complexity_tier": "T3", "furigana": "こうりつ べんきょう たか", "sentence_source": "generated"}, {"text": "効率よく掃除をしている。", "target_word": "効率", "complexity_tier": "T3", "furigana": "こうりつ そうじ", "sentence_source": "generated"}, {"text": "効率だけでは決められない。", "target_word": "効率", "complexity_tier": "T3", "furigana": "こうりつ き", "sentence_source": "generated"}], "morphological_forms": [{"form": "効率的", "label": "派生"}, {"form": "効率化", "label": "派生"}, {"form": "効率性", "label": "派生"}, {"form": "非効率", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 無駄なく成果を出す度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ベーキング (Zipf 1.24), 極致 (Zipf 2.48)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35785, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の大切さや役に立つ程度。", "primary_collocate": null, "pronunciation": "かち", "ipa": "kat͡ɕi", "syllable_count": 2, "sentences": [{"text": "変化に適応し、自らの価値を高め続ける姿勢が、これからの職場では強く求められる。", "target_word": "価値", "complexity_tier": "T3", "furigana": "かち", "sentence_source": "mined"}, {"text": "単なる出資にとどまらず、経営戦略やネットワークを提供することで、市場に新たな価値を生むイノベーションを加速させるのだ。", "target_word": "価値", "complexity_tier": "T3", "furigana": "かち", "sentence_source": "mined"}, {"text": "しかし、その無骨な外観や維持管理の難しさから、現在ではその価値が再評価される一方で、取り壊されるケースも増えています。", "target_word": "価値", "complexity_tier": "T3", "furigana": "かち", "sentence_source": "mined"}, {"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "価値", "complexity_tier": "T3", "furigana": "かち", "sentence_source": "mined"}, {"text": "この本は読む価値がある。", "target_word": "価値", "complexity_tier": "T3", "furigana": "かち ほん よ", "sentence_source": "generated"}, {"text": "古い時計の価値を調べた。", "target_word": "価値", "complexity_tier": "T3", "furigana": "かち ふる とけい しら", "sentence_source": "generated"}, {"text": "友情の価値は大きい。", "target_word": "価値", "complexity_tier": "T3", "furigana": "かち ゆうじょう おお", "sentence_source": "generated"}, {"text": "その絵は価値が高いそうだ。", "target_word": "価値", "complexity_tier": "T3", "furigana": "かち え たか", "sentence_source": "generated"}, {"text": "価値のある経験ができた。", "target_word": "価値", "complexity_tier": "T3", "furigana": "かち けいけん", "sentence_source": "generated"}, {"text": "時間の価値を考えてみよう。", "target_word": "価値", "complexity_tier": "T3", "furigana": "かち じかん かんが", "sentence_source": "generated"}], "morphological_forms": [{"form": "価値観", "label": "派生"}, {"form": "付加価値", "label": "派生"}, {"form": "無価値", "label": "派生"}, {"form": "価値ある", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の大切さや有用性の程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 4 words above tier T1 (max 2): 出資 (Zipf 3.93), とどまら (Zipf 3.23), 生む (Zipf 3.79), イノベーション (Zipf 3.6)','sentence 2 above tier T1: 3 words above tier T1 (max 2): 無骨 (Zipf 2.69), 外観 (Zipf 3.94), 取り壊さ (Zipf 2.81)','sentence 3 above tier T1: contains vocabulary far above tier T1: アペラシオン (Zipf 1.01)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51472, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "細かいところまで注意が行き届いていて、手抜かりがないさま。", "primary_collocate": null, "pronunciation": "ちみつ", "ipa": "t͡ɕimʲit͡sɯ", "syllable_count": 3, "sentences": [{"text": "天然酵母を用いた製パンは、職人の緻密な管理が不可欠な工程です。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "ちみつ", "sentence_source": "mined"}, {"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "ちみつ", "sentence_source": "mined"}, {"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "ちみつ", "sentence_source": "mined"}, {"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "ちみつ", "sentence_source": "mined"}, {"text": "彼は緻密な計画を立てた。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "ちみつ かれ けいかく た", "sentence_source": "generated"}, {"text": "緻密に調べて、答えを見つけた。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "ちみつ しら こた み", "sentence_source": "generated"}, {"text": "この絵はとても緻密だ。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "ちみつ え", "sentence_source": "generated"}, {"text": "緻密な作業が得意です。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "ちみつ さぎょう とくい", "sentence_source": "generated"}, {"text": "彼女の説明は緻密で分かりやすい。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "ちみつ かのじょ せつめい わ", "sentence_source": "generated"}, {"text": "緻密さが足りないと言われた。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "ちみつ た い", "sentence_source": "generated"}], "morphological_forms": [{"form": "緻密な", "label": "活用"}, {"form": "緻密に", "label": "活用"}, {"form": "緻密だ", "label": "活用"}, {"form": "緻密さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 細部まで注意が行き届くさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35221, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "特定の技術を身につけ、手作業で物を作ることを仕事にする人。", "primary_collocate": null, "pronunciation": "しょくにん", "ipa": "ɕo̞kɯɲĩɴ", "syllable_count": 4, "sentences": [{"text": "天然酵母を用いた製パンは、職人の緻密な管理が不可欠な工程です。", "target_word": "職人", "complexity_tier": "T3", "furigana": "しょくにん", "sentence_source": "mined"}, {"text": "ベル・エポック期、アトリエにおける職人の手指による精緻な刺繍とドレープは、身体を包み込む芸術として確立された。", "target_word": "職人", "complexity_tier": "T3", "furigana": "しょくにん", "sentence_source": "mined"}, {"text": "しかし現代ファッションの文脈では、この伝統的な職人技はデジタルデザインという新たなパラダイムと衝突し、あるいは融合しつつある。", "target_word": "職人", "complexity_tier": "T3", "furigana": "しょくにん", "sentence_source": "mined"}, {"text": "特に多色印刷の場合、色ごとに異なる版木を使い分ける必要があり、職人たちの高度な技術と協力が不可欠です。", "target_word": "職人", "complexity_tier": "T3", "furigana": "しょくにん", "sentence_source": "mined"}, {"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "職人", "complexity_tier": "T3", "furigana": "しょくにん", "sentence_source": "mined"}, {"text": "単なるパンを焼き上げるという行為の域を超え、そこには古の製法への畏敬の念と、素材の潜在能力を限界まで引き出そうとする職人としての揺るぎない覚悟が、静かに宿っていたのである。", "target_word": "職人", "complexity_tier": "T3", "furigana": "しょくにん", "sentence_source": "mined"}, {"text": "祖父は家具の職人だった。", "target_word": "職人", "complexity_tier": "T3", "furigana": "しょくにん そふ かぐ", "sentence_source": "generated"}, {"text": "職人が手で器を作っている。", "target_word": "職人", "complexity_tier": "T3", "furigana": "しょくにん て うつわ つく", "sentence_source": "generated"}, {"text": "職人になるのは大変だ。", "target_word": "職人", "complexity_tier": "T3", "furigana": "しょくにん たいへん", "sentence_source": "generated"}, {"text": "あの職人の技はすごい。", "target_word": "職人", "complexity_tier": "T3", "furigana": "しょくにん わざ", "sentence_source": "generated"}], "morphological_forms": [{"form": "職人技", "label": "派生"}, {"form": "職人気質", "label": "派生"}, {"form": "職人芸", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 手作業で物を作る技術者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: ドレープ (Zipf 1.9)','sentence 4 above tier T3: contains vocabulary far above tier T3: 張り詰める (Zipf 1.07)','sentence 5 above tier T3: 5 words above tier T3 (max 3): 焼き上げる (Zipf 2.14), 畏敬 (Zipf 2.76), 引き出そ (Zipf 2.49), 揺るぎない (Zipf 2.86), 宿っ (Zipf 3.16)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39705, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を最後までやり遂げて、完全な状態にすること。", "primary_collocate": null, "pronunciation": "かんせい", "ipa": "kaɰ̃seː", "syllable_count": 4, "sentences": [{"text": "一連の科学的な変化を経て、風味豊かなパンが完成するのです。", "target_word": "完成", "complexity_tier": "T3", "furigana": "かんせい", "sentence_source": "mined"}, {"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "完成", "complexity_tier": "T3", "furigana": "かんせい", "sentence_source": "mined"}, {"text": "最終的に、その雰囲気を取り入れた、木漏れ日が差し込む開放的な小屋が完成し、家族の新たな憩いの場となった。", "target_word": "完成", "complexity_tier": "T3", "furigana": "かんせい", "sentence_source": "mined"}, {"text": "こうして、一枚の絵画が完成します。", "target_word": "完成", "complexity_tier": "T3", "furigana": "かんせい", "sentence_source": "mined"}, {"text": "やっと模型が完成した。", "target_word": "完成", "complexity_tier": "T3", "furigana": "かんせい もけい", "sentence_source": "generated"}, {"text": "新しい橋は来年完成する。", "target_word": "完成", "complexity_tier": "T3", "furigana": "かんせい あたら はし らいねん", "sentence_source": "generated"}, {"text": "完成までに三か月かかった。", "target_word": "完成", "complexity_tier": "T3", "furigana": "かんせい さん げつ", "sentence_source": "generated"}, {"text": "完成した絵をみんなに見せた。", "target_word": "完成", "complexity_tier": "T3", "furigana": "かんせい え み", "sentence_source": "generated"}, {"text": "ビルの完成を楽しみにしている。", "target_word": "完成", "complexity_tier": "T3", "furigana": "かんせい たの", "sentence_source": "generated"}, {"text": "作品の完成が近づいている。", "target_word": "完成", "complexity_tier": "T3", "furigana": "かんせい さくひん ちか", "sentence_source": "generated"}], "morphological_forms": [{"form": "完成する", "label": "派生"}, {"form": "完成品", "label": "派生"}, {"form": "未完成", "label": "派生"}, {"form": "完成度", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 最後まで仕上がること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 切片 (Zipf 1.86)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35151, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自然や社会の仕組みを、観察や実験に基づいて体系的に説明しようとする知識や活動。", "primary_collocate": null, "pronunciation": "かがく", "ipa": "kaɡakɯ", "syllable_count": 3, "sentences": [{"text": "一連の科学的な変化を経て、風味豊かなパンが完成するのです。", "target_word": "科学", "complexity_tier": "T5", "furigana": "かがく", "sentence_source": "mined"}, {"text": "犯罪現場という苛烈な情報の奔流の中から、科学捜査の担い手は微細な痕跡を拾い上げる。", "target_word": "科学", "complexity_tier": "T6", "furigana": "かがく", "sentence_source": "mined"}, {"text": "いかなる偽装も、この厳密な科学的検証の前には無力化されるほかない。", "target_word": "科学", "complexity_tier": "T6", "furigana": "かがく", "sentence_source": "mined"}, {"text": "この際、脂質の膜がジャムの水分浸透を防ぐバリアーとして機能するという科学的裏付けも無視できない。", "target_word": "科学", "complexity_tier": "T6", "furigana": "かがく", "sentence_source": "mined"}, {"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "科学", "complexity_tier": "T6", "furigana": "かがく", "sentence_source": "mined"}, {"text": "兄は大学で科学を学んでいる。", "target_word": "科学", "complexity_tier": "T3", "furigana": "あに だいがく かがく まな", "sentence_source": "generated"}, {"text": "科学が進んで、生活が便利になった。", "target_word": "科学", "complexity_tier": "T3", "furigana": "かがく すす せいかつ べんり", "sentence_source": "generated"}, {"text": "私は科学の本を読むのが好きだ。", "target_word": "科学", "complexity_tier": "T3", "furigana": "わたし かがく ほん よ す", "sentence_source": "generated"}, {"text": "科学の力で病気を治せるようになった。", "target_word": "科学", "complexity_tier": "T3", "furigana": "かがく ちから びょうき なお", "sentence_source": "generated"}, {"text": "彼女の夢は科学者になることだ。", "target_word": "科学", "complexity_tier": "T3", "furigana": "かのじょ ゆめ かがくしゃ", "sentence_source": "generated"}], "morphological_forms": [{"form": "科学的", "label": "派生"}, {"form": "科学者", "label": "派生"}, {"form": "自然科学", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 観察や実験に基づく体系的な知識", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 奔流 (Zipf 2.32), 拾い上げる (Zipf 2.14)','sentence 4 above tier T2: 7 words above tier T2 (max 3): 水温 (Zipf 3.22), 室温 (Zipf 3.3), 小麦粉 (Zipf 3.59), 混ぜ合わ (Zipf 2.89), 微生物 (Zipf 3.52), 育む (Zipf 3.02)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41315, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小麦粉を水や酵母などで練り、発酵させて焼いた食べ物。", "primary_collocate": null, "pronunciation": "ぱん", "ipa": "paɴ", "syllable_count": 2, "sentences": [{"text": "天然酵母を用いた製パンは、職人の緻密な管理が不可欠な工程です。", "target_word": "パン", "complexity_tier": "T5", "furigana": "てんねんこうぼ もち せい しょくにん ちみつ かんり ふかけつ こうてい", "sentence_source": "mined"}, {"text": "一連の科学的な変化を経て、風味豊かなパンが完成するのです。", "target_word": "パン", "complexity_tier": "T5", "furigana": "いちれん かがくてき へんか へ ふうみゆた かんせい", "sentence_source": "mined"}, {"text": "まず、良質な全粒粉のパンを用意し、その多孔質な表面にピーナッツバターを均一に塗る。", "target_word": "パン", "complexity_tier": "T6", "furigana": "りょうしつ ぜんりゅうふん ようい たこうしつ ひょうめん きんいつ ぬ", "sentence_source": "mined"}, {"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "パン", "complexity_tier": "T6", "furigana": "しゅぎょう とじょう わか しょくにん よあ まえ りん くうき は つ やせい こうぼ お びさい げきてき かがくはんのう もくもく かくとう", "sentence_source": "mined"}, {"text": "単なるパンを焼き上げるという行為の域を超え、そこには古の製法への畏敬の念と、素材の潜在能力を限界まで引き出そうとする職人としての揺るぎない覚悟が、静かに宿っていたのである。", "target_word": "パン", "complexity_tier": "T6", "furigana": "たん や あ こうい いき こ いにしえ せいほう いけい ねん そざい せんざいのうりょく げんかい ひ だ しょくにん ゆ かくご しず やど", "sentence_source": "mined"}, {"text": "数日かけて培養されたルヴァン種は、独特の酸味と芳醇な香りを纏い、パンの骨格を形成する。", "target_word": "パン", "complexity_tier": "T6", "furigana": "すうじつ ばいよう だね どくとく さんみ ほうじゅん かお まと こっかく けいせい", "sentence_source": "mined"}, {"text": "毎朝、パンと牛乳を食べている。", "target_word": "パン", "complexity_tier": "T3", "furigana": "まいあさ ぎゅうにゅう た", "sentence_source": "generated"}, {"text": "駅前のパン屋はいつも混んでいる。", "target_word": "パン", "complexity_tier": "T3", "furigana": "えきまえ や こ", "sentence_source": "generated"}, {"text": "焼きたてのパンはとてもおいしい。", "target_word": "パン", "complexity_tier": "T3", "furigana": "や", "sentence_source": "generated"}, {"text": "母がパンを二枚焼いてくれた。", "target_word": "パン", "complexity_tier": "T3", "furigana": "はは にまい や", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "助数詞"}, {"form": "個", "label": "助数詞"}, {"form": "パン屋", "label": "派生"}, {"form": "食パン", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 小麦粉を発酵させて焼いた食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 全粒粉 (Zipf 2.32), 多孔 (Zipf 2.46)','sentence 3 above tier T2: contains vocabulary far above tier T2: 張り詰める (Zipf 1.07)','sentence 4 above tier T2: contains vocabulary far above tier T2: 焼き上げる (Zipf 2.14), 引き出そ (Zipf 2.49)','sentence 5 above tier T2: 5 words above tier T2 (max 3): 培養 (Zipf 3.6), ルヴァン (Zipf 2.53), 酸味 (Zipf 3.39), 芳醇 (Zipf 2.57), 纏い (Zipf 2.78)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36343, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事がうまく進むように、計画や方法にしたがって状態を整え、コントロールすること。", "primary_collocate": null, "pronunciation": "かんり", "ipa": "kaɴɾi", "syllable_count": 3, "sentences": [{"text": "天然酵母を用いた製パンは、職人の緻密な管理が不可欠な工程です。", "target_word": "管理", "complexity_tier": "T5", "furigana": "かんり", "sentence_source": "mined"}, {"text": "家禽の一つであり、人間が管理する家畜として、畜産業界で重要な役割を果たしています。", "target_word": "管理", "complexity_tier": "T6", "furigana": "かんり", "sentence_source": "mined"}, {"text": "しかし、その無骨な外観や維持管理の難しさから、現在ではその価値が再評価される一方で、取り壊されるケースも増えています。", "target_word": "管理", "complexity_tier": "T6", "furigana": "かんり", "sentence_source": "mined"}, {"text": "また、限られた環境で効率的に生産を行う「資源管理」の観点からも、持続可能な食料供給の実現において重要な役割を果たしています。", "target_word": "管理", "complexity_tier": "T6", "furigana": "かんり", "sentence_source": "mined"}, {"text": "父は会社でお金の管理をしている。", "target_word": "管理", "complexity_tier": "T3", "furigana": "ちち かいしゃ かね かんり", "sentence_source": "generated"}, {"text": "時間の管理はとても大切だ。", "target_word": "管理", "complexity_tier": "T3", "furigana": "じかん かんり たいせつ", "sentence_source": "generated"}, {"text": "このビルは市が管理している。", "target_word": "管理", "complexity_tier": "T3", "furigana": "し かんり", "sentence_source": "generated"}, {"text": "健康管理のために毎日歩いている。", "target_word": "管理", "complexity_tier": "T3", "furigana": "けんこう かんり まいにち ある", "sentence_source": "generated"}, {"text": "パスワードの管理が苦手だ。", "target_word": "管理", "complexity_tier": "T3", "furigana": "かんり にがて", "sentence_source": "generated"}, {"text": "先生が教室のかぎを管理している。", "target_word": "管理", "complexity_tier": "T3", "furigana": "せんせい きょうしつ かんり", "sentence_source": "generated"}], "morphological_forms": [{"form": "管理する", "label": "派生"}, {"form": "管理者", "label": "派生"}, {"form": "健康管理", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 状態を整えてコントロールすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): 酵母 (Zipf 3.37), 緻密 (Zipf 3.25), 不可欠 (Zipf 3.79), 工程 (Zipf 3.83)','sentence 1 above tier T1: contains vocabulary far above tier T1: 家禽 (Zipf 2.3)','sentence 2 above tier T1: 3 words above tier T1 (max 2): 無骨 (Zipf 2.69), 外観 (Zipf 3.94), 取り壊さ (Zipf 2.81)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35929, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物の端から端までの距離や、物事が続く時間が大きいようす。", "primary_collocate": null, "pronunciation": "ながい", "ipa": "naɡai", "syllable_count": 3, "sentences": [{"text": "革の匂いが漂う暗闇の奥底で、長き眠りについていたそれを引きずり出した瞬間、埃っぽい記憶の粒子が舞い上がる。", "target_word": "長き", "complexity_tier": "T6", "furigana": "なが", "sentence_source": "mined"}, {"text": "中国には、とてもながい城壁があります。", "target_word": "ながい", "complexity_tier": "T2", "furigana": "ちゅうごく じょうへき", "sentence_source": "mined"}, {"text": "長い紐を引くと、馬は元気に走ります。", "target_word": "長い", "complexity_tier": "T2", "furigana": "なが", "sentence_source": "mined"}, {"text": "色褪せた外壁や苔むした庭は、過ぎ去った長い年月を静かに物語っている。", "target_word": "長い", "complexity_tier": "T5", "furigana": "なが", "sentence_source": "mined"}, {"text": "姉の髪はとても長い。", "target_word": "長い", "complexity_tier": "T3", "furigana": "あね かみ なが", "sentence_source": "generated"}, {"text": "夏休みは長くて楽しかった。", "target_word": "長く", "complexity_tier": "T3", "furigana": "なつやす なが たの", "sentence_source": "generated"}, {"text": "校長先生の話が長かった。", "target_word": "長か", "complexity_tier": "T3", "furigana": "こうちょうせんせい はなし なが", "sentence_source": "generated"}, {"text": "長い間、友達に会っていない。", "target_word": "長い", "complexity_tier": "T3", "furigana": "なが あいだ ともだち あ", "sentence_source": "generated"}, {"text": "この川は日本で一番長い。", "target_word": "長い", "complexity_tier": "T3", "furigana": "かわ にほん いちばん なが", "sentence_source": "generated"}, {"text": "冬の夜は長く感じる。", "target_word": "長く", "complexity_tier": "T3", "furigana": "ふゆ よる なが かん", "sentence_source": "generated"}], "morphological_forms": [{"form": "長かった", "label": "活用"}, {"form": "長くて", "label": "活用"}, {"form": "長くない", "label": "活用"}, {"form": "長さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 距離や時間が大きいようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 奥底 (Zipf 3.21), 引きずり出し (Zipf 2.55), 埃 (Zipf 3.54), 舞い上がる (Zipf 2.61)','sentence 3 above tier T2: contains vocabulary far above tier T2: 苔むし (Zipf 1.86)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51608, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "血やトマトのような色をしているようす。", "primary_collocate": null, "pronunciation": "あかい", "ipa": "akai", "syllable_count": 3, "sentences": [{"text": "私がこの赤い靴を履くという行為は、決して寒さ凌ぎの方便ではない。", "target_word": "赤い", "complexity_tier": "T5", "furigana": "あか", "sentence_source": "mined"}, {"text": "課題は自由な「お絵描き」だが、手には短くなった赤いクレヨンが握られている。", "target_word": "赤い", "complexity_tier": "T5", "furigana": "あか", "sentence_source": "mined"}, {"text": "森の奥深くに佇む、その赤いドアの小さな家は、かつて祖母が一人で暮らしていた場所だ。", "target_word": "赤い", "complexity_tier": "T6", "furigana": "あか", "sentence_source": "mined"}, {"text": "秋の気配が色濃く漂う古びた縁側にて、一人の幼子が無心なる眼差しを向けているのは、掌に収められた一つの赤い果物である。", "target_word": "赤い", "complexity_tier": "T6", "furigana": "あか", "sentence_source": "mined"}, {"text": "このりんごはとても赤い。", "target_word": "赤い", "complexity_tier": "T3", "furigana": "あか", "sentence_source": "generated"}, {"text": "寒くて、弟の手が赤くなった。", "target_word": "赤く", "complexity_tier": "T3", "furigana": "さむ おとうと て あか", "sentence_source": "generated"}, {"text": "夕方の空が赤くて美しい。", "target_word": "赤く", "complexity_tier": "T3", "furigana": "ゆうがた そら あか うつく", "sentence_source": "generated"}, {"text": "昨日の夕日は本当に赤かった。", "target_word": "赤か", "complexity_tier": "T3", "furigana": "きのう ゆうひ ほんとう あか", "sentence_source": "generated"}, {"text": "彼女は恥ずかしくて顔が赤い。", "target_word": "赤い", "complexity_tier": "T3", "furigana": "かのじょ は かお あか", "sentence_source": "generated"}, {"text": "赤い花が庭にたくさん咲いている。", "target_word": "赤い", "complexity_tier": "T3", "furigana": "あか はな にわ さ", "sentence_source": "generated"}], "morphological_forms": [{"form": "赤かった", "label": "活用"}, {"form": "赤くて", "label": "活用"}, {"form": "赤くない", "label": "活用"}, {"form": "赤さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 血やトマトのような色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: 7 words above tier T2 (max 3): 色濃く (Zipf 3.13), 古び (Zipf 2.76), 縁側 (Zipf 3.0), 幼子 (Zipf 2.71), 無心 (Zipf 3.09), 眼差し (Zipf 3.38)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38529, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "基準や規則に従って、少しのずれもなく正確であるようす。", "primary_collocate": null, "pronunciation": "げんみつ", "ipa": "ɡeɴmitsɯ", "syllable_count": 4, "sentences": [{"text": "いかなる偽装も、この厳密な科学的検証の前には無力化されるほかない。", "target_word": "厳密", "complexity_tier": "T6", "furigana": "げんみつ", "sentence_source": "mined"}, {"text": "鶏の飼育は、温度や餌が厳密に調整された環境で行われます。", "target_word": "厳密", "complexity_tier": "T5", "furigana": "げんみつ", "sentence_source": "mined"}, {"text": "しかる後に、プログラミングという「神経系」を構築し、抽象的論理と物理的挙動を厳密に同期させるのだ。", "target_word": "厳密", "complexity_tier": "T6", "furigana": "げんみつ", "sentence_source": "mined"}, {"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "厳密", "complexity_tier": "T6", "furigana": "げんみつ", "sentence_source": "mined"}, {"text": "この実験には厳密なルールがある。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "じっけん げんみつ", "sentence_source": "generated"}, {"text": "時間を厳密に守ってください。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "じかん げんみつ まも", "sentence_source": "generated"}, {"text": "厳密に言えば、それは間違いだ。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "げんみつ い まちが", "sentence_source": "generated"}, {"text": "工場では品質の検査が厳密だ。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "こうじょう ひんしつ けんさ げんみつ", "sentence_source": "generated"}, {"text": "先生は採点がとても厳密だ。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "せんせい さいてん げんみつ", "sentence_source": "generated"}, {"text": "厳密な計算で答えを出した。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "げんみつ けいさん こた だ", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳密な", "label": "活用"}, {"form": "厳密に", "label": "活用"}, {"form": "厳密だ", "label": "活用"}, {"form": "厳密さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 少しのずれもなく正確なようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: アペラシオン (Zipf 1.01)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36771, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "相手に知識や情報、物などを与えること。", "primary_collocate": null, "pronunciation": "ていきょう", "ipa": "teːkʲoː", "syllable_count": 4, "sentences": [{"text": "単なる出資にとどまらず、経営戦略やネットワークを提供することで、市場に新たな価値を生むイノベーションを加速させるのだ。", "target_word": "提供", "complexity_tier": "T3", "furigana": "ていきょう", "sentence_source": "mined"}, {"text": "病気を治すために、他の人が提供します。", "target_word": "提供", "complexity_tier": "T3", "furigana": "ていきょう", "sentence_source": "mined"}, {"text": "彼がこれらを大切に育てる理由は、地域の子供たちに安全な給食を安定的に提供するためだ。", "target_word": "提供", "complexity_tier": "T3", "furigana": "ていきょう", "sentence_source": "mined"}, {"text": "特に、初期段階のスタートアップ資金調達を担う彼らの役割は、単なる資本の提供にとどまらない。", "target_word": "提供", "complexity_tier": "T3", "furigana": "ていきょう", "sentence_source": "mined"}, {"text": "この店は無料でお茶を提供している。", "target_word": "提供", "complexity_tier": "T3", "furigana": "みせ むりょう ちゃ ていきょう", "sentence_source": "generated"}, {"text": "情報の提供に感謝します。", "target_word": "提供", "complexity_tier": "T3", "furigana": "じょうほう ていきょう かんしゃ", "sentence_source": "generated"}, {"text": "市が新しい場所を提供してくれた。", "target_word": "提供", "complexity_tier": "T3", "furigana": "し あたら ばしょ ていきょう", "sentence_source": "generated"}, {"text": "提供されたデータを使って調べた。", "target_word": "提供", "complexity_tier": "T3", "furigana": "ていきょう つか しら", "sentence_source": "generated"}, {"text": "会社は社員に昼食を提供している。", "target_word": "提供", "complexity_tier": "T3", "furigana": "かいしゃ しゃいん ちゅうしょく ていきょう", "sentence_source": "generated"}, {"text": "資料の提供をお願いできますか。", "target_word": "提供", "complexity_tier": "T3", "furigana": "しりょう ていきょう ねが", "sentence_source": "generated"}], "morphological_forms": [{"form": "提供する", "label": "派生"}, {"form": "提供者", "label": "派生"}, {"form": "情報提供", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 情報や物を相手に与えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): 出資 (Zipf 3.93), とどまら (Zipf 3.23), 生む (Zipf 3.79), イノベーション (Zipf 3.6)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37779, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人々が技術や感性を使って、美しいものや感動を生み出す活動やその作品。", "primary_collocate": null, "pronunciation": "げいじゅつ", "ipa": "ɡeːʑutsɯ", "syllable_count": 4, "sentences": [{"text": "微生物の代謝作用である発酵は、単なる保存技法の域を超え、主食の持つ潜在能力を飛躍的に拡張する化学的芸術である。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "げいじゅつ", "sentence_source": "mined"}, {"text": "ベル・エポック期、アトリエにおける職人の手指による精緻な刺繍とドレープは、身体を包み込む芸術として確立された。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "げいじゅつ", "sentence_source": "mined"}, {"text": "浮世絵は、日本で発展した独自の工芸であり、世界的に評価される芸術です。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "げいじゅつ", "sentence_source": "mined"}, {"text": "この一連の工程は、自然の摂理と人間の叡智が交差する、紛れもなく芸術的な創造物である。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "げいじゅつ", "sentence_source": "mined"}, {"text": "私は芸術に興味があります。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "わたし げいじゅつ きょうみ", "sentence_source": "generated"}, {"text": "芸術は人の心を動かす。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "げいじゅつ ひと こころ うご", "sentence_source": "generated"}, {"text": "姉は大学で芸術を学んでいる。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "あね だいがく げいじゅつ まな", "sentence_source": "generated"}, {"text": "この町は芸術の町として有名だ。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "まち げいじゅつ まち ゆうめい", "sentence_source": "generated"}, {"text": "音楽も一つの芸術だと思う。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "おんがく ひと げいじゅつ おも", "sentence_source": "generated"}, {"text": "芸術の秋に美術館へ行った。", "target_word": "芸術", "complexity_tier": "T3", "furigana": "げいじゅつ あき びじゅつかん い", "sentence_source": "generated"}], "morphological_forms": [{"form": "芸術的", "label": "派生"}, {"form": "芸術家", "label": "派生"}, {"form": "芸術作品", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 美や感動を生み出す活動や作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: ドレープ (Zipf 1.9)','sentence 3 above tier T2: 4 words above tier T2 (max 3): 摂理 (Zipf 3.05), 叡智 (Zipf 2.97), 交差 (Zipf 3.55), 紛れ (Zipf 3.68)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42775, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や動物、植物などが成長するように、大切に世話をすること。また、心や能力などを大切に育てること。", "primary_collocate": null, "pronunciation": "はぐくむ", "ipa": "haɡɯkɯmɯ", "syllable_count": 4, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "育む", "complexity_tier": "T3", "furigana": "はぐくむ", "sentence_source": "mined"}, {"text": "不確実性の高い技術的課題に挑む起業家に対し、リスクマネーを供給することで、彼らは市場の失敗を補完し、破壊的なイノベーションの萌芽を育むのである。", "target_word": "育む", "complexity_tier": "T3", "furigana": "はぐくむ", "sentence_source": "mined"}, {"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "育む", "complexity_tier": "T3", "furigana": "はぐくむ", "sentence_source": "mined"}, {"text": "その一つひとつの動作が、彼女の認知能力と社会性を育む養分となる。", "target_word": "育む", "complexity_tier": "T3", "furigana": "はぐくむ", "sentence_source": "mined"}, {"text": "親は子どもを大切に育む。", "target_word": "育む", "complexity_tier": "T3", "furigana": "おや こ はぐく", "sentence_source": "generated"}, {"text": "友情を育むのは時間がかかる。", "target_word": "育む", "complexity_tier": "T3", "furigana": "ゆうじょう はぐく じかん", "sentence_source": "generated"}, {"text": "森が多くの生き物を育んでいる。", "target_word": "育ん", "complexity_tier": "T3", "furigana": "もり おお い もの はぐく", "sentence_source": "generated"}, {"text": "この学校は自由な心を育む場所だ。", "target_word": "育む", "complexity_tier": "T3", "furigana": "がっこう じゆう こころ はぐく ばしょ", "sentence_source": "generated"}, {"text": "豊かな自然に育まれて大きくなった。", "target_word": "育ま", "complexity_tier": "T3", "furigana": "ゆた しぜん はぐく おお", "sentence_source": "generated"}, {"text": "二人は長い間、愛を育んだ。", "target_word": "育ん", "complexity_tier": "T3", "furigana": "ふたり なが あいだ あい はぐく", "sentence_source": "generated"}], "morphological_forms": [{"form": "育んだ", "label": "活用"}, {"form": "育んで", "label": "活用"}, {"form": "育まない", "label": "活用"}, {"form": "育まれる", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 大切に世話をして成長させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41227, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の形や色を、紙などにえがいたもの。", "primary_collocate": "描く", "pronunciation": "え", "ipa": "e", "syllable_count": 1, "sentences": [{"text": "くまの絵がすきです。", "target_word": "絵", "complexity_tier": "T3", "furigana": "え", "sentence_source": "mined"}, {"text": "指先で色を擦り混ぜ、重ね塗りをする技法によって、私は心の中の風景を絵として表現している。", "target_word": "絵", "complexity_tier": "T3", "furigana": "え", "sentence_source": "mined"}, {"text": "そこで、デザインを決める際、子供が自由に描いた絵を参考にすることにした。", "target_word": "絵", "complexity_tier": "T3", "furigana": "え", "sentence_source": "mined"}, {"text": "現実的な設計図とは異なるが、その絵には彼が求める理想の世界が詰まっている。", "target_word": "絵", "complexity_tier": "T3", "furigana": "え", "sentence_source": "mined"}, {"text": "浮世絵は、日本で発展した独自の工芸であり、世界的に評価される芸術です。", "target_word": "絵", "complexity_tier": "T3", "furigana": "え", "sentence_source": "mined"}, {"text": "絵師の描いた下絵を彫師が版木に彫り、摺師が紙に印刷するという複雑な工程を経ます。", "target_word": "絵", "complexity_tier": "T3", "furigana": "え", "sentence_source": "mined"}, {"text": "弟は毎日、犬の絵を描いている。", "target_word": "絵", "complexity_tier": "T3", "furigana": "おとうと まいにち いぬ え か", "sentence_source": "generated"}, {"text": "壁にきれいな絵がかけてある。", "target_word": "絵", "complexity_tier": "T3", "furigana": "かべ え", "sentence_source": "generated"}, {"text": "この絵は祖母が描いたものだ。", "target_word": "絵", "complexity_tier": "T3", "furigana": "え そぼ か", "sentence_source": "generated"}, {"text": "絵を見ると、心が落ち着く。", "target_word": "絵", "complexity_tier": "T3", "furigana": "え み こころ お つ", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "助数詞"}, {"form": "絵本", "label": "派生"}, {"form": "絵画", "label": "派生"}, {"form": "絵の具", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 紙などに形や色を描いたもの", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 指先 (Zipf 3.6), 擦り (Zipf 3.29), 技法 (Zipf 3.83)','sentence 5 above tier T1: contains vocabulary far above tier T1: 版木 (Zipf 2.03)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51460, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "あることを行ったり経験したりするのが、それが最初であることを表す。", "primary_collocate": null, "pronunciation": "はじめて", "ipa": "haʑimete", "syllable_count": 4, "sentences": [{"text": "金属イオンとの錯体形成を通じて、色は初めてその真の輝きを帯び、生地へと不可逆的に定着するのだ。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "はじ", "sentence_source": "mined"}, {"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "はじ", "sentence_source": "mined"}, {"text": "十代の人が初めてステージに立ちます。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "はじ", "sentence_source": "mined"}, {"text": "初めて海を見たとき、感動した。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "はじ うみ み かんどう", "sentence_source": "generated"}, {"text": "日本に来たのは初めてです。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "にほん き はじ", "sentence_source": "generated"}, {"text": "初めての旅行はとても楽しかった。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "はじ りょこう たの", "sentence_source": "generated"}, {"text": "病気になって初めて健康の大切さを知った。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "びょうき はじ けんこう たいせつ し", "sentence_source": "generated"}, {"text": "妹は今日初めて自転車に乗れた。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "いもうと きょう はじ じてんしゃ の", "sentence_source": "generated"}, {"text": "こんな味は初めてだ。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "あじ はじ", "sentence_source": "generated"}, {"text": "彼と初めて話したのは春だった。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "かれ はじ はな はる", "sentence_source": "generated"}], "morphological_forms": [{"form": "初めての", "label": "派生"}, {"form": "初めまして", "label": "派生"}, {"form": "初め", "label": "派生"}], "register": "plain", "sense_fingerprint": "副詞 | 経験や行為が最初であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 錯体 (Zipf 2.39)','sentence 1 above tier T1: contains vocabulary far above tier T1: 謬 (Zipf 2.26)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38533, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会で行われる正式な手続きや礼儀作法。特に、宗教や伝統に基づく決まった行動様式。", "primary_collocate": null, "pronunciation": "ぎれい", "ipa": "ɡiɾeː", "syllable_count": 3, "sentences": [{"text": "天然染料による染色は、単なる化学的操作の連鎖ではなく、素材と対話する儀礼にも等しい。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "ぎれい", "sentence_source": "mined"}, {"text": "学校イベントという儀礼的空間において、Tシャツデザインは単なる装飾を超え、集団内の微細な階層や個性の顕現として機能し得る。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "ぎれい", "sentence_source": "mined"}, {"text": "それは、確立された安住の地からの離脱であり、新たな社会的文脈における自己の再構築を迫られる、極めて重要な通過儀礼なのである。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "ぎれい", "sentence_source": "mined"}, {"text": "この村には古い儀礼が残っている。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "むら ふる ぎれい のこ", "sentence_source": "generated"}, {"text": "儀礼は地域によって違う。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "ぎれい ちいき ちが", "sentence_source": "generated"}, {"text": "神社で大切な儀礼が行われた。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "じんじゃ たいせつ ぎれい おこな", "sentence_source": "generated"}, {"text": "祖父は儀礼をとても重んじている。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "そふ ぎれい おも", "sentence_source": "generated"}, {"text": "結婚の儀礼について調べた。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "けっこん ぎれい しら", "sentence_source": "generated"}, {"text": "儀礼の意味を先生に聞いた。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "ぎれい いみ せんせい き", "sentence_source": "generated"}, {"text": "その儀礼は百年続いている。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "ぎれい ひゃくねん つづ", "sentence_source": "generated"}], "morphological_forms": [{"form": "儀礼的", "label": "派生"}, {"form": "通過儀礼", "label": "派生"}, {"form": "宗教儀礼", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 伝統に基づく正式な作法や式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36875, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物質の性質や変化、その仕組みを研究する学問。", "primary_collocate": null, "pronunciation": "かがく", "ipa": "kaɡakɯ", "syllable_count": 3, "sentences": [{"text": "天然染料による染色は、単なる化学的操作の連鎖ではなく、素材と対話する儀礼にも等しい。", "target_word": "化学", "complexity_tier": "T3", "furigana": "かがく", "sentence_source": "mined"}, {"text": "微生物の代謝作用である発酵は、単なる保存技法の域を超え、主食の持つ潜在能力を飛躍的に拡張する化学的芸術である。", "target_word": "化学", "complexity_tier": "T3", "furigana": "かがく", "sentence_source": "mined"}, {"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "化学", "complexity_tier": "T3", "furigana": "かがく", "sentence_source": "mined"}, {"text": "姉は大学で化学を勉強している。", "target_word": "化学", "complexity_tier": "T3", "furigana": "かがく", "sentence_source": "generated"}, {"text": "化学の授業はとても楽しい。", "target_word": "化学", "complexity_tier": "T3", "furigana": "かがく", "sentence_source": "generated"}, {"text": "ぼくは化学がちょっと苦手だ。", "target_word": "化学", "complexity_tier": "T3", "furigana": "かがく", "sentence_source": "generated"}, {"text": "化学の先生は実験が好きだ。", "target_word": "化学", "complexity_tier": "T3", "furigana": "かがく", "sentence_source": "generated"}, {"text": "将来は化学の研究者になりたい。", "target_word": "化学", "complexity_tier": "T3", "furigana": "かがく", "sentence_source": "generated"}, {"text": "化学のテストで満点を取れた。", "target_word": "化学", "complexity_tier": "T3", "furigana": "かがく", "sentence_source": "generated"}, {"text": "料理にも化学が関係している。", "target_word": "化学", "complexity_tier": "T3", "furigana": "かがく", "sentence_source": "generated"}], "morphological_forms": [{"form": "化学的", "label": "派生"}, {"form": "化学者", "label": "派生"}, {"form": "化学反応", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物質の性質と変化を研究する学問", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 張り詰める (Zipf 1.07)']::text[], 'bc41e76b-2fc7-42de-aeaa-03ed008d32e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
