INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35677, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事や動作が、順序よく続けて行われるひとまとまり。", "primary_collocate": null, "pronunciation": "いちれん", "ipa": "itɕiɾeɴ", "syllable_count": 4, "sentences": [{"text": "この一連の作業は、移ろいやすい自然の産物を、人間の手によって恒久の美へと昇華させる、高度な技術と美意識の結晶なのである。", "target_word": "一連", "complexity_tier": "T3", "furigana": "いちれん", "sentence_source": "mined"}, {"text": "一連の科学的な変化を経て、風味豊かなパンが完成するのです。", "target_word": "一連", "complexity_tier": "T3", "furigana": "いちれん", "sentence_source": "mined"}, {"text": "この一連の工程は、自然の摂理と人間の叡智が交差する、紛れもなく芸術的な創造物である。", "target_word": "一連", "complexity_tier": "T3", "furigana": "いちれん", "sentence_source": "mined"}, {"text": "一連の事件がニュースになった。", "target_word": "一連", "complexity_tier": "T3", "furigana": "いちれん", "sentence_source": "generated"}, {"text": "一連の動きを何度も練習した。", "target_word": "一連", "complexity_tier": "T3", "furigana": "いちれん", "sentence_source": "generated"}, {"text": "彼は一連の問題を一人で解いた。", "target_word": "一連", "complexity_tier": "T3", "furigana": "いちれん", "sentence_source": "generated"}, {"text": "一連の流れを先生が説明した。", "target_word": "一連", "complexity_tier": "T3", "furigana": "いちれん", "sentence_source": "generated"}, {"text": "一連の出来事に、みんな驚いている。", "target_word": "一連", "complexity_tier": "T3", "furigana": "いちれん", "sentence_source": "generated"}, {"text": "料理の一連の手順を覚えた。", "target_word": "一連", "complexity_tier": "T3", "furigana": "いちれん", "sentence_source": "generated"}, {"text": "一連の試合で彼は活躍した。", "target_word": "一連", "complexity_tier": "T3", "furigana": "いちれん", "sentence_source": "generated"}], "morphological_forms": [{"form": "一連の", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 順につながったひとまとまりの物事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', tr