INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41343, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "新しい事業を始める会社。特に、急成長を目指す小さな会社。", "primary_collocate": null, "pronunciation": "すたーとあっぷ", "ipa": "sɯtaːtoappɯ", "syllable_count": 6, "sentences": [{"text": "スタートアップは、革新的なアイデアを種として創業される。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "ベンチャーキャピタルは、将来性のあるスタートアップへリスクを取って資金調達を行い、その成長を支援する重要な役割を担っている。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "特に、初期段階のスタートアップ資金調達を担う彼らの役割は、単なる資本の提供にとどまらない。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "兄はスタートアップで働いている。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "あに はたら", "sentence_source": "generated"}, {"text": "そのスタートアップは急に成長した。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "きゅう せいちょう", "sentence_source": "generated"}, {"text": "友だちとスタートアップを作りたい。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "とも つく", "sentence_source": "generated"}, {"text": "スタートアップの社長は若い。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "しゃちょう わか", "sentence_source": "generated"}, {"text": "この町には小さなスタートアップが多い。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "まち ちい おお", "sentence_source": "generated"}, {"text": "新しいスタートアップがアプリを出した。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "あたら だ", "sentence_source": "generated"}, {"text": "スタートアップに入るのは楽しそうだ。", "target_word": "スタートアップ", "complexity_tier": "T3", "furigana": "はい たの", "sentence_source": "generated"}], "morphological_forms": [{"form": "社", "label": "助数詞"}, {"form": "スタートアップ企業", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 急成長を目指す新しい小さな会社", "collocate_gro