INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39281, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "感", "is_correct": true, "explanation": "正解：「感」（かん）。"}, {"text": "貝", "is_correct": false, "explanation": "「貝」はかいと読み、「ん」が「い」に変わる一モーラ差。"}, {"text": "紙", "is_correct": false, "explanation": "「紙」はかみと読み、「ん」が「み」に変わる一モーラ差。"}, {"text": "癌", "is_correct": false, "explanation": "「癌」はがんと読み、「か」と「が」の清濁の違い。"}, {"text": "鐘", "is_correct": false, "explanation": "「鐘」はかねと読み、「ん」が「ね」に変わる一モーラ差。"}], "explanations": {"感": "正解：「感」（かん）。", "貝": "「貝」はかいと読み、「ん」が「い」に変わる一モーラ差。", "紙": "「紙」はかみと読み、「ん」が「み」に変わる一モーラ差。", "癌": "「癌」はがんと読み、「か」と「が」の清濁の違い。", "鐘": "「鐘」はかねと読み、「ん」が「ね」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "感"}, "level_3": {"options": [{"text": "感", "is_correct": true, "explanation": "正解：文脈に合う。"}, {"text": "料", "is_correct": false, "explanation": "意味：「存在料」という語はなく、料金を表す接尾辞は文脈に合わない。"}, {"text": "署", "is_correct": false, "explanation": "意味：役所を表す接尾辞で、存在の感じを表さない。"}, {"text": "便", "is_correct": false, "explanation": "連語：「存在便」とは言わず、「増していく」と結びつかない。"}], "explanations": {"感": "正解：文脈に合う。", "料": "意味：「存在料」という語はなく、料金を表す接尾辞は文脈に合わない。", "署": "意味：役所を表す接尾辞で、存在の感じを表さない。", "便": "連語：「存在便」とは言わず、「増していく」と結びつかない。"}, "sentence_index": 0, "correct_answer": "感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は昨日、焦燥感を三冊も買った。", "explanation": "助数詞の誤り：感じや気持ちは数えたり買ったりできない。"}, {"text": "試験の前に不安感をとても食べた。", "explanation": "連語の誤り：気持ちを表す語は「食べる」と結びつかない。"}, {"text": "達成感は明日、もう感じてしまった。", "explanation": "アスペクトの誤り：未来の「明日」と完了の「てしまった」が矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validat