INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36163, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分析", "is_correct": true, "explanation": "正解：「分析」（ぶんせき）。"}, {"text": "胆石", "is_correct": false, "explanation": "「胆石」はたんせきと読み、「ぶ」が「た」に変わる一モーラ差。"}, {"text": "痕跡", "is_correct": false, "explanation": "「痕跡」はこんせきと読み、「ぶ」が「こ」に変わる一モーラ差。"}, {"text": "文節", "is_correct": false, "explanation": "「文節」はぶんせつと読み、「き」が「つ」に変わる一モーラ差。"}, {"text": "噴石", "is_correct": false, "explanation": "「噴石」はふんせきと読み、「ぶ」と「ふ」の清濁の違い。"}], "explanations": {"分析": "正解：「分析」（ぶんせき）。", "胆石": "「胆石」はたんせきと読み、「ぶ」が「た」に変わる一モーラ差。", "痕跡": "「痕跡」はこんせきと読み、「ぶ」が「こ」に変わる一モーラ差。", "文節": "「文節」はぶんせつと読み、「き」が「つ」に変わる一モーラ差。", "噴石": "「噴石」はふんせきと読み、「ぶ」と「ふ」の清濁の違い。"}, "sentence_index": null, "correct_answer": "分析"}, "level_3": {"options": [{"text": "分析", "is_correct": true, "explanation": "正解：文脈に合う。"}, {"text": "笑顔", "is_correct": false, "explanation": "意味：笑顔は正確かどうかを言わない。"}, {"text": "帽子", "is_correct": false, "explanation": "意味：帽子は正確ではありえない。"}, {"text": "声", "is_correct": false, "explanation": "連語：「声が正確」は不自然。"}], "explanations": {"分析": "正解：文脈に合う。", "笑顔": "意味：笑顔は正確かどうかを言わない。", "帽子": "意味：帽子は正確ではありえない。", "声": "連語：「声が正確」は不自然。"}, "sentence_index": 6, "correct_answer": "分析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分析を二冊した。", "explanation": "助数詞の誤り：分析は「冊」で数えない。"}, {"text": "彼は人の気持ちの分析で得意だ。", "explanation": "助詞の誤り：「分析が得意だ」が正しい。"}, {"text": "昨日、分析するつもりだ。", "explanation": "アスペクトの誤り：「昨日」と予定が矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
