INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35851, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ネットワーク", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "フットワーク", "is_correct": false, "explanation": "ふっとわーく。語頭の「ネッ」が「フッ」に変わる。"}, {"text": "ネットワーカー", "is_correct": false, "explanation": "ねっとわーかー。語末に「カー」が加わる。"}, {"text": "ハードワーク", "is_correct": false, "explanation": "はーどわーく。前半の音が異なる。"}], "explanations": {"ネットワーク": "音声どおりの正しい表記。", "フットワーク": "ふっとわーく。語頭の「ネッ」が「フッ」に変わる。", "ネットワーカー": "ねっとわーかー。語末に「カー」が加わる。", "ハードワーク": "はーどわーく。前半の音が異なる。"}, "sentence_index": null, "correct_answer": "ネットワーク"}, "level_3": {"options": [{"text": "ネットワーク", "is_correct": true, "explanation": "緑地どうしが結びついて形成する「つながり」を表す。"}, {"text": "スケジュール", "is_correct": false, "explanation": "意味：緑地が形成するものとして意味が通らない。"}, {"text": "アンケート", "is_correct": false, "explanation": "意味：緑地と有機的に形成するものではない。"}, {"text": "マニュアル", "is_correct": false, "explanation": "連語：「マニュアルを形成する」とは言わない。"}], "explanations": {"ネットワーク": "緑地どうしが結びついて形成する「つながり」を表す。", "スケジュール": "意味：緑地が形成するものとして意味が通らない。", "アンケート": "意味：緑地と有機的に形成するものではない。", "マニュアル": "連語：「マニュアルを形成する」とは言わない。"}, "sentence_index": 0, "correct_answer": "ネットワーク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ネットワークを一冊買って読んだ。", "explanation": "助数詞の誤り：ネットワークは本ではないので「一冊」で数えない。"}, {"text": "パソコンをネットワークをつないだ。", "explanation": "助詞の混同：つなぐ先は「に」で示す（ネットワークにつないだ）。"}, {"text": "昨日ネットワークを広げている。", "explanation": "アスペクトの誤り：「昨日」には「広げた」が必要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
