INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35851, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「提供する」の目的語を示す。"}, {"text": "の", "is_correct": false, "explanation": "「ネットワークの提供する」となり、動詞の目的語を示せず非文。"}, {"text": "と", "is_correct": false, "explanation": "「経営戦略やネットワークと提供する」は並列が崩れ不自然。"}, {"text": "か", "is_correct": false, "explanation": "「や」と「か」が混在し、目的語も示されず非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「提供する」の目的語を示す。", "の": "「ネットワークの提供する」となり、動詞の目的語を示せず非文。", "と": "「経営戦略やネットワークと提供する」は並列が崩れ不自然。", "か": "「や」と「か」が混在し、目的語も示されず非文。"}, "error_tags": {"の": "object_marking", "と": "other", "か": "other"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
