INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35851, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「役に立つ」の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「役に立つ」は他動詞でないので目的語を取らない。"}, {"text": "と", "is_correct": false, "explanation": "「ネットワークと役に立った」は主語を示せず非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、この位置では非文。"}], "correct_answer": "が", "explanations": {"が": "「役に立つ」の主語を示す格助詞。", "を": "「役に立つ」は他動詞でないので目的語を取らない。", "と": "「ネットワークと役に立った」は主語を示せず非文。", "へ": "方向を表し、この位置では非文。"}, "error_tags": {"を": "object_marking", "と": "other", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36933, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "近年", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "記念", "is_correct": false, "explanation": "きねん。「ん」が一つ抜ける。"}, {"text": "禁煙", "is_correct": false, "explanation": "きんえん。「ね」が「え」に変わる。"}, {"text": "新年", "is_correct": false, "explanation": "しんねん。「き」が「し」に変わる。"}, {"text": "金言", "is_correct": false, "explanation": "きんげん。「ね」が「げ」に変わる。"}], "explanations": {"近年": "音声どおりの正しい表記。", "記念": "きねん。「ん」が一つ抜ける。", "禁煙": "きんえん。「ね」が「え」に変わる。", "新年": "しんねん。「き」が「し」に変わる。", "金言": "きんげん。「ね」が「げ」に変わる。"}, "sentence_index": null, "correct_answer": "近年"}, "level_3": {"options": [{"text": "近年", "is_correct": true, "explanation": "ここ数年の傾向を述べる文頭の時の語。"}, {"text": "昨夜", "is_correct": false, "explanation": "意味：一晩の出来事では「各地で顕在化している」傾向に合わない。"}, {"text": "来年", "is_correct": false, "explanation": "アスペクト：未来の語は「している」と合わない。"}, {"text": "将来", "is_correct": false, "explanation": "アスペクト：未来を指し、現在進行の傾向と不整合。"}], "explanations": {"近年": "ここ数年の傾向を述べる文頭の時の語。", "昨夜": "意味：一晩の出来事では「各地で顕在化している」傾向に合わない。", "来年": "アスペクト：未来の語は「している」と合わない。", "将来": "アスペクト：未来を指し、現在進行の傾向と不整合。"}, "sentence_index": 0, "correct_answer": "近年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近年が、理論は重要な基盤となりつつあります。", "explanation": "助詞の混同：時を表す「近年」に「が」は付かない。"}, {"text": "近年の、理論は重要な基盤となりつつあります。", "explanation": "助詞の誤り：「近年の」は名詞を修飾する形で、文頭の副詞的用法には使えない。"}, {"text": "近年を理論が重要な基盤となりつつあります。", "explanation": "助詞の混同：「近年」に「を」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
