INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36933, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「もたらす」の相手（着点）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「もたらす」の目的語は既に「可能性を」なので重複して非文。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を表し、相手を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、文意が逆になる。"}], "correct_answer": "に", "explanations": {"に": "「もたらす」の相手（着点）を示す。", "を": "「もたらす」の目的語は既に「可能性を」なので重複して非文。", "で": "場所・手段を表し、相手を示せない。", "から": "起点を表し、文意が逆になる。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "から": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36933, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "近年", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "記念", "is_correct": false, "explanation": "きねん。撥音「ん」がない。"}, {"text": "禁煙", "is_correct": false, "explanation": "きんえん。三拍目が「え」。"}, {"text": "新年", "is_correct": false, "explanation": "しんねん。一拍目が「し」。"}, {"text": "金言", "is_correct": false, "explanation": "きんげん。三拍目が「げ」。"}], "explanations": {"近年": "音声どおりの正しい表記。", "記念": "きねん。撥音「ん」がない。", "禁煙": "きんえん。三拍目が「え」。", "新年": "しんねん。一拍目が「し」。", "金言": "きんげん。三拍目が「げ」。"}, "sentence_index": null, "correct_answer": "近年"}, "level_3": {"options": [{"text": "近年", "is_correct": true, "explanation": "「近年になって」で最近数年の変化を表す。"}, {"text": "明日", "is_correct": false, "explanation": "アスペクト：未来の語で「変わった」と合わない。"}, {"text": "一瞬", "is_correct": false, "explanation": "意味：一瞬で町が変わるのは不自然。"}, {"text": "毎朝", "is_correct": false, "explanation": "意味：繰り返しの時で一回の変化に合わない。"}], "explanations": {"近年": "「近年になって」で最近数年の変化を表す。", "明日": "アスペクト：未来の語で「変わった」と合わない。", "一瞬": "意味：一瞬で町が変わるのは不自然。", "毎朝": "意味：繰り返しの時で一回の変化に合わない。"}, "sentence_index": 6, "correct_answer": "近年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "近年が本を読む人は減った。", "explanation": "助詞の混同：時の語「近年」に「が」は付かない。"}, {"text": "近年は本を読む人が減るだろう。", "explanation": "時制の誤り：「近年」はここ数年から現在までを指し、未来の推量とは合わない。"}, {"text": "近年を本を読む人が減った。", "explanation": "助詞の混同：時を表す「近年」に「を」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36933, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この問題は近年がよく話題になる。", "corrected_sentence": "この問題は近年よく話題になる。", "error_description": "助詞の誤り：時を表す「近年」に「が」は付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
