INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37927, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "豊か", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "床", "is_correct": false, "explanation": "ゆか。「た」が抜ける。"}, {"text": "鷹", "is_correct": false, "explanation": "たか。最初の「ゆ」が抜ける。"}, {"text": "有価", "is_correct": false, "explanation": "ゆうか。二拍目が「た」でなく「う」。"}], "explanations": {"豊か": "音声どおりの正しい表記。", "床": "ゆか。「た」が抜ける。", "鷹": "たか。最初の「ゆ」が抜ける。", "有価": "ゆうか。二拍目が「た」でなく「う」。"}, "sentence_index": null, "correct_answer": "豊か"}, "level_3": {"options": [{"text": "豊か", "is_correct": true, "explanation": "「豊かさ」で心が満ち足りていること。"}, {"text": "不便", "is_correct": false, "explanation": "意味：「心の不便さ」を追求するのは意味をなさない。"}, {"text": "確か", "is_correct": false, "explanation": "意味：「心の確かさ」は追求の対象として不自然。"}, {"text": "派手", "is_correct": false, "explanation": "意味：視覚的雑音を減らす文脈と矛盾する。"}], "explanations": {"豊か": "「豊かさ」で心が満ち足りていること。", "不便": "意味：「心の不便さ」を追求するのは意味をなさない。", "確か": "意味：「心の確かさ」は追求の対象として不自然。", "派手": "意味：視覚的雑音を減らす文脈と矛盾する。"}, "sentence_index": 0, "correct_answer": "豊か"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "豊かの実りの季節を心待ちにしている。", "explanation": "活用の誤り：形状詞は名詞を修飾するとき「の」でなく「な」をとる。"}, {"text": "豊かに実りの季節を心待ちにしている。", "explanation": "活用の誤り：名詞を修飾するのは「豊かな」。"}, {"text": "実りが豊かを季節を待つ。", "explanation": "助詞の混同：「豊かな季節」とすべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37927, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風味豊かのパンが完成するのです。", "corrected_sentence": "一連の科学的な変化を経て、風味豊かなパンが完成するのです。", "error_description": "活用の誤り：形状詞は名詞を修飾するとき「な」をとる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "豊か", "is_correct": true, "explanation": "後ろの「な」と合わせて連体形「豊かな」になり「パン」を修飾する。"}, {"text": "豊かに", "is_correct": false, "explanation": "「豊かにな」となり非文。連用形は名詞を修飾しない。"}, {"text": "豊かで", "is_correct": false, "explanation": "「豊かでな」となり非文。"}, {"text": "豊かだ", "is_correct": false, "explanation": "終止形「だ」の後に「な」は続かない。"}], "correct_form": "豊か", "base_form": "豊か", "form_label": "活用", "sentence_index": 1, "explanations": {"豊か": "後ろの「な」と合わせて連体形「豊かな」になり「パン」を修飾する。", "豊かに": "「豊かにな」となり非文。連用形は名詞を修飾しない。", "豊かで": "「豊かでな」となり非文。", "豊かだ": "終止形「だ」の後に「な」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
