INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37927, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "豊か", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "床", "is_correct": false, "explanation": "ゆか。「た」が抜ける。"}, {"text": "鷹", "is_correct": false, "explanation": "たか。最初の「ゆ」が抜ける。"}, {"text": "有価", "is_correct": false, "explanation": "ゆうか。二拍目が「た」でなく「う」。"}], "explanations": {"豊か": "音声どおりの正しい表記。", "床": "ゆか。「た」が抜ける。", "鷹": "たか。最初の「ゆ」が抜ける。", "有価": "ゆうか。二拍目が「た」でなく「う」。"}, "sentence_index": null, "correct_answer": "豊か"}, "level_3": {"options": [{"text": "豊か", "is_correct": true, "explanation": "「豊かになる」で心が満ち足りる。"}, {"text": "下手", "is_correct": false, "explanation": "意味：本を読んで心が下手になるのは不自然。"}, {"text": "便利", "is_correct": false, "explanation": "意味：「心が便利になる」とは言わない。"}, {"text": "不便", "is_correct": false, "explanation": "連語：「心が不便」とは言わない。"}], "explanations": {"豊か": "「豊かになる」で心が満ち足りる。", "下手": "意味：本を読んで心が下手になるのは不自然。", "便利": "意味：「心が便利になる」とは言わない。", "不便": "連語：「心が不便」とは言わない。"}, "sentence_index": 6, "correct_answer": "豊か"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "想像力を豊かな子どもだ。", "explanation": "助詞の混同：「想像力が」が正しい。"}, {"text": "想像力が豊かだ子どもだ。", "explanation": "活用の誤り：名詞修飾は「豊かな」。"}, {"text": "想像力が豊かに子どもだ。", "explanation": "活用の誤り：連用形「豊かに」は名詞を修飾しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37927, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この国は自然を豊かだ。", "corrected_sentence": "この国は自然が豊かだ。", "error_description": "助詞の混同：形状詞述語の主語は「が」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "豊か", "is_correct": true, "explanation": "語幹に「な」が続き「豊かな森」と名詞を修飾する。"}, {"text": "豊かだっ", "is_correct": false, "explanation": "「豊かだっな」は存在しない形。"}, {"text": "豊かなら", "is_correct": false, "explanation": "仮定形に「な」は続かない。"}, {"text": "豊かだろう", "is_correct": false, "explanation": "推量形の後に「な森」は続かない。"}], "correct_form": "豊か", "base_form": "豊か", "form_label": "活用", "sentence_index": 7, "explanations": {"豊か": "語幹に「な」が続き「豊かな森」と名詞を修飾する。", "豊かだっ": "「豊かだっな」は存在しない形。", "豊かなら": "仮定形に「な」は続かない。", "豊かだろう": "推量形の後に「な森」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
