INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37435, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基づく", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "言付く", "is_correct": false, "explanation": "ことづく。一拍目が「も」でなく「こ」。"}, {"text": "近づく", "is_correct": false, "explanation": "ちかづく。前半の音が違う。"}, {"text": "片付く", "is_correct": false, "explanation": "かたづく。前半の音が違う。"}, {"text": "色づく", "is_correct": false, "explanation": "いろづく。前半の音が違う。"}], "explanations": {"基づく": "音声どおりの正しい表記。", "言付く": "ことづく。一拍目が「も」でなく「こ」。", "近づく": "ちかづく。前半の音が違う。", "片付く": "かたづく。前半の音が違う。", "色づく": "いろづく。前半の音が違う。"}, "sentence_index": null, "correct_answer": "基づく"}, "level_3": {"options": [{"text": "基づき", "is_correct": true, "explanation": "思想を根拠にして行動することを表す。"}, {"text": "濡れ", "is_correct": false, "explanation": "意味：思想に濡れることはない。"}, {"text": "溶け", "is_correct": false, "explanation": "意味：思想に溶けるでは文意をなさない。"}, {"text": "曲がり", "is_correct": false, "explanation": "意味：思想に曲がるでは文意をなさない。"}], "explanations": {"基づき": "思想を根拠にして行動することを表す。", "濡れ": "意味：思想に濡れることはない。", "溶け": "意味：思想に溶けるでは文意をなさない。", "曲がり": "意味：思想に曲がるでは文意をなさない。"}, "sentence_index": 0, "correct_answer": "基づき"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "これは心理学を基づいた反応だ。", "explanation": "助詞の混同：「心理学に基づいた」が正しい。"}, {"text": "これは心理学に基づかれる反応を利用した。", "explanation": "活用の誤り：「基づく」は受身にしない。"}, {"text": "基づいた心理学にこれは反応だ。", "explanation": "語順の誤り：係り受けが壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
