INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53272, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "織りなす", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "取りなす", "is_correct": false, "explanation": "とりなす。一拍目が「お」でなく「と」。"}, {"text": "織り出す", "is_correct": false, "explanation": "おりだす。「な」が「だ」に変わる。"}, {"text": "見なす", "is_correct": false, "explanation": "みなす。前の音が違う。"}], "explanations": {"織りなす": "音声どおりの正しい表記。", "取りなす": "とりなす。一拍目が「お」でなく「と」。", "織り出す": "おりだす。「な」が「だ」に変わる。", "見なす": "みなす。前の音が違う。"}, "sentence_index": null, "correct_answer": "織りなす"}, "level_3": {"options": [{"text": "織りなす", "is_correct": true, "explanation": "記号が組み合わさってテキストを作り出す。"}, {"text": "食べる", "is_correct": false, "explanation": "意味：記号が食べることはない。"}, {"text": "眠る", "is_correct": false, "explanation": "意味：記号が眠るテキストは不自然。"}, {"text": "落とす", "is_correct": false, "explanation": "意味：記号が落とすでは意味をなさない。"}], "explanations": {"織りなす": "記号が組み合わさってテキストを作り出す。", "食べる": "意味：記号が食べることはない。", "眠る": "意味：記号が眠るテキストは不自然。", "落とす": "意味：記号が落とすでは意味をなさない。"}, "sentence_index": 0, "correct_answer": "織りなす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "酵母を織りなす化学反応と格闘していた。", "explanation": "助詞の混同：「酵母が織りなす」が正しい。"}, {"text": "酵母が織りなされる化学反応と格闘していた。", "explanation": "活用の誤り：主語「酵母が」と受身が矛盾。"}, {"text": "酵母が織りなすの化学反応と格闘していた。", "explanation": "接続の誤り：連体形「織りなす」は「の」を介さずに名詞を修飾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53272, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "むしろ、それらの相互作用が織りなして複雑適応システムにおいては、正負のフィードバックを介した非線形なダイナミクスが、予測不可能なマクロな秩序、すなわち創発をもたらすのである。", "corrected_sentence": "むしろ、それらの相互作用が織りなす複雑適応システムにおいては、正負のフィードバックを介した非線形なダイナミクスが、予測不可能なマクロな秩序、すなわち創発をもたらすのである。", "error_description": "活用の誤り：名詞を修飾するのは連体形「織りなす」で、て形は使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "織りなす", "is_correct": true, "explanation": "名詞を修飾する連体形（辞書形）。"}, {"text": "織りなして", "is_correct": false, "explanation": "て形は名詞を直接修飾できない。"}, {"text": "織りなせ", "is_correct": false, "explanation": "命令形は名詞を修飾できない。"}, {"text": "織りなそう", "is_correct": false, "explanation": "意向形は名詞の前に置けない。"}], "correct_form": "織りなす", "base_form": "織りなす", "form_label": "活用", "sentence_index": 1, "explanations": {"織りなす": "名詞を修飾する連体形（辞書形）。", "織りなして": "て形は名詞を直接修飾できない。", "織りなせ": "命令形は名詞を修飾できない。", "織りなそう": "意向形は名詞の前に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53272, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "連体節内の主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「相互作用に織りなす」では主体を示せず非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し非文。"}, {"text": "は", "is_correct": false, "explanation": "連体節の中では主題の「は」は使えず不自然。"}], "correct_answer": "が", "explanations": {"が": "連体節内の主語を示す。", "に": "「相互作用に織りなす」では主体を示せず非文。", "へ": "方向を表し非文。", "は": "連体節の中では主題の「は」は使えず不自然。"}, "error_tags": {"に": "location_vs_target", "へ": "direction", "は": "topic_vs_subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53272, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "織りなす", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "取りなす", "is_correct": false, "explanation": "とりなす。最初の音が違う。"}, {"text": "織り出す", "is_correct": false, "explanation": "おりだす。三拍目が濁る別語。"}, {"text": "見なす", "is_correct": false, "explanation": "みなす。前半が違う。"}], "explanations": {"織りなす": "音声どおりの正しい表記。", "取りなす": "とりなす。最初の音が違う。", "織り出す": "おりだす。三拍目が濁る別語。", "見なす": "みなす。前半が違う。"}, "sentence_index": null, "correct_answer": "織りなす"}, "level_3": {"options": [{"text": "織りなし", "is_correct": true, "explanation": "「た」に続く連用形。音と色が世界を作り出した。"}, {"text": "泣き", "is_correct": false, "explanation": "意味：音と色が泣いた世界は不自然。"}, {"text": "走り", "is_correct": false, "explanation": "意味：音と色が走るのは意味をなさない。"}, {"text": "借り", "is_correct": false, "explanation": "項構造：音と色が借りるでは文意不明。"}], "explanations": {"織りなし": "「た」に続く連用形。音と色が世界を作り出した。", "泣き": "意味：音と色が泣いた世界は不自然。", "走り": "意味：音と色が走るのは意味をなさない。", "借り": "項構造：音と色が借りるでは文意不明。"}, "sentence_index": 6, "correct_answer": "織りなし"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "四季に織りなす風景を楽しむ。", "explanation": "助詞の混同：作り出す主体は「が」で示す。"}, {"text": "四季が織りなせ風景を楽しむ。", "explanation": "活用の誤り：命令形は名詞を修飾できない。"}, {"text": "四季が織りなすだ風景を楽しむ。", "explanation": "活用の誤り：連体形に「だ」を挟んで名詞を修飾することはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53272, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "光と影に織りなす景色が美しい。", "corrected_sentence": "光と影が織りなす景色が美しい。", "error_description": "助詞の混同：作り出す主体は「が」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "織りなし", "is_correct": true, "explanation": "「て」に続く連用形（織りなして）。"}, {"text": "織りなさ", "is_correct": false, "explanation": "未然形は「て」に続かない。"}, {"text": "織りなす", "is_correct": false, "explanation": "辞書形は「て」に続かない。"}, {"text": "織りなせ", "is_correct": false, "explanation": "命令・仮定形は「て」に続かない。"}], "correct_form": "織りなし", "base_form": "織りなす", "form_label": "活用", "sentence_index": 7, "explanations": {"織りなし": "「て」に続く連用形（織りなして）。", "織りなさ": "未然形は「て」に続かない。", "織りなす": "辞書形は「て」に続かない。", "織りなせ": "命令・仮定形は「て」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53272, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「織りなす」の主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「山と川に織りなして」では主体を示せず非文。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体節の中でしか主語を示せず、ここでは非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し非文。"}], "correct_answer": "が", "explanations": {"が": "「織りなす」の主語を示す。", "に": "「山と川に織りなして」では主体を示せず非文。", "の": "「の」は連体節の中でしか主語を示せず、ここでは非文。", "へ": "方向を表し非文。"}, "error_tags": {"に": "location_vs_target", "の": "topic_vs_subject", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35405, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "構造", "is_correct": true, "explanation": "読み上げられた語。"}, {"text": "香草", "is_correct": false, "explanation": "音が似ているが別の語。"}, {"text": "工場", "is_correct": false, "explanation": "音が似ているが別の語。"}, {"text": "高層", "is_correct": false, "explanation": "音が似ているが別の語。"}], "explanations": {"構造": "読み上げられた語。", "香草": "音が似ているが別の語。", "工場": "音が似ているが別の語。", "高層": "音が似ているが別の語。"}, "sentence_index": null, "correct_answer": "構造"}, "level_3": {"options": [{"text": "構造", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "工程", "is_correct": false, "explanation": "作業の手順であり、主義の名前にならない。"}, {"text": "高層", "is_correct": false, "explanation": "「ポスト高層主義」という語はなく、記号・テキストの批評にも合わない。"}, {"text": "効果", "is_correct": false, "explanation": "「効果主義」は存在せず不自然。"}], "explanations": {"構造": "文脈に合う正しい語。", "工程": "作業の手順であり、主義の名前にならない。", "高層": "「ポスト高層主義」という語はなく、記号・テキストの批評にも合わない。", "効果": "「効果主義」は存在せず不自然。"}, "sentence_index": 0, "correct_answer": "構造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝、構造を飲んでから出かける。", "explanation": "構造は飲み物ではない。"}, {"text": "友達と公園で構造して遊んだ。", "explanation": "構造は動作を表す動詞として使えない。"}, {"text": "この料理はとても構造でおいしい。", "explanation": "構造は味を表す形容詞ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
