INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38293, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "最適", "is_correct": true, "explanation": "読み上げられた語。"}, {"text": "最低", "is_correct": false, "explanation": "音が似ているが別の語。"}, {"text": "裁定", "is_correct": false, "explanation": "音が似ているが別の語。"}, {"text": "再訂", "is_correct": false, "explanation": "音が似ているが別の語。"}], "explanations": {"最適": "読み上げられた語。", "最低": "音が似ているが別の語。", "裁定": "音が似ているが別の語。", "再訂": "音が似ているが別の語。"}, "sentence_index": null, "correct_answer": "最適"}, "level_3": {"options": [{"text": "最適", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "最悪", "is_correct": false, "explanation": "最悪解は難題への答えとして評価されない。"}, {"text": "最低", "is_correct": false, "explanation": "最低解では肯定的な結論に合わない。"}, {"text": "最後", "is_correct": false, "explanation": "「最後解」という語はない。"}], "explanations": {"最適": "文脈に合う正しい語。", "最悪": "最悪解は難題への答えとして評価されない。", "最低": "最低解では肯定的な結論に合わない。", "最後": "「最後解」という語はない。"}, "sentence_index": 0, "correct_answer": "最適"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日は最適を食べて、お腹がいっぱいになった。", "explanation": "最適は食べ物ではない。"}, {"text": "彼は最適に転んで、足をけがした。", "explanation": "最適は失敗や事故の様子には使わない。"}, {"text": "この雨はとても最適で、みんな困っている。", "explanation": "最適は困る状況を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38293, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部屋は勉強に最適だな場所だ。", "corrected_sentence": "この部屋は勉強に最適な場所だ。", "error_description": "最適は形状詞なので、名詞を修飾するときは「最適な」となる。「最適だな」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "最適", "is_correct": true, "explanation": "「化」の前には語幹がそのまま来る。"}, {"text": "最適な", "is_correct": false, "explanation": "連体形。後ろに「化」は続かない。"}, {"text": "最適に", "is_correct": false, "explanation": "連用形。「化」の前には来ない。"}, {"text": "最適だ", "is_correct": false, "explanation": "終止形。「化」の前には来ない。"}], "correct_form": "最適", "base_form": "最適", "form_label": "語幹（最適化の一部）", "sentence_index": 1, "explanations": {"最適": "「化」の前には語幹がそのまま来る。", "最適な": "連体形。後ろに「化」は続かない。", "最適に": "連用形。「化」の前には来ない。", "最適だ": "終止形。「化」の前には来ない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
