INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35859, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "本質", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "本式", "is_correct": false, "explanation": "ほんしき：三拍目「し」の次「つ」が「き」に変わる一モーラ差。"}, {"text": "本心", "is_correct": false, "explanation": "ほんしん：最後の「つ」が「ん」に変わる一モーラ差。"}, {"text": "温室", "is_correct": false, "explanation": "おんしつ：最初の「ほ」が「お」に変わる一モーラ差。"}, {"text": "寝室", "is_correct": false, "explanation": "しんしつ：最初の「ほ」が「し」に変わる一モーラ差。"}], "explanations": {"本質": "音声どおりの正しい表記。", "本式": "ほんしき：三拍目「し」の次「つ」が「き」に変わる一モーラ差。", "本心": "ほんしん：最後の「つ」が「ん」に変わる一モーラ差。", "温室": "おんしつ：最初の「ほ」が「お」に変わる一モーラ差。", "寝室": "しんしつ：最初の「ほ」が「し」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "本質"}, "level_3": {"options": [{"text": "本質", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "住所", "is_correct": false, "explanation": "意味：場所の情報で、「〜的な愉楽」として行為の楽しさを表せない。"}, {"text": "値段", "is_correct": false, "explanation": "意味：価格のことで、行為の愉楽を表す語として不適切。"}, {"text": "時計", "is_correct": false, "explanation": "意味：道具の名前で、「〜的な愉楽」として行為の楽しさを表せない。"}], "explanations": {"本質": "文脈に合う正しい語。", "住所": "意味：場所の情報で、「〜的な愉楽」として行為の楽しさを表せない。", "値段": "意味：価格のことで、行為の愉楽を表す語として不適切。", "時計": "意味：道具の名前で、「〜的な愉楽」として行為の楽しさを表せない。"}, "sentence_index": 0, "correct_answer": "本質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本質の一冊を本棚から取り出した。", "explanation": "助数詞の誤り：本質は抽象概念で、冊で数えられない。"}, {"text": "彼は毎朝本質で駅まで歩いている。", "explanation": "助詞の誤り：本質は手段を表す「で」の対象にならない。"}, {"text": "本質の温度を測ったら三十度だった。", "explanation": "意味の誤り：本質は抽象的な性質で、温度を測れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_erro