INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35859, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置に必要な助詞。"}, {"text": "が", "is_correct": false, "explanation": "他動詞「構築する」の目的語を主格で示すことはできない。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、構築の対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を表し、ここでは目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "この位置に必要な助詞。", "が": "他動詞「構築する」の目的語を主格で示すことはできない。", "に": "着点を表し、構築の対象を示せない。", "で": "場所・手段を表し、ここでは目的語にならない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "現象", "is_correct": true, "explanation": "本質（内にある根本）に対し、外に現れた姿を表す対義語。"}, {"text": "核心", "is_correct": false, "explanation": "中心的な部分で、むしろ類義に近い。"}, {"text": "根本", "is_correct": false, "explanation": "物事のもとで、類義に近く対義ではない。"}, {"text": "性質", "is_correct": false, "explanation": "持ち前の特徴で、対立する関係にない。"}], "correct_answer": "現象", "explanations": {"現象": "本質（内にある根本）に対し、外に現れた姿を表す対義語。", "核心": "中心的な部分で、むしろ類義に近い。", "根本": "物事のもとで、類義に近く対義ではない。", "性質": "持ち前の特徴で、対立する関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
