INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36071, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "微細", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "微罪", "is_correct": false, "explanation": "びざい：二拍目「さ」が濁音「ざ」になる清濁の差。"}, {"text": "被災", "is_correct": false, "explanation": "ひさい：語頭「び」が清音「ひ」になる清濁の差。"}, {"text": "記載", "is_correct": false, "explanation": "きさい：語頭「び」が「き」になる一モーラ差。"}, {"text": "委細", "is_correct": false, "explanation": "いさい：語頭「び」が「い」になる一モーラ差。"}], "explanations": {"微細": "音声どおりの正しい表記。", "微罪": "びざい：二拍目「さ」が濁音「ざ」になる清濁の差。", "被災": "ひさい：語頭「び」が清音「ひ」になる清濁の差。", "記載": "きさい：語頭「び」が「き」になる一モーラ差。", "委細": "いさい：語頭「び」が「い」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "微細"}, "level_3": {"options": [{"text": "微細", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "巨大", "is_correct": false, "explanation": "意味：「階層」のわずかな差を表すのに大きさが合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "連語：「新鮮な階層」は結びつきが不自然。"}, {"text": "賑やか", "is_correct": false, "explanation": "意味：騒がしさを表し、階層の性質に合わない。"}], "explanations": {"微細": "文脈に合う正しい語。", "巨大": "意味：「階層」のわずかな差を表すのに大きさが合わない。", "新鮮": "連語：「新鮮な階層」は結びつきが不自然。", "賑やか": "意味：騒がしさを表し、階層の性質に合わない。"}, "sentence_index": 0, "correct_answer": "微細"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "微細な声で大きく叫んだ。", "explanation": "意味の矛盾：微細と大きく叫ぶが衝突する。"}, {"text": "この山はとても微細で、登るのに三日かかる。", "explanation": "意味の誤り：巨大な山に微細は使えない。"}, {"text": "微細を傷が布についた。", "explanation": "助詞・活用の誤り：連体には「微細な」が必要で「を」は不可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnin