INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36071, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は微細な声で叫んで町中に響かせた。", "corrected_sentence": "彼は微細な音の違いを聞き分けた。", "error_description": "微細は町中に響く大きな声とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "微細", "is_correct": true, "explanation": "後ろの「だった」とつながる語幹。"}, {"text": "微細な", "is_correct": false, "explanation": "後ろに続く語と重なり、形が二重になって非文になる。"}, {"text": "微細に", "is_correct": false, "explanation": "連用形で、この位置の後続要素とつながらない。"}, {"text": "微細さ", "is_correct": false, "explanation": "名詞化した形で、後続要素と重なり非文になる。"}], "correct_form": "微細", "base_form": "微細", "form_label": "語幹（「だった」に接続）", "sentence_index": 7, "explanations": {"微細": "後ろの「だった」とつながる語幹。", "微細な": "後ろに続く語と重なり、形が二重になって非文になる。", "微細に": "連用形で、この位置の後続要素とつながらない。", "微細さ": "名詞化した形で、後続要素と重なり非文になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
