INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52248, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "静謐", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "性質", "is_correct": false, "explanation": "せいしつ：三拍目「ひ」が「し」になる一モーラ差。"}, {"text": "製品", "is_correct": false, "explanation": "せいひん：語末「つ」が「ん」になる一モーラ差。"}, {"text": "斉一", "is_correct": false, "explanation": "せいいつ：「ひ」が「い」になる一モーラ差。"}, {"text": "名筆", "is_correct": false, "explanation": "めいひつ：語頭「せ」が「め」になる一モーラ差。"}], "explanations": {"静謐": "音声どおりの正しい表記。", "性質": "せいしつ：三拍目「ひ」が「し」になる一モーラ差。", "製品": "せいひん：語末「つ」が「ん」になる一モーラ差。", "斉一": "せいいつ：「ひ」が「い」になる一モーラ差。", "名筆": "めいひつ：語頭「せ」が「め」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "静謐"}, "level_3": {"options": [{"text": "静謐", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "派手", "is_correct": false, "explanation": "意味：目立つさまで、静かな成長を表せない。"}, {"text": "騒然", "is_correct": false, "explanation": "意味：騒がしいさまで、文意と逆。"}, {"text": "乱暴", "is_correct": false, "explanation": "意味：荒々しいさまで、慈愛に満ちた文脈に合わない。"}], "explanations": {"静謐": "文脈に合う正しい語。", "派手": "意味：目立つさまで、静かな成長を表せない。", "騒然": "意味：騒がしいさまで、文意と逆。", "乱暴": "意味：荒々しいさまで、慈愛に満ちた文脈に合わない。"}, "sentence_index": 0, "correct_answer": "静謐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "静謐な花火大会で皆が大声を上げた。", "explanation": "意味の矛盾：大声の騒ぎに静謐は合わない。"}, {"text": "静謐をとても工房だった。", "explanation": "助詞・活用の誤り：「静謐な工房」とすべきで「を」は不可。"}, {"text": "工場の機械が静謐に大音量で鳴り響く。", "explanation": "意味の矛盾：大音量と静謐が衝突する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52248, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ロックの演奏会は静謐で、耳が痛いほどだった。", "corrected_sentence": "夜明けの寺は静謐で、心が落ち着いた。", "error_description": "静謐は静かで落ち着いた状態で、耳が痛いほどの騒音には使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "静謐", "is_correct": true, "explanation": "後ろの「かつ」と並べて用いる語幹。"}, {"text": "静謐な", "is_correct": false, "explanation": "後ろに続く語と重なり、形が二重になって非文になる。"}, {"text": "静謐に", "is_correct": false, "explanation": "連用形で、この位置の後続要素とつながらない。"}, {"text": "静謐だ", "is_correct": false, "explanation": "終止形で、文の途中のこの位置に置けない。"}], "correct_form": "静謐", "base_form": "静謐", "form_label": "語幹（「かつ」で並列）", "sentence_index": 1, "explanations": {"静謐": "後ろの「かつ」と並べて用いる語幹。", "静謐な": "後ろに続く語と重なり、形が二重になって非文になる。", "静謐に": "連用形で、この位置の後続要素とつながらない。", "静謐だ": "終止形で、文の途中のこの位置に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52248, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "騒然", "is_correct": true, "explanation": "静謐（静かで落ち着く）と反対に、騒がしく落ち着かないさま。"}, {"text": "閑静", "is_correct": false, "explanation": "静かなさまで、類義に近い。"}, {"text": "平穏", "is_correct": false, "explanation": "穏やかなさまで、対義ではない。"}, {"text": "厳粛", "is_correct": false, "explanation": "おごそかなさまで、対立しない。"}], "correct_answer": "騒然", "explanations": {"騒然": "静謐（静かで落ち着く）と反対に、騒がしく落ち着かないさま。", "閑静": "静かなさまで、類義に近い。", "平穏": "穏やかなさまで、対義ではない。", "厳粛": "おごそかなさまで、対立しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52248, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "静謐", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "精密", "is_correct": false, "explanation": "せいみつ：三拍目「ひ」が「み」になる一モーラ差。"}, {"text": "成立", "is_correct": false, "explanation": "せいりつ：三拍目「ひ」が「り」になる一モーラ差。"}, {"text": "製鉄", "is_correct": false, "explanation": "せいてつ：三拍目「ひ」が「て」になる一モーラ差。"}], "explanations": {"静謐": "音声どおりの正しい表記。", "精密": "せいみつ：三拍目「ひ」が「み」になる一モーラ差。", "成立": "せいりつ：三拍目「ひ」が「り」になる一モーラ差。", "製鉄": "せいてつ：三拍目「ひ」が「て」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "静謐"}, "level_3": {"options": [{"text": "静謐", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "迷惑", "is_correct": false, "explanation": "意味：湖を見て心が落ち着く理由にならない。"}, {"text": "不便", "is_correct": false, "explanation": "意味：利便性を表し、景色の様子に合わない。"}, {"text": "下手", "is_correct": false, "explanation": "意味：技術の拙さを表し、湖には使えない。"}], "explanations": {"静謐": "文脈に合う正しい語。", "迷惑": "意味：湖を見て心が落ち着く理由にならない。", "不便": "意味：利便性を表し、景色の様子に合わない。", "下手": "意味：技術の拙さを表し、湖には使えない。"}, "sentence_index": 6, "correct_answer": "静謐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "静謐な運動会で太鼓が鳴り続けた。", "explanation": "意味の矛盾：騒がしい場面に静謐は合わない。"}, {"text": "静謐なライブ会場で観客が絶叫し続けた。", "explanation": "意味の矛盾：絶叫が続く騒がしい場に静謐は合わない。"}, {"text": "静謐だ時間を大切にしたい。", "explanation": "活用の誤り：名詞を修飾するときは「静謐な」とする。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52248, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工事現場は静謐で、うるさくて眠れない。", "corrected_sentence": "山の宿は静謐で、ぐっすり眠れた。", "error_description": "静謐は静かな様子で、うるさい状況とは矛盾する。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "静謐", "is_correct": true, "explanation": "後ろの「さ」とつながり名詞「静謐さ」となる語幹。"}, {"text": "静謐な", "is_correct": false, "explanation": "後ろに続く語と重なり、形が二重になって非文になる。"}, {"text": "静謐に", "is_correct": false, "explanation": "連用形で、この位置の後続要素とつながらない。"}, {"text": "静謐だ", "is_correct": false, "explanation": "終止形で、文の途中のこの位置に置けない。"}], "correct_form": "静謐", "base_form": "静謐", "form_label": "語幹（接尾辞「さ」に接続）", "sentence_index": 7, "explanations": {"静謐": "後ろの「さ」とつながり名詞「静謐さ」となる語幹。", "静謐な": "後ろに続く語と重なり、形が二重になって非文になる。", "静謐に": "連用形で、この位置の後続要素とつながらない。", "静謐だ": "終止形で、文の途中のこの位置に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52248, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喧騒", "is_correct": true, "explanation": "静謐（静けさ）に対し、騒がしさを表す対義語。"}, {"text": "静寂", "is_correct": false, "explanation": "静けさで、類義に近い。"}, {"text": "安寧", "is_correct": false, "explanation": "穏やかで安らかな状態で、対義ではない。"}, {"text": "沈黙", "is_correct": false, "explanation": "黙ることで、対立する語ではない。"}], "correct_answer": "喧騒", "explanations": {"喧騒": "静謐（静けさ）に対し、騒がしさを表す対義語。", "静寂": "静けさで、類義に近い。", "安寧": "穏やかで安らかな状態で、対義ではない。", "沈黙": "黙ることで、対立する語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35705, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "過程", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "火星", "is_correct": false, "explanation": "かせい：二拍目「て」が「せ」になる一モーラ差。"}, {"text": "家計", "is_correct": false, "explanation": "かけい：二拍目「て」が「け」になる一モーラ差。"}, {"text": "加点", "is_correct": false, "explanation": "かてん：語末「い」が「ん」になる一モーラ差。"}], "explanations": {"過程": "音声どおりの正しい表記。", "火星": "かせい：二拍目「て」が「せ」になる一モーラ差。", "家計": "かけい：二拍目「て」が「け」になる一モーラ差。", "加点": "かてん：語末「い」が「ん」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "過程"}, "level_3": {"options": [{"text": "過程", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "結論", "is_correct": false, "explanation": "意味：最終的な判断で、見守る「成長の流れ」を表せない。"}, {"text": "住所", "is_correct": false, "explanation": "意味：場所の情報で、成長とは結びつかない。"}, {"text": "値段", "is_correct": false, "explanation": "意味：価格を表し、文脈に合わない。"}], "explanations": {"過程": "文脈に合う正しい語。", "結論": "意味：最終的な判断で、見守る「成長の流れ」を表せない。", "住所": "意味：場所の情報で、成長とは結びつかない。", "値段": "意味：価格を表し、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "過程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "過程を三本買ってきた。", "explanation": "助数詞の誤り：過程は物ではなく本で数えられない。"}, {"text": "過程で犬が吠えている。", "explanation": "意味・助詞の誤り：過程は犬がいる場所にならない。"}, {"text": "過程を冷蔵庫で冷やしておいた。", "explanation": "意味の誤り：過程は流れや段階で、物のように冷やせない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
