INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35705, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置に必要な助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、他動詞「培養する」の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、培養の対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表し、ここでは非文になる。"}], "correct_answer": "を", "explanations": {"を": "この位置に必要な助詞。", "へ": "方向を表し、他動詞「培養する」の目的語にならない。", "に": "着点を表し、培養の対象を示せない。", "より": "比較を表し、ここでは非文になる。"}, "error_tags": {"へ": "direction", "に": "location_vs_target", "より": "other"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "結果", "is_correct": true, "explanation": "過程（途中の流れ）に対し、最後に生じたものを表す。"}, {"text": "段階", "is_correct": false, "explanation": "途中の区切りで、類義に近い。"}, {"text": "経緯", "is_correct": false, "explanation": "いきさつで、対義ではない。"}, {"text": "手順", "is_correct": false, "explanation": "進め方で、対立しない。"}], "correct_answer": "結果", "explanations": {"結果": "過程（途中の流れ）に対し、最後に生じたものを表す。", "段階": "途中の区切りで、類義に近い。", "経緯": "いきさつで、対義ではない。", "手順": "進め方で、対立しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
