INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52114, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "唯", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "棚", "is_correct": false, "explanation": "たな：語末「だ」が「な」になる一モーラ差。"}, {"text": "束", "is_correct": false, "explanation": "たば：語末「だ」が「ば」になる一モーラ差。"}, {"text": "縦", "is_correct": false, "explanation": "たて：語末「だ」が「て」になる一モーラ差。"}, {"text": "為", "is_correct": false, "explanation": "ため：語末「だ」が「め」になる一モーラ差。"}], "explanations": {"唯": "音声どおりの正しい表記。", "棚": "たな：語末「だ」が「な」になる一モーラ差。", "束": "たば：語末「だ」が「ば」になる一モーラ差。", "縦": "たて：語末「だ」が「て」になる一モーラ差。", "為": "ため：語末「だ」が「め」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "唯"}, "level_3": {"options": [{"text": "ただ", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "決して", "is_correct": false, "explanation": "項構造：否定と呼応する副詞で、肯定文に入らない。"}, {"text": "めったに", "is_correct": false, "explanation": "項構造：否定と呼応する副詞で、肯定の「見守っているのだ」に入らない。"}, {"text": "まさか", "is_correct": false, "explanation": "項構造：否定や意外の推量と呼応し、断定の「見守っているのだ」と合わない。"}], "explanations": {"ただ": "文脈に合う正しい語。", "決して": "項構造：否定と呼応する副詞で、肯定文に入らない。", "めったに": "項構造：否定と呼応する副詞で、肯定の「見守っているのだ」に入らない。", "まさか": "項構造：否定や意外の推量と呼応し、断定の「見守っているのだ」と合わない。"}, "sentence_index": 0, "correct_answer": "ただ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ただ彼も彼女も、みんなが来てくれた。", "explanation": "意味の矛盾：ただは限定を表し、「も」「みんな」の包括と合わない。"}, {"text": "ただ多くのことが一度にできる。", "explanation": "意味の矛盾：それだけを示すただが「多くのこと」と衝突する。"}, {"text": "見守るただことだけだ。", "explanation": "語順の誤り：副詞ただが連体の位置に置かれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, 