INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52132, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宇宙", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "意中", "is_correct": false, "explanation": "いちゅう：語頭「う」が「い」になる一モーラ差。"}, {"text": "支柱", "is_correct": false, "explanation": "しちゅう：語頭「う」が「し」になる一モーラ差。"}, {"text": "忌中", "is_correct": false, "explanation": "きちゅう：語頭「う」が「き」になる一モーラ差。"}], "explanations": {"宇宙": "音声どおりの正しい表記。", "意中": "いちゅう：語頭「う」が「い」になる一モーラ差。", "支柱": "しちゅう：語頭「う」が「し」になる一モーラ差。", "忌中": "きちゅう：語頭「う」が「き」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "宇宙"}, "level_3": {"options": [{"text": "宇宙", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "台所", "is_correct": false, "explanation": "意味：鉢を一つの世界にたとえる語にならない。"}, {"text": "財布", "is_correct": false, "explanation": "意味：命が緑を深める場として不自然。"}, {"text": "時計", "is_correct": false, "explanation": "意味：道具で、限定された世界を表さない。"}], "explanations": {"宇宙": "文脈に合う正しい語。", "台所": "意味：鉢を一つの世界にたとえる語にならない。", "財布": "意味：命が緑を深める場として不自然。", "時計": "意味：道具で、限定された世界を表さない。"}, "sentence_index": 0, "correct_answer": "宇宙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宇宙を三冊買った。", "explanation": "助数詞の誤り：宇宙は冊で数えられない。"}, {"text": "宇宙で机の引き出しにしまった。", "explanation": "意味の誤り：宇宙は引き出しにしまえない。"}, {"text": "宇宙を手のひらに乗せて運んだ。", "explanation": "意味の誤り：宇宙は広大な空間で、手に乗せられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
