INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37073, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "個々", "is_correct": true, "explanation": "「ここ」と読む。"}, {"text": "ココア", "is_correct": false, "explanation": "「ここあ」で語末に音が加わる。"}, {"text": "小言", "is_correct": false, "explanation": "「こごと」で濁音と音数が違う。"}, {"text": "故国", "is_correct": false, "explanation": "「ここく」で語末に音が加わる。"}, {"text": "孤高", "is_correct": false, "explanation": "「ここう」で長音が加わる。"}, {"text": "戸口", "is_correct": false, "explanation": "「とぐち」で頭の音が違う。"}], "explanations": {"個々": "「ここ」と読む。", "ココア": "「ここあ」で語末に音が加わる。", "小言": "「こごと」で濁音と音数が違う。", "故国": "「ここく」で語末に音が加わる。", "孤高": "「ここう」で長音が加わる。", "戸口": "「とぐち」で頭の音が違う。"}, "sentence_index": null, "correct_answer": "個々"}, "level_3": {"options": [{"text": "個々", "is_correct": true, "explanation": "一人一人の学修到達度を指すので「個々」が合う。"}, {"text": "多忙", "is_correct": false, "explanation": "「多忙の学修到達度」は意味が通らない。"}, {"text": "一度", "is_correct": false, "explanation": "「一度の学修到達度」は意味が通らない。"}, {"text": "唯一", "is_correct": false, "explanation": "「唯一の学修到達度」は不自然。"}], "explanations": {"個々": "一人一人の学修到達度を指すので「個々」が合う。", "多忙": "「多忙の学修到達度」は意味が通らない。", "一度": "「一度の学修到達度」は意味が通らない。", "唯一": "「唯一の学修到達度」は不自然。"}, "sentence_index": 0, "correct_answer": "個々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋はとても個々で、静かだ。", "explanation": "「個々」は静かさや私的な様子を表す形容詞ではない。"}, {"text": "彼は個々な人で、いつも一人でいる。", "explanation": "「個々」は「〜な」の形で人の性格を表さない。"}, {"text": "雨が個々に降り続いて、川があふれた。", "explanation": "「個々」は連続の意味を持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37073, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町の人々は個々して暮らしている。", "corrected_sentence": "この町の人々は個々に暮らしている。", "error_description": "「個々」は「〜する」の形で動詞として使えない。副詞的には「個々に」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37073, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「個々の企業利益」で名詞を修飾する「の」。"}, {"text": "が", "is_correct": false, "explanation": "「個々が企業利益」では後ろの名詞につながらない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「個々に企業利益」は修飾関係が崩れる。"}], "correct_answer": "の", "explanations": {"の": "「個々の企業利益」で名詞を修飾する「の」。", "が": "「個々が企業利益」では後ろの名詞につながらない。", "を": "目的語の「を」では文が成り立たない。", "に": "「個々に企業利益」は修飾関係が崩れる。"}, "error_tags": {"が": "case_confusion", "を": "case_confusion", "に": "case_confusion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全体", "is_correct": true, "explanation": "一つ一つ別々の「個々」に対し、まとめた「全体」が反対の意味。"}, {"text": "各自", "is_correct": false, "explanation": "一人一人という意味で、近い語。"}, {"text": "個別", "is_correct": false, "explanation": "一つ一つ別にという意味で近い語。"}, {"text": "企業", "is_correct": false, "explanation": "関係のない名詞。"}], "correct_answer": "全体", "explanations": {"全体": "一つ一つ別々の「個々」に対し、まとめた「全体」が反対の意味。", "各自": "一人一人という意味で、近い語。", "個別": "一つ一つ別にという意味で近い語。", "企業": "関係のない名詞。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37073, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "個々", "is_correct": true, "explanation": "「ここ」と読む。"}, {"text": "箇所", "is_correct": false, "explanation": "「かしょ」で似た響きだが音が違う。"}, {"text": "ここら", "is_correct": false, "explanation": "語末に「ら」が付く。"}, {"text": "後期", "is_correct": false, "explanation": "「こうき」で長音と子音が違う。"}, {"text": "固辞", "is_correct": false, "explanation": "「こじ」で二拍目が違う。"}, {"text": "孤独", "is_correct": false, "explanation": "「こどく」で音が加わる。"}], "explanations": {"個々": "「ここ」と読む。", "箇所": "「かしょ」で似た響きだが音が違う。", "ここら": "語末に「ら」が付く。", "後期": "「こうき」で長音と子音が違う。", "固辞": "「こじ」で二拍目が違う。", "孤独": "「こどく」で音が加わる。"}, "sentence_index": null, "correct_answer": "個々"}, "level_3": {"options": [{"text": "個々", "is_correct": true, "explanation": "一人一人別々に話を聞くので「個々に」が合う。"}, {"text": "全部", "is_correct": false, "explanation": "「全部に話を聞いてみた」は不自然な言い方。"}, {"text": "全体", "is_correct": false, "explanation": "「全体に話を聞いてみた」は不自然な言い方。"}, {"text": "大型", "is_correct": false, "explanation": "「大型に話を聞いてみた」は意味が通らない。"}], "explanations": {"個々": "一人一人別々に話を聞くので「個々に」が合う。", "全部": "「全部に話を聞いてみた」は不自然な言い方。", "全体": "「全体に話を聞いてみた」は不自然な言い方。", "大型": "「大型に話を聞いてみた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "個々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理は個々がおいしい。", "explanation": "「個々」は味のよさを表す言葉ではない。"}, {"text": "個々の雨が一日中降った。", "explanation": "雨を一つ一つ別々に数える使い方はしない。"}, {"text": "明日は個々に行く予定だ。", "explanation": "「個々」は場所を表す「ここ」とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_wa