INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35785, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "価値", "is_correct": true, "explanation": "「かち」と読む。"}, {"text": "火事", "is_correct": false, "explanation": "「かじ」で濁音になる。"}, {"text": "肩", "is_correct": false, "explanation": "「かた」で二拍目が違う。"}, {"text": "口", "is_correct": false, "explanation": "「くち」で一拍目が違う。"}, {"text": "幸", "is_correct": false, "explanation": "「さち」で一拍目が違う。"}, {"text": "型紙", "is_correct": false, "explanation": "「かたがみ」で音が加わる。"}], "explanations": {"価値": "「かち」と読む。", "火事": "「かじ」で濁音になる。", "肩": "「かた」で二拍目が違う。", "口": "「くち」で一拍目が違う。", "幸": "「さち」で一拍目が違う。", "型紙": "「かたがみ」で音が加わる。"}, "sentence_index": null, "correct_answer": "価値"}, "level_3": {"options": [{"text": "価値", "is_correct": true, "explanation": "「友情の価値は大きい」で大切さを表す。"}, {"text": "色", "is_correct": false, "explanation": "「友情の色」は不自然。"}, {"text": "体重", "is_correct": false, "explanation": "「友情の体重」は意味が通らない。"}, {"text": "電話", "is_correct": false, "explanation": "「友情の電話は大きい」は意味が通らない。"}], "explanations": {"価値": "「友情の価値は大きい」で大切さを表す。", "色": "「友情の色」は不自然。", "体重": "「友情の体重」は意味が通らない。", "電話": "「友情の電話は大きい」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "価値"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "価値で手を洗った。", "explanation": "「価値」は物質ではない。"}, {"text": "毎日バスで価値に行く。", "explanation": "「価値」は場所ではない。"}, {"text": "価値がワンワンとほえた。", "explanation": "「価値」は動物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
