INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51472, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "緻密", "is_correct": true, "explanation": "「ちみつ」と読む。"}, {"text": "秘密", "is_correct": false, "explanation": "「ひみつ」で一拍目が違う。"}, {"text": "蜜", "is_correct": false, "explanation": "「みつ」で一拍目がない。"}, {"text": "地味", "is_correct": false, "explanation": "「じみ」で音が違う。"}, {"text": "密室", "is_correct": false, "explanation": "「みっしつ」で音が違う。"}, {"text": "近道", "is_correct": false, "explanation": "「ちかみち」で音が加わる。"}], "explanations": {"緻密": "「ちみつ」と読む。", "秘密": "「ひみつ」で一拍目が違う。", "蜜": "「みつ」で一拍目がない。", "地味": "「じみ」で音が違う。", "密室": "「みっしつ」で音が違う。", "近道": "「ちかみち」で音が加わる。"}, "sentence_index": null, "correct_answer": "緻密"}, "level_3": {"options": [{"text": "緻密", "is_correct": true, "explanation": "細かいところまで行き届いた管理なので「緻密な」が合う。"}, {"text": "乱暴", "is_correct": false, "explanation": "「乱暴な管理が不可欠」は文意に反する。"}, {"text": "大雑把", "is_correct": false, "explanation": "細部に気を配る文意と反対。"}, {"text": "退屈", "is_correct": false, "explanation": "「退屈な管理が不可欠」は意味が通らない。"}], "explanations": {"緻密": "細かいところまで行き届いた管理なので「緻密な」が合う。", "乱暴": "「乱暴な管理が不可欠」は文意に反する。", "大雑把": "細部に気を配る文意と反対。", "退屈": "「退屈な管理が不可欠」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "緻密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "緻密な声で大きく叫んだ。", "explanation": "「緻密」は声の大きさを表さない。"}, {"text": "彼は緻密を食べた。", "explanation": "「緻密」は食べ物ではない。"}, {"text": "今日はとても緻密な天気だ。", "explanation": "「緻密」は天気を形容しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
