INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51472, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "緻密", "is_correct": true, "explanation": "「ちみつ」と読む。"}, {"text": "知識", "is_correct": false, "explanation": "「ちしき」で音が違う。"}, {"text": "地図", "is_correct": false, "explanation": "「ちず」で音数が違う。"}, {"text": "密着", "is_correct": false, "explanation": "「みっちゃく」で音が違う。"}, {"text": "血筋", "is_correct": false, "explanation": "「ちすじ」で二拍目以降が違う。"}, {"text": "地道", "is_correct": false, "explanation": "「じみち」で音が違う。"}], "explanations": {"緻密": "「ちみつ」と読む。", "知識": "「ちしき」で音が違う。", "地図": "「ちず」で音数が違う。", "密着": "「みっちゃく」で音が違う。", "血筋": "「ちすじ」で二拍目以降が違う。", "地道": "「じみち」で音が違う。"}, "sentence_index": null, "correct_answer": "緻密"}, "level_3": {"options": [{"text": "緻密", "is_correct": true, "explanation": "細かく描かれた絵なので「緻密だ」が合う。"}, {"text": "ちょうど", "is_correct": false, "explanation": "「とてもちょうどだ」は文法的に誤り。"}, {"text": "親切", "is_correct": false, "explanation": "「この絵はとても親切だ」は意味が通らない。"}, {"text": "暇", "is_correct": false, "explanation": "「絵が暇だ」は意味が通らない。"}], "explanations": {"緻密": "細かく描かれた絵なので「緻密だ」が合う。", "ちょうど": "「とてもちょうどだ」は文法的に誤り。", "親切": "「この絵はとても親切だ」は意味が通らない。", "暇": "「絵が暇だ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "緻密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "緻密さを飲んで寝た。", "explanation": "「緻密さ」は飲み物ではない。"}, {"text": "彼は緻密な人だから、いつも忘れ物ばかりしている。", "explanation": "「緻密」は手抜かりがない意味で、忘れ物ばかりする様子と矛盾する。"}, {"text": "緻密さで雨がやんだ。", "explanation": "天気の変化とは関係がない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
