INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35221, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "職人", "is_correct": true, "explanation": "「しょくにん」と読む。"}, {"text": "食品", "is_correct": false, "explanation": "「しょくひん」で三拍目が違う。"}, {"text": "職員", "is_correct": false, "explanation": "「しょくいん」で三拍目が違う。"}, {"text": "植林", "is_correct": false, "explanation": "「しょくりん」で三拍目が違う。"}, {"text": "主人", "is_correct": false, "explanation": "「しゅじん」で前半の音が違う。"}, {"text": "証人", "is_correct": false, "explanation": "「しょうにん」で長音になる。"}], "explanations": {"職人": "「しょくにん」と読む。", "食品": "「しょくひん」で三拍目が違う。", "職員": "「しょくいん」で三拍目が違う。", "植林": "「しょくりん」で三拍目が違う。", "主人": "「しゅじん」で前半の音が違う。", "証人": "「しょうにん」で長音になる。"}, "sentence_index": null, "correct_answer": "職人"}, "level_3": {"options": [{"text": "職人", "is_correct": true, "explanation": "手作業で技術を持つ人の管理なので「職人」が合う。"}, {"text": "机", "is_correct": false, "explanation": "「机の緻密な管理」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の緻密な管理」は文意に合わない。"}, {"text": "子犬", "is_correct": false, "explanation": "「子犬の緻密な管理」は不自然。"}], "explanations": {"職人": "手作業で技術を持つ人の管理なので「職人」が合う。", "机": "「机の緻密な管理」は意味が通らない。", "天気": "「天気の緻密な管理」は文意に合わない。", "子犬": "「子犬の緻密な管理」は不自然。"}, "sentence_index": 0, "correct_answer": "職人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "職人を一杯飲んで休んだ。", "explanation": "「職人」は飲み物ではない。"}, {"text": "今日は職人がいい天気だ。", "explanation": "「職人」は天気を表さない。"}, {"text": "この箱は職人の形をしている。", "explanation": "「職人」は形を表す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
