INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39705, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「絵を見せた」で目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「絵が見せた」は他動詞と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「絵で見せた」は手段になり文意が変わる。"}, {"text": "へ", "is_correct": false, "explanation": "「絵へ」は方向を表し誤り。"}], "correct_answer": "を", "explanations": {"を": "「絵を見せた」で目的語を示す。", "が": "「絵が見せた」は他動詞と合わない。", "で": "「絵で見せた」は手段になり文意が変わる。", "へ": "「絵へ」は方向を表し誤り。"}, "error_tags": {"が": "case_confusion", "で": "case_confusion", "へ": "case_confusion"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未完成", "is_correct": true, "explanation": "まだでき上がっていないことで「完成」の反対。"}, {"text": "出来上がり", "is_correct": false, "explanation": "近い意味の語。"}, {"text": "作品", "is_correct": false, "explanation": "関係のある名詞だが反対ではない。"}, {"text": "高さ", "is_correct": false, "explanation": "関係のない名詞。"}], "correct_answer": "未完成", "explanations": {"未完成": "まだでき上がっていないことで「完成」の反対。", "出来上がり": "近い意味の語。", "作品": "関係のある名詞だが反対ではない。", "高さ": "関係のない名詞。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35151, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "科学", "is_correct": true, "explanation": "「かがく」と読む。"}, {"text": "画角", "is_correct": false, "explanation": "「がかく」。写真に写る範囲の角度。"}, {"text": "価格", "is_correct": false, "explanation": "「かかく」。ものの値段。"}, {"text": "過去", "is_correct": false, "explanation": "「かこ」。過ぎた時。"}, {"text": "加害", "is_correct": false, "explanation": "「かがい」。害を与えること。"}], "explanations": {"科学": "「かがく」と読む。", "画角": "「がかく」。写真に写る範囲の角度。", "価格": "「かかく」。ものの値段。", "過去": "「かこ」。過ぎた時。", "加害": "「かがい」。害を与えること。"}, "sentence_index": null, "correct_answer": "科学"}, "level_3": {"options": [{"text": "科学", "is_correct": true, "explanation": "「科学的な変化」で、仕組みに基づく変化を表す。"}, {"text": "文学", "is_correct": false, "explanation": "「文学的な変化」ではパン作りに合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "「音楽的な変化」は意味が通らない。"}, {"text": "歴史", "is_correct": false, "explanation": "「歴史的な変化」は大きな時代の変化で、この文脈に合わない。"}], "explanations": {"科学": "「科学的な変化」で、仕組みに基づく変化を表す。", "文学": "「文学的な変化」ではパン作りに合わない。", "音楽": "「音楽的な変化」は意味が通らない。", "歴史": "「歴史的な変化」は大きな時代の変化で、この文脈に合わない。"}, "sentence_index": 0, "correct_answer": "科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この科学は甘くておいしい。", "explanation": "科学は食べ物ではない。"}, {"text": "彼は科学を三杯飲んだ。", "explanation": "科学は飲み物ではない。"}, {"text": "駅前に大きな科学が建った。", "explanation": "科学は建物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
