INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36343, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "管理", "is_correct": true, "explanation": "「かんり」。"}, {"text": "観覧", "is_correct": false, "explanation": "「かんらん」。見物すること。"}, {"text": "関係", "is_correct": false, "explanation": "「かんけい」。つながり。"}, {"text": "簡易", "is_correct": false, "explanation": "「かんい」。手軽なこと。"}, {"text": "寒冷", "is_correct": false, "explanation": "「かんれい」。寒いこと。"}], "explanations": {"管理": "「かんり」。", "観覧": "「かんらん」。見物すること。", "関係": "「かんけい」。つながり。", "簡易": "「かんい」。手軽なこと。", "寒冷": "「かんれい」。寒いこと。"}, "sentence_index": null, "correct_answer": "管理"}, "level_3": {"options": [{"text": "管理", "is_correct": true, "explanation": "温度や時間の細かい管理が必要。"}, {"text": "散歩", "is_correct": false, "explanation": "緻密な散歩は不自然。"}, {"text": "昼寝", "is_correct": false, "explanation": "緻密な昼寝は意味が通らない。"}, {"text": "失敗", "is_correct": false, "explanation": "失敗が不可欠な工程、は不自然。"}], "explanations": {"管理": "温度や時間の細かい管理が必要。", "散歩": "緻密な散歩は不自然。", "昼寝": "緻密な昼寝は意味が通らない。", "失敗": "失敗が不可欠な工程、は不自然。"}, "sentence_index": 0, "correct_answer": "管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "管理をおいしく食べた。", "explanation": "管理は食べ物ではない。"}, {"text": "庭に管理が咲いている。", "explanation": "管理は花ではない。"}, {"text": "管理をかばんに入れた。", "explanation": "管理は物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
