INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35929, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "長い", "is_correct": true, "explanation": "「ながい」。"}, {"text": "投げない", "is_correct": false, "explanation": "「なげない」。"}, {"text": "流し", "is_correct": false, "explanation": "「ながし」。台所の設備。"}, {"text": "泣かない", "is_correct": false, "explanation": "「なかない」。"}, {"text": "仲居", "is_correct": false, "explanation": "「なかい」。旅館の係の人。"}], "explanations": {"長い": "「ながい」。", "投げない": "「なげない」。", "流し": "「ながし」。台所の設備。", "泣かない": "「なかない」。", "仲居": "「なかい」。旅館の係の人。"}, "sentence_index": null, "correct_answer": "長い"}, "level_3": {"options": [{"text": "長き", "is_correct": true, "explanation": "「長き眠り」で長い時間の眠り。文語の連体形。"}, {"text": "赤き", "is_correct": false, "explanation": "「赤き眠り」は意味が通らない。"}, {"text": "重き", "is_correct": false, "explanation": "「重き眠り」は自然な表現ではない。"}, {"text": "広き", "is_correct": false, "explanation": "「広き眠り」は意味が通らない。"}], "explanations": {"長き": "「長き眠り」で長い時間の眠り。文語の連体形。", "赤き": "「赤き眠り」は意味が通らない。", "重き": "「重き眠り」は自然な表現ではない。", "広き": "「広き眠り」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "長き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープはとても長い。", "explanation": "スープの味に長いは使わない。"}, {"text": "長い色の服を買った。", "explanation": "色に長いは使わない。"}, {"text": "この部屋は長いので明るい。", "explanation": "長さと明るさは関係なく、「広い」が自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
