INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35929, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "長い", "is_correct": true, "explanation": "「ながい」。"}, {"text": "泣かない", "is_correct": false, "explanation": "「なかない」。"}, {"text": "流し", "is_correct": false, "explanation": "「ながし」。"}, {"text": "習い", "is_correct": false, "explanation": "「ならい」。"}], "explanations": {"長い": "「ながい」。", "泣かない": "「なかない」。", "流し": "「ながし」。", "習い": "「ならい」。"}, "sentence_index": null, "correct_answer": "長い"}, "level_3": {"options": [{"text": "長か", "is_correct": true, "explanation": "「長かった」で話が長かった。"}, {"text": "赤か", "is_correct": false, "explanation": "話が赤かったは不自然。"}, {"text": "青か", "is_correct": false, "explanation": "話が青かったは意味が通らない。"}, {"text": "丸か", "is_correct": false, "explanation": "話が丸かったは不自然。"}], "explanations": {"長か": "「長かった」で話が長かった。", "赤か": "話が赤かったは不自然。", "青か": "話が青かったは意味が通らない。", "丸か": "話が丸かったは不自然。"}, "sentence_index": 6, "correct_answer": "長か"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このカレーは長くておいしい。", "explanation": "味に長いは使わない。"}, {"text": "父の声は長いので遠くまで聞こえる。", "explanation": "「大きい」が自然。"}, {"text": "今日の気温はとても長い。", "explanation": "気温には「高い」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35929, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長いの間、友達に会っていない。", "corrected_sentence": "長い間、友達に会っていない。", "error_description": "い形容詞は名詞の前に「の」をつけない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "長い", "is_correct": true, "explanation": "「長い間」で名詞の前の形。"}, {"text": "長く", "is_correct": false, "explanation": "名詞の前には使えない。"}, {"text": "長かった", "is_correct": false, "explanation": "「長かった間」は不自然。"}, {"text": "長くて", "is_correct": false, "explanation": "て形は名詞につながらない。"}], "correct_form": "長い", "base_form": "長い", "form_label": "連体形", "sentence_index": 7, "explanations": {"長い": "「長い間」で名詞の前の形。", "長く": "名詞の前には使えない。", "長かった": "「長かった間」は不自然。", "長くて": "て形は名詞につながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
