INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51608, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赤い", "is_correct": true, "explanation": "「あかい」。"}, {"text": "浅い", "is_correct": false, "explanation": "「あさい」。深くない。"}, {"text": "甘い", "is_correct": false, "explanation": "「あまい」。"}, {"text": "青い", "is_correct": false, "explanation": "「あおい」。"}, {"text": "明かり", "is_correct": false, "explanation": "「あかり」。光。"}], "explanations": {"赤い": "「あかい」。", "浅い": "「あさい」。深くない。", "甘い": "「あまい」。", "青い": "「あおい」。", "明かり": "「あかり」。光。"}, "sentence_index": null, "correct_answer": "赤い"}, "level_3": {"options": [{"text": "赤い", "is_correct": true, "explanation": "「赤い靴」は自然。"}, {"text": "苦い", "is_correct": false, "explanation": "苦い靴は不自然。"}, {"text": "甘い", "is_correct": false, "explanation": "甘い靴は意味が通らない。"}, {"text": "うるさい", "is_correct": false, "explanation": "うるさい靴は不自然。"}], "explanations": {"赤い": "「赤い靴」は自然。", "苦い": "苦い靴は不自然。", "甘い": "甘い靴は意味が通らない。", "うるさい": "うるさい靴は不自然。"}, "sentence_index": 0, "correct_answer": "赤い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この赤い歌はとても静かだ。", "explanation": "歌に色はない。"}, {"text": "赤い音が聞こえた。", "explanation": "音に色はない。"}, {"text": "彼の話はとても赤くて長い。", "explanation": "話に色はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
