INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51608, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の夕日は本当に赤いかった。", "corrected_sentence": "昨日の夕日は本当に赤かった。", "error_description": "過去形は「赤かった」で「い」を取る。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "赤かった", "is_correct": true, "explanation": "昨日のことなので過去形。"}, {"text": "赤い", "is_correct": false, "explanation": "昨日の話なので現在形は合わない。"}, {"text": "赤くて", "is_correct": false, "explanation": "文の終わりにて形は使えない。"}, {"text": "赤く", "is_correct": false, "explanation": "連用形では文が終わらない。"}], "correct_form": "赤かった", "base_form": "赤い", "form_label": "過去形", "sentence_index": 7, "explanations": {"赤かった": "昨日のことなので過去形。", "赤い": "昨日の話なので現在形は合わない。", "赤くて": "文の終わりにて形は使えない。", "赤く": "連用形では文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
