INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38529, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "厳密", "is_correct": true, "explanation": "「げんみつ」。"}, {"text": "現実", "is_correct": false, "explanation": "「げんじつ」。"}, {"text": "原始", "is_correct": false, "explanation": "「げんし」。"}, {"text": "元日", "is_correct": false, "explanation": "「がんじつ」。"}, {"text": "厳重", "is_correct": false, "explanation": "「げんじゅう」。"}], "explanations": {"厳密": "「げんみつ」。", "現実": "「げんじつ」。", "原始": "「げんし」。", "元日": "「がんじつ」。", "厳重": "「げんじゅう」。"}, "sentence_index": null, "correct_answer": "厳密"}, "level_3": {"options": [{"text": "厳密", "is_correct": true, "explanation": "「厳密な検証」で、正確な調べ。"}, {"text": "曖昧", "is_correct": false, "explanation": "曖昧な検証では偽装が無力化されない。"}, {"text": "適当", "is_correct": false, "explanation": "適当な検証では意味が逆になる。"}, {"text": "簡単", "is_correct": false, "explanation": "簡単な検証では文意に合わない。"}], "explanations": {"厳密": "「厳密な検証」で、正確な調べ。", "曖昧": "曖昧な検証では偽装が無力化されない。", "適当": "適当な検証では意味が逆になる。", "簡単": "簡単な検証では文意に合わない。"}, "sentence_index": 0, "correct_answer": "厳密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このケーキは厳密でおいしい。", "explanation": "味に厳密は使わない。"}, {"text": "厳密な犬が庭で寝ている。", "explanation": "動物の性質に使わない。"}, {"text": "今日は厳密に晴れている。", "explanation": "天気に厳密は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
