INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36771, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提供", "is_correct": true, "explanation": "「ていきょう」で、正しい語。"}, {"text": "定休", "is_correct": false, "explanation": "「ていきゅう」で、一モーラだけ違う別の語。"}, {"text": "抵抗", "is_correct": false, "explanation": "「ていこう」で、一モーラだけ違う別の語。"}, {"text": "提唱", "is_correct": false, "explanation": "「ていしょう」で、一モーラだけ違う別の語。"}, {"text": "低調", "is_correct": false, "explanation": "「ていちょう」で、一モーラだけ違う別の語。"}], "explanations": {"提供": "「ていきょう」で、正しい語。", "定休": "「ていきゅう」で、一モーラだけ違う別の語。", "抵抗": "「ていこう」で、一モーラだけ違う別の語。", "提唱": "「ていしょう」で、一モーラだけ違う別の語。", "低調": "「ていちょう」で、一モーラだけ違う別の語。"}, "sentence_index": null, "correct_answer": "提供"}, "level_3": {"options": [{"text": "提供", "is_correct": true, "explanation": "戦略やネットワークを相手に与えるという意味で文に合う。"}, {"text": "要求", "is_correct": false, "explanation": "相手から求める意味になり、価値を生む文脈に合わない。"}, {"text": "拒否", "is_correct": false, "explanation": "断る意味になり、文意と矛盾する。"}, {"text": "没収", "is_correct": false, "explanation": "取り上げる意味で、支援の文脈に合わない。"}], "explanations": {"提供": "戦略やネットワークを相手に与えるという意味で文に合う。", "要求": "相手から求める意味になり、価値を生む文脈に合わない。", "拒否": "断る意味になり、文意と矛盾する。", "没収": "取り上げる意味で、支援の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "提供"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が三時間も提供した。", "explanation": "「提供」は人や組織が物や情報を与えることで、雨が降る意味には使えない。"}, {"text": "彼は友達の家まで歩いて提供した。", "explanation": "移動の意味はなく、「提供」は与える対象が必要。"}, {"text": "私は今朝、とても眠くて提供した。", "explanation": "気分や状態を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36771, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店は客に無料でお茶を提供られた。", "corrected_sentence": "店は客に無料でお茶を提供した。", "error_description": "「提供する」の活用が誤っている。「提供られた」という形はない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36771, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「治す」の目的語「病気」を表す。"}, {"text": "が", "is_correct": false, "explanation": "「治す」は他動詞なので、目的語に「が」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点を表し、「治す」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を表し、ここでは不自然。"}], "correct_answer": "を", "explanations": {"を": "他動詞「治す」の目的語「病気」を表す。", "が": "「治す」は他動詞なので、目的語に「が」は使えない。", "に": "「に」は着点を表し、「治す」の目的語にならない。", "で": "「で」は手段・場所を表し、ここでは不自然。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受領", "is_correct": true, "explanation": "与える「提供」に対し、受け取る意味で反対の語。"}, {"text": "供給", "is_correct": false, "explanation": "与える意味で、反対ではなく近い語。"}, {"text": "支援", "is_correct": false, "explanation": "助ける意味で、反対語ではない。"}, {"text": "提示", "is_correct": false, "explanation": "見せる意味で、反対語ではない。"}], "correct_answer": "受領", "explanations": {"受領": "与える「提供」に対し、受け取る意味で反対の語。", "供給": "与える意味で、反対ではなく近い語。", "支援": "助ける意味で、反対語ではない。", "提示": "見せる意味で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36771, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "提供", "is_correct": true, "explanation": "「ていきょう」で、正しい語。"}, {"text": "低級", "is_correct": false, "explanation": "「ていきゅう」で、一モーラだけ違う別の語。"}, {"text": "盛況", "is_correct": false, "explanation": "「せいきょう」で、一モーラだけ違う別の語。"}, {"text": "景況", "is_correct": false, "explanation": "「けいきょう」で、一モーラだけ違う別の語。"}], "explanations": {"提供": "「ていきょう」で、正しい語。", "低級": "「ていきゅう」で、一モーラだけ違う別の語。", "盛況": "「せいきょう」で、一モーラだけ違う別の語。", "景況": "「けいきょう」で、一モーラだけ違う別の語。"}, "sentence_index": null, "correct_answer": "提供"}, "level_3": {"options": [{"text": "提供", "is_correct": true, "explanation": "場所を相手に与えてくれたという意味で合う。"}, {"text": "見物", "is_correct": false, "explanation": "見て楽しむ意味で、場所を与える文に合わない。"}, {"text": "禁止", "is_correct": false, "explanation": "させない意味で、「してくれた」と合わない。"}, {"text": "遅刻", "is_correct": false, "explanation": "自動詞的な語で「場所を」と結びつかない。"}], "explanations": {"提供": "場所を相手に与えてくれたという意味で合う。", "見物": "見て楽しむ意味で、場所を与える文に合わない。", "禁止": "させない意味で、「してくれた」と合わない。", "遅刻": "自動詞的な語で「場所を」と結びつかない。"}, "sentence_index": 6, "correct_answer": "提供"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎朝ジョギングを提供している。", "explanation": "自分がする運動には使えない。相手に何かを与える意味が必要。"}, {"text": "この花はとても提供だ。", "explanation": "「提供」は名詞・する動詞で、性質を表す形容詞のようには使えない。"}, {"text": "昨日は一日中、家で提供した。", "explanation": "与える対象も相手もなく、意味が成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
