INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36771, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「使う」の目的語「データ」を表す。"}, {"text": "が", "is_correct": false, "explanation": "「使う」の目的語に「が」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象・着点で、「使う」の目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、ここでは非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「使う」の目的語「データ」を表す。", "が": "「使う」の目的語に「が」は使えない。", "に": "「に」は対象・着点で、「使う」の目的語にならない。", "へ": "「へ」は方向を表し、ここでは非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受け取り", "is_correct": true, "explanation": "与える「提供」の反対で、もらうこと。"}, {"text": "配布", "is_correct": false, "explanation": "配って与える意味で、反対ではない。"}, {"text": "協力", "is_correct": false, "explanation": "力を合わせる意味で、反対語ではない。"}, {"text": "説明", "is_correct": false, "explanation": "内容を伝える意味で、反対語ではない。"}], "correct_answer": "受け取り", "explanations": {"受け取り": "与える「提供」の反対で、もらうこと。", "配布": "配って与える意味で、反対ではない。", "協力": "力を合わせる意味で、反対語ではない。", "説明": "内容を伝える意味で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37779, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "芸術", "is_correct": true, "explanation": "「げいじゅつ」で、正しい語。"}, {"text": "幻術", "is_correct": false, "explanation": "「げんじゅつ」で、一モーラだけ違う別の語。"}, {"text": "技術", "is_correct": false, "explanation": "「ぎじゅつ」で、音が近い別の語。"}, {"text": "手術", "is_correct": false, "explanation": "「しゅじゅつ」で、音が近い別の語。"}], "explanations": {"芸術": "「げいじゅつ」で、正しい語。", "幻術": "「げんじゅつ」で、一モーラだけ違う別の語。", "技術": "「ぎじゅつ」で、音が近い別の語。", "手術": "「しゅじゅつ」で、音が近い別の語。"}, "sentence_index": null, "correct_answer": "芸術"}, "level_3": {"options": [{"text": "芸術", "is_correct": true, "explanation": "技法を超えた美しい創造という意味で合う。"}, {"text": "事故", "is_correct": false, "explanation": "偶然の災難で、文意に合わない。"}, {"text": "値段", "is_correct": false, "explanation": "価格の意味で、文に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "気象の意味で、発酵の説明に合わない。"}], "explanations": {"芸術": "技法を超えた美しい創造という意味で合う。", "事故": "偶然の災難で、文意に合わない。", "値段": "価格の意味で、文に合わない。", "天気": "気象の意味で、発酵の説明に合わない。"}, "sentence_index": 0, "correct_answer": "芸術"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "芸術で駅まで走った。", "explanation": "「芸術」は活動や作品で、移動の手段にはならない。"}, {"text": "今日は芸術が降っている。", "explanation": "天気を表す語ではない。"}, {"text": "この牛乳は芸術が切れている。", "explanation": "期限を表す語ではなく、意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
