INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37779, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町は芸術な町として有名だ。", "corrected_sentence": "この町は芸術の町として有名だ。", "error_description": "「芸術」は名詞なので「な」ではなく「の」でつなぐ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37779, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞「芸術」が名詞「町」を修飾するときは「の」を使う。"}, {"text": "な", "is_correct": false, "explanation": "「芸術」は名詞なので「な」でつなげない。"}, {"text": "が", "is_correct": false, "explanation": "「芸術が町として」は非文。"}, {"text": "を", "is_correct": false, "explanation": "「芸術を町として」は非文。"}], "correct_answer": "の", "explanations": {"の": "名詞「芸術」が名詞「町」を修飾するときは「の」を使う。", "な": "「芸術」は名詞なので「な」でつなげない。", "が": "「芸術が町として」は非文。", "を": "「芸術を町として」は非文。"}, "error_tags": {"な": "other", "が": "other", "を": "object_marking"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自然", "is_correct": true, "explanation": "人が作る「芸術」に対し、人の手を加えないもの。"}, {"text": "音楽", "is_correct": false, "explanation": "芸術の一つで、反対語ではない。"}, {"text": "絵画", "is_correct": false, "explanation": "芸術の一つで、反対語ではない。"}, {"text": "美", "is_correct": false, "explanation": "芸術が求めるもので、反対語ではない。"}], "correct_answer": "自然", "explanations": {"自然": "人が作る「芸術」に対し、人の手を加えないもの。", "音楽": "芸術の一つで、反対語ではない。", "絵画": "芸術の一つで、反対語ではない。", "美": "芸術が求めるもので、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42775, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "育む", "is_correct": true, "explanation": "「はぐくむ」で、正しい語。"}, {"text": "剥ぐ", "is_correct": false, "explanation": "「はぐ」で、音が近い別の語。"}, {"text": "励む", "is_correct": false, "explanation": "「はげむ」で、音が近い別の語。"}, {"text": "拒む", "is_correct": false, "explanation": "「こばむ」で、終わりの音が近い別の語。"}, {"text": "挟む", "is_correct": false, "explanation": "「はさむ」で、音が近い別の語。"}], "explanations": {"育む": "「はぐくむ」で、正しい語。", "剥ぐ": "「はぐ」で、音が近い別の語。", "励む": "「はげむ」で、音が近い別の語。", "拒む": "「こばむ」で、終わりの音が近い別の語。", "挟む": "「はさむ」で、音が近い別の語。"}, "sentence_index": null, "correct_answer": "育む"}, "level_3": {"options": [{"text": "育む", "is_correct": true, "explanation": "土が命を大切に成長させるという意味で合う。"}, {"text": "壊す", "is_correct": false, "explanation": "破壊の意味で、「壮大な仕組み」と合わない。"}, {"text": "忘れる", "is_correct": false, "explanation": "記憶の意味で、土の働きに合わない。"}, {"text": "売る", "is_correct": false, "explanation": "商売の意味で、土の働きに合わない。"}], "explanations": {"育む": "土が命を大切に成長させるという意味で合う。", "壊す": "破壊の意味で、「壮大な仕組み」と合わない。", "忘れる": "記憶の意味で、土の働きに合わない。", "売る": "商売の意味で、土の働きに合わない。"}, "sentence_index": 0, "correct_answer": "育む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は駅で電車を育んだ。", "explanation": "電車は成長するものではなく、使えない。"}, {"text": "昨日、財布を道で育んだ。", "explanation": "落とす意味ではない。"}, {"text": "雨がたくさん育んで、道がぬれた。", "explanation": "雨が降る意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42775, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "土が命を育いでいる。", "corrected_sentence": "土が命を育んでいる。", "error_description": "「育む」のて形は「育んで」で、「育いで」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "育む", "is_correct": true, "explanation": "「のである」の前は辞書形（連体形）が必要。"}, {"text": "育んで", "is_correct": false, "explanation": "て形は後に続く動詞が必要で、「のである」につながらない。"}, {"text": "育もう", "is_correct": false, "explanation": "意向形は「のである」の前に置けない。"}, {"text": "育みます", "is_correct": false, "explanation": "ます形は「のである」の前では使わない。"}], "correct_form": "育む", "base_form": "育む", "form_label": "辞書形（連体）", "sentence_index": 1, "explanations": {"育む": "「のである」の前は辞書形（連体形）が必要。", "育んで": "て形は後に続く動詞が必要で、「のである」につながらない。", "育もう": "意向形は「のである」の前に置けない。", "育みます": "ます形は「のである」の前では使わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42775, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「育む」の目的語「萌芽」を表す。"}, {"text": "が", "is_correct": false, "explanation": "「育む」の目的語に「が」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所で、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向で、ここでは非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「育む」の目的語「萌芽」を表す。", "が": "「育む」の目的語に「が」は使えない。", "で": "「で」は手段・場所で、目的語にならない。", "へ": "「へ」は方向で、ここでは非文。"}, "error_tags": {"が": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "損なう", "is_correct": true, "explanation": "大切に育てる「育む」に対し、傷つけてだめにする意味。"}, {"text": "養う", "is_correct": false, "explanation": "育てる意味で、反対ではなく近い語。"}, {"text": "伸ばす", "is_correct": false, "explanation": "成長させる意味で、反対語ではない。"}, {"text": "守る", "is_correct": false, "explanation": "大切にする意味で、反対語ではない。"}], "correct_answer": "損なう", "explanations": {"損なう": "大切に育てる「育む」に対し、傷つけてだめにする意味。", "養う": "育てる意味で、反対ではなく近い語。", "伸ばす": "成長させる意味で、反対語ではない。", "守る": "大切にする意味で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42775, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "育む", "is_correct": true, "explanation": "「はぐくむ」で、正しい語。"}, {"text": "恵む", "is_correct": false, "explanation": "「めぐむ」で、終わりの音が近い別の語。"}, {"text": "はぐれる", "is_correct": false, "explanation": "「はぐれる」で、始まりの音が近い別の語。"}, {"text": "組む", "is_correct": false, "explanation": "「くむ」で、終わりの音が同じ別の語。"}, {"text": "拝む", "is_correct": false, "explanation": "「おがむ」で、音が近い別の語。"}], "explanations": {"育む": "「はぐくむ」で、正しい語。", "恵む": "「めぐむ」で、終わりの音が近い別の語。", "はぐれる": "「はぐれる」で、始まりの音が近い別の語。", "組む": "「くむ」で、終わりの音が同じ別の語。", "拝む": "「おがむ」で、音が近い別の語。"}, "sentence_index": null, "correct_answer": "育む"}, "level_3": {"options": [{"text": "育ん", "is_correct": true, "explanation": "森が生き物を大切に養い成長させている意味で合う。"}, {"text": "住ん", "is_correct": false, "explanation": "「住んでいる」は自動詞で、「生き物を」と合わない。"}, {"text": "盗ん", "is_correct": false, "explanation": "盗む意味で、森の働きに合わない。"}, {"text": "読ん", "is_correct": false, "explanation": "読む意味で、森の働きに合わない。"}], "explanations": {"育ん": "森が生き物を大切に養い成長させている意味で合う。", "住ん": "「住んでいる」は自動詞で、「生き物を」と合わない。", "盗ん": "盗む意味で、森の働きに合わない。", "読ん": "読む意味で、森の働きに合わない。"}, "sentence_index": 6, "correct_answer": "育ん"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は毎朝、歯を育んでいる。", "explanation": "歯を磨くという意味ではない。"}, {"text": "彼は怒って、ドアを強く育んだ。", "explanation": "閉める動作ではない。"}, {"text": "バスが遅れて、学校に育んだ。", "explanation": "遅刻・到着の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42775, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この学校は自由な心を育みる場所だ。", "corrected_sentence": "この学校は自由な心を育む場所だ。", "error_description": "「育む」は五段動詞なので「育みる」という形はない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "育む", "is_correct": true, "explanation": "名詞「場所」を修飾するので辞書形（連体形）が入る。"}, {"text": "育んで", "is_correct": false, "explanation": "て形は名詞を直接修飾できない。"}, {"text": "育みます", "is_correct": false, "explanation": "ます形は普通、名詞の修飾に使わず、常体の文に合わない。"}, {"text": "育め", "is_correct": false, "explanation": "命令形は名詞「場所」を修飾できない。"}], "correct_form": "育む", "base_form": "育む", "form_label": "辞書形（連体）", "sentence_index": 7, "explanations": {"育む": "名詞「場所」を修飾するので辞書形（連体形）が入る。", "育んで": "て形は名詞を直接修飾できない。", "育みます": "ます形は普通、名詞の修飾に使わず、常体の文に合わない。", "育め": "命令形は名詞「場所」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42775, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「育む」の目的語「心」を表す。"}, {"text": "は", "is_correct": false, "explanation": "連体修飾節の中に「は」は入らず非文。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」の後に続く名詞がなく非文。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向で、「育む」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「育む」の目的語「心」を表す。", "は": "連体修飾節の中に「は」は入らず非文。", "や": "並列の「や」の後に続く名詞がなく非文。", "へ": "「へ」は方向で、「育む」の目的語にならない。"}, "error_tags": {"は": "topic_vs_subject", "や": "other", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "大切に育てた愛を「育む」の反対に、だめにする意味。"}, {"text": "深める", "is_correct": false, "explanation": "関係を強くする意味で、反対ではない。"}, {"text": "温める", "is_correct": false, "explanation": "大切にする意味で、反対語ではない。"}, {"text": "育てる", "is_correct": false, "explanation": "近い意味の語で、反対語ではない。"}], "correct_answer": "壊す", "explanations": {"壊す": "大切に育てた愛を「育む」の反対に、だめにする意味。", "深める": "関係を強くする意味で、反対ではない。", "温める": "大切にする意味で、反対語ではない。", "育てる": "近い意味の語で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
