INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41227, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「表現する」の目的語「風景」を表す。"}, {"text": "が", "is_correct": false, "explanation": "「表現する」の目的語に「が」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点で、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向で、ここでは非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「表現する」の目的語「風景」を表す。", "が": "「表現する」の目的語に「が」は使えない。", "に": "「に」は着点で、目的語にならない。", "へ": "「へ」は方向で、ここでは非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41227, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "絵", "is_correct": true, "explanation": "「え」で、正しい語。"}, {"text": "毛", "is_correct": false, "explanation": "「け」で、音が近い別の語。"}, {"text": "上", "is_correct": false, "explanation": "「うえ」で、音が近い別の語。"}, {"text": "枝", "is_correct": false, "explanation": "「えだ」で、音が近い別の語。"}, {"text": "駅", "is_correct": false, "explanation": "「えき」で、音が近い別の語。"}], "explanations": {"絵": "「え」で、正しい語。", "毛": "「け」で、音が近い別の語。", "上": "「うえ」で、音が近い別の語。", "枝": "「えだ」で、音が近い別の語。", "駅": "「えき」で、音が近い別の語。"}, "sentence_index": null, "correct_answer": "絵"}, "level_3": {"options": [{"text": "絵", "is_correct": true, "explanation": "犬を描いたものという意味で「描いている」と合う。"}, {"text": "声", "is_correct": false, "explanation": "声は描くものではない。"}, {"text": "肉", "is_correct": false, "explanation": "肉は描くものとして文意に合わない。"}, {"text": "音", "is_correct": false, "explanation": "音は描くものではない。"}], "explanations": {"絵": "犬を描いたものという意味で「描いている」と合う。", "声": "声は描くものではない。", "肉": "肉は描くものとして文意に合わない。", "音": "音は描くものではない。"}, "sentence_index": 6, "correct_answer": "絵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "絵が強く吹いて、木が倒れた。", "explanation": "風の意味ではない。"}, {"text": "絵を十分寝たので、元気だ。", "explanation": "睡眠の意味ではない。"}, {"text": "この絵は時速百キロで走る。", "explanation": "絵は走るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41227, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "壁にきれいな絵がいる。", "corrected_sentence": "壁にきれいな絵がある。", "error_description": "絵は生き物ではないので「いる」ではなく「ある」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
