INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51460, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "初めて", "is_correct": true, "explanation": "「はじめて」で、正しい語。"}, {"text": "始めた", "is_correct": false, "explanation": "「はじめた」で、一モーラだけ違う別の語。"}, {"text": "恥じて", "is_correct": false, "explanation": "「はじて」で、一モーラだけ違う別の語。"}, {"text": "はじけて", "is_correct": false, "explanation": "「はじけて」で、一モーラだけ違う別の語。"}], "explanations": {"初めて": "「はじめて」で、正しい語。", "始めた": "「はじめた」で、一モーラだけ違う別の語。", "恥じて": "「はじて」で、一モーラだけ違う別の語。", "はじけて": "「はじけて」で、一モーラだけ違う別の語。"}, "sentence_index": null, "correct_answer": "初めて"}, "level_3": {"options": [{"text": "初めて", "is_correct": true, "explanation": "錯体形成を経てその段階で最初に輝くという意味で合う。"}, {"text": "昨日", "is_correct": false, "explanation": "時の名詞で、化学的な過程の文に合わない。"}, {"text": "全然", "is_correct": false, "explanation": "否定と使う副詞で、肯定文に合わない。"}, {"text": "決して", "is_correct": false, "explanation": "否定と使う副詞で、肯定文に合わない。"}], "explanations": {"初めて": "錯体形成を経てその段階で最初に輝くという意味で合う。", "昨日": "時の名詞で、化学的な過程の文に合わない。", "全然": "否定と使う副詞で、肯定文に合わない。", "決して": "否定と使う副詞で、肯定文に合わない。"}, "sentence_index": 0, "correct_answer": "初めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は初めて広い。", "explanation": "「初めて」は経験が最初であることを表し、程度は表せない。"}, {"text": "初めて、雨が降らないでください。", "explanation": "依頼の文に合わず、意味が通らない。"}, {"text": "彼は毎日初めて学校へ行く。", "explanation": "「毎日」と「初めて」は矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
