INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38533, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "儀礼", "is_correct": true, "explanation": "「ぎれい」で、正しい語。"}, {"text": "綺麗", "is_correct": false, "explanation": "「きれい」で、一モーラだけ違う別の語。"}, {"text": "比例", "is_correct": false, "explanation": "「ひれい」で、一モーラだけ違う別の語。"}, {"text": "無礼", "is_correct": false, "explanation": "「ぶれい」で、一モーラだけ違う別の語。"}], "explanations": {"儀礼": "「ぎれい」で、正しい語。", "綺麗": "「きれい」で、一モーラだけ違う別の語。", "比例": "「ひれい」で、一モーラだけ違う別の語。", "無礼": "「ぶれい」で、一モーラだけ違う別の語。"}, "sentence_index": null, "correct_answer": "儀礼"}, "level_3": {"options": [{"text": "儀礼", "is_correct": true, "explanation": "素材と向き合う決まった作法にたとえる意味で合う。"}, {"text": "事故", "is_correct": false, "explanation": "偶然の災難で、文意に合わない。"}, {"text": "値段", "is_correct": false, "explanation": "価格で、文意に合わない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちで、文意に合わない。"}], "explanations": {"儀礼": "素材と向き合う決まった作法にたとえる意味で合う。", "事故": "偶然の災難で、文意に合わない。", "値段": "価格で、文意に合わない。", "食欲": "食べたい気持ちで、文意に合わない。"}, "sentence_index": 0, "correct_answer": "儀礼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この儀礼はとても辛くておいしい。", "explanation": "儀礼は食べ物ではない。"}, {"text": "儀礼に乗って海を渡った。", "explanation": "儀礼は乗り物ではない。"}, {"text": "彼は儀礼が高くて、天井に頭が当たった。", "explanation": "身長を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
