INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38533, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "儀礼", "is_correct": true, "explanation": "「ぎれい」で、正しい語。"}, {"text": "事例", "is_correct": false, "explanation": "「じれい」で、一モーラだけ違う別の語。"}, {"text": "指令", "is_correct": false, "explanation": "「しれい」で、一モーラだけ違う別の語。"}, {"text": "樹齢", "is_correct": false, "explanation": "「じゅれい」で、一モーラだけ違う別の語。"}], "explanations": {"儀礼": "「ぎれい」で、正しい語。", "事例": "「じれい」で、一モーラだけ違う別の語。", "指令": "「しれい」で、一モーラだけ違う別の語。", "樹齢": "「じゅれい」で、一モーラだけ違う別の語。"}, "sentence_index": null, "correct_answer": "儀礼"}, "level_3": {"options": [{"text": "儀礼", "is_correct": true, "explanation": "祖父が重んじる伝統的な作法という意味で合う。"}, {"text": "宿題", "is_correct": false, "explanation": "課題の意味で「重んじる」には不自然。"}, {"text": "昼寝", "is_correct": false, "explanation": "短い睡眠で、文意に合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "交通の混雑で、文意に合わない。"}], "explanations": {"儀礼": "祖父が重んじる伝統的な作法という意味で合う。", "宿題": "課題の意味で「重んじる」には不自然。", "昼寝": "短い睡眠で、文意に合わない。", "渋滞": "交通の混雑で、文意に合わない。"}, "sentence_index": 6, "correct_answer": "儀礼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "儀礼を一杯飲んで寝た。", "explanation": "儀礼は飲み物ではない。"}, {"text": "駅まで儀礼で十分かかる。", "explanation": "移動の手段ではない。"}, {"text": "この儀礼は重さが五キロある。", "explanation": "重さをもつ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
