INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36875, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "化学", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "価格", "is_correct": false, "explanation": "「かかく」と読み、二拍目の清濁が異なる。"}, {"text": "鏡", "is_correct": false, "explanation": "「かがみ」と読み、三拍目が「く」と「み」で異なる。"}, {"text": "雅楽", "is_correct": false, "explanation": "「ががく」と読み、一拍目の清濁が異なる。"}, {"text": "地学", "is_correct": false, "explanation": "「ちがく」と読み、一拍目が「か」と「ち」で異なる。"}], "explanations": {"化学": "音声どおりの正しい表記。", "価格": "「かかく」と読み、二拍目の清濁が異なる。", "鏡": "「かがみ」と読み、三拍目が「く」と「み」で異なる。", "雅楽": "「ががく」と読み、一拍目の清濁が異なる。", "地学": "「ちがく」と読み、一拍目が「か」と「ち」で異なる。"}, "sentence_index": null, "correct_answer": "化学"}, "level_3": {"options": [{"text": "化学", "is_correct": true, "explanation": "物質の変化を扱う学問として「化学的操作」が成り立つ。"}, {"text": "音楽", "is_correct": false, "explanation": "意味：音楽的操作では染色の物質変化を表せない。"}, {"text": "家庭", "is_correct": false, "explanation": "意味：家庭的操作は染色の工程を指さない。"}, {"text": "友情", "is_correct": false, "explanation": "連語：「友情的操作」という結びつきは不自然。"}], "explanations": {"化学": "物質の変化を扱う学問として「化学的操作」が成り立つ。", "音楽": "意味：音楽的操作では染色の物質変化を表せない。", "家庭": "意味：家庭的操作は染色の工程を指さない。", "友情": "連語：「友情的操作」という結びつきは不自然。"}, "sentence_index": 0, "correct_answer": "化学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉は大学に化学を勉強している。", "explanation": "助詞の混同：勉強する場所は「に」ではなく「で」。"}, {"text": "姉は大学で化学を一冊勉強している。", "explanation": "助数詞の誤り：学問の「化学」を「冊」で数えない。"}, {"text": "姉は明日大学で化学を勉強した。", "explanation": "活用・アスペクトの誤り：「明日」と過去の「た」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
