INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36875, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "化学", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "課外", "is_correct": false, "explanation": "「かがい」と読み、三拍目が「く」と「い」で異なる。"}, {"text": "画角", "is_correct": false, "explanation": "「がかく」と読み、一拍目の清濁と二拍目の清濁が異なる。"}, {"text": "価格", "is_correct": false, "explanation": "「かかく」と読み、二拍目の清濁が異なる。"}, {"text": "家屋", "is_correct": false, "explanation": "「かおく」と読み、二拍目が「が」と「お」で異なる。"}], "explanations": {"化学": "音声どおりの正しい表記。", "課外": "「かがい」と読み、三拍目が「く」と「い」で異なる。", "画角": "「がかく」と読み、一拍目の清濁と二拍目の清濁が異なる。", "価格": "「かかく」と読み、二拍目の清濁が異なる。", "家屋": "「かおく」と読み、二拍目が「が」と「お」で異なる。"}, "sentence_index": null, "correct_answer": "化学"}, "level_3": {"options": [{"text": "化学", "is_correct": true, "explanation": "実験をする教科は「化学」。"}, {"text": "価格", "is_correct": false, "explanation": "意味：「価格の先生」は意味をなさない。"}, {"text": "階段", "is_correct": false, "explanation": "意味：「階段の先生」は意味をなさない。"}, {"text": "砂糖", "is_correct": false, "explanation": "意味：「砂糖の先生」は意味をなさない。"}], "explanations": {"化学": "実験をする教科は「化学」。", "価格": "意味：「価格の先生」は意味をなさない。", "階段": "意味：「階段の先生」は意味をなさない。", "砂糖": "意味：「砂糖の先生」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "化学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "料理にも化学を関係している。", "explanation": "助詞の混同：「関係する」は自動詞なので「が」を使う。"}, {"text": "料理にも化学が三匹関係している。", "explanation": "助数詞の誤り：「匹」は動物を数える語。"}, {"text": "料理にも化学が関係していた明日。", "explanation": "語順・時制の誤り：「明日」が文末にあり過去形とも合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
