INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38693, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "金", "is_correct": false, "explanation": "「きん」と読み、一拍目が「し」と「き」で異なる。"}, {"text": "線", "is_correct": false, "explanation": "「せん」と読み、一拍目が「し」と「せ」で異なる。"}, {"text": "陣", "is_correct": false, "explanation": "「じん」と読み、一拍目の清濁が異なる。"}, {"text": "損", "is_correct": false, "explanation": "「そん」と読み、一拍目が「し」と「そ」で異なる。"}], "explanations": {"真": "音声どおりの正しい表記。", "金": "「きん」と読み、一拍目が「し」と「き」で異なる。", "線": "「せん」と読み、一拍目が「し」と「せ」で異なる。", "陣": "「じん」と読み、一拍目の清濁が異なる。", "損": "「そん」と読み、一拍目が「し」と「そ」で異なる。"}, "sentence_index": null, "correct_answer": "真"}, "level_3": {"options": [{"text": "真", "is_correct": true, "explanation": "「真の輝き」で本当の姿という意味になる。"}, {"text": "逆", "is_correct": false, "explanation": "意味：「逆の輝き」では色の本来の姿を表せない。"}, {"text": "横", "is_correct": false, "explanation": "意味：位置を表す語で輝きの本物さを言えない。"}, {"text": "左", "is_correct": false, "explanation": "意味：方向の語で文脈に合わない。"}], "explanations": {"真": "「真の輝き」で本当の姿という意味になる。", "逆": "意味：「逆の輝き」では色の本来の姿を表せない。", "横": "意味：位置を表す語で輝きの本物さを言えない。", "左": "意味：方向の語で文脈に合わない。"}, "sentence_index": 0, "correct_answer": "真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼こそに真の友だちだと思う。", "explanation": "助詞の混同：「思う」の内容の主語は「に」ではなく「が」で示す。"}, {"text": "彼こそが一枚の真の友だちだと思う。", "explanation": "助数詞の誤り：人を「枚」で数えない。"}, {"text": "彼こそが真の友だちだと思った明日。", "explanation": "語順・時制の誤り：「明日」と過去形が合わず位置も不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, g