INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36347, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意識", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "知識", "is_correct": false, "explanation": "「ちしき」と読み、一拍目が「い」と「ち」で異なる。"}, {"text": "儀式", "is_correct": false, "explanation": "「ぎしき」と読み、一拍目が「い」と「ぎ」で異なる。"}, {"text": "遺跡", "is_correct": false, "explanation": "「いせき」と読み、二拍目が「し」と「せ」で異なる。"}], "explanations": {"意識": "音声どおりの正しい表記。", "知識": "「ちしき」と読み、一拍目が「い」と「ち」で異なる。", "儀式": "「ぎしき」と読み、一拍目が「い」と「ぎ」で異なる。", "遺跡": "「いせき」と読み、二拍目が「し」と「せ」で異なる。"}, "sentence_index": null, "correct_answer": "意識"}, "level_3": {"options": [{"text": "意識", "is_correct": true, "explanation": "「美意識」で美しさを感じ取る心を表す。"}, {"text": "時間", "is_correct": false, "explanation": "意味：「美時間」という語はなく意味をなさない。"}, {"text": "道路", "is_correct": false, "explanation": "意味：美しさを感じる心を表せない。"}, {"text": "天気", "is_correct": false, "explanation": "意味：「美天気」は意味をなさない。"}], "explanations": {"意識": "「美意識」で美しさを感じ取る心を表す。", "時間": "意味：「美時間」という語はなく意味をなさない。", "道路": "意味：美しさを感じる心を表せない。", "天気": "意味：「美天気」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "意識"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "環境への意識を高まっている。", "explanation": "助詞の混同：自動詞「高まる」の主語は「が」。"}, {"text": "環境への意識が一本高まっている。", "explanation": "助数詞の誤り：意識を「本」で数えない。"}, {"text": "環境への意識が明日高まった。", "explanation": "活用・アスペクトの誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c90efc4-a0e6-4309-a92d-d546596ba038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
