INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39057, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "事業や活動を行うための元手となるお金。", "primary_collocate": null, "pronunciation": "しきん", "ipa": "ɕikʲiɴ", "syllable_count": 3, "sentences": [{"text": "初期段階では、投資家からの資金調達を通じて事業の基盤を固め、市場での急速な成長を目指す。", "target_word": "資金", "complexity_tier": "T3", "furigana": "しょきだんかい とうしか しきんちょうたつ じぎょう きばん かた しじょう きゅうそく せいちょう めざ", "sentence_source": "mined"}, {"text": "ベンチャーキャピタルは、将来性のあるスタートアップへリスクを取って資金調達を行い、その成長を支援する重要な役割を担っている。", "target_word": "資金", "complexity_tier": "T3", "furigana": "しょうらいせい と しきんちょうたつ おこな せいちょう しえん じゅうよう やくわり にな", "sentence_source": "mined"}, {"text": "特に、初期段階のスタートアップ資金調達を担う彼らの役割は、単なる資本の提供にとどまらない。", "target_word": "資金", "complexity_tier": "T3", "furigana": "とく しょきだんかい しきんちょうたつ にな かれ やくわり たん しほん ていきょう", "sentence_source": "mined"}, {"text": "さらに、こうした資金供給メカニズムは、エコシステム全体に好循環をもたらす。", "target_word": "資金", "complexity_tier": "T3", "furigana": "しきんきょうきゅう ぜんたい こうじゅんかん", "sentence_source": "mined"}, {"text": "店を開く資金が足りない。", "target_word": "資金", "complexity_tier": "T3", "furigana": "みせ ひら しきん た", "sentence_source": "generated"}, {"text": "祭りの資金を町で集めた。", "target_word": "資金", "complexity_tier": "T3", "furigana": "まつ しきん まち あつ", "sentence_source": "generated"}, {"text": "兄は資金をためて会社を作った。", "target_word": "資金", "complexity_tier": "T3", "furigana": "あに しきん かいしゃ つく", "sentence_source": "generated"}, {"text": "この活動は寄付が資金になっている。", "target_word": "資金", "complexity_tier": "T3", "furigana": "かつどう きふ しきん", "sentence_source": "generated"}, {"text": "資金がなくて計画が止まった。", "target_word": "資金", "complexity_tier": "T3", "furigana": "しきん けいかく と", "sentence_source": "generated"}, {"text": "文化祭の資金は生徒会が出す。", "target_word": "資金", "complexity_tier": "T3", "furigana": "ぶんかさい しきん せいとかい だ", "sentence_source": "generated"}], "morphological_forms": [{"form": "資金力", "label": "派生"}, {"form": "資金難", "label": "派生"}, {"form": "資金源", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 事業や活動の元手となるお金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35791, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の進み具合や程度の違いによる、区切りや状態。", "primary_collocate": null, "pronunciation": "だんかい", "ipa": "daŋkai", "syllable_count": 4, "sentences": [{"text": "初期段階では、投資家からの資金調達を通じて事業の基盤を固め、市場での急速な成長を目指す。", "target_word": "段階", "complexity_tier": "T3", "furigana": "しょきだんかい とうしか しきんちょうたつ じぎょう きばん かた しじょう きゅうそく せいちょう めざ", "sentence_source": "mined"}, {"text": "特に、初期段階のスタートアップ資金調達を担う彼らの役割は、単なる資本の提供にとどまらない。", "target_word": "段階", "complexity_tier": "T3", "furigana": "とく しょきだんかい しきんちょうたつ にな かれ やくわり たん しほん ていきょう", "sentence_source": "mined"}, {"text": "計画はまだ準備の段階だ。", "target_word": "段階", "complexity_tier": "T3", "furigana": "けいかく じゅんび だんかい", "sentence_source": "generated"}, {"text": "練習は三つの段階に分かれている。", "target_word": "段階", "complexity_tier": "T3", "furigana": "れんしゅう みっ だんかい わ", "sentence_source": "generated"}, {"text": "次の段階に進むのが楽しみだ。", "target_word": "段階", "complexity_tier": "T3", "furigana": "つぎ だんかい すす たの", "sentence_source": "generated"}, {"text": "この段階で決めるのは早い。", "target_word": "段階", "complexity_tier": "T3", "furigana": "だんかい き はや", "sentence_source": "generated"}, {"text": "どの段階でも先生が助けてくれる。", "target_word": "段階", "complexity_tier": "T3", "furigana": "だんかい せんせい たす", "sentence_source": "generated"}, {"text": "最後の段階がいちばん難しい。", "target_word": "段階", "complexity_tier": "T3", "furigana": "さいご だんかい むずか", "sentence_source": "generated"}, {"text": "今の段階では答えられない。", "target_word": "段階", "complexity_tier": "T3", "furigana": "いま だんかい こた", "sentence_source": "generated"}, {"text": "工事は最終段階に入った。", "target_word": "段階", "complexity_tier": "T3", "furigana": "こうじ さいしゅうだんかい はい", "sentence_source": "generated"}], "morphological_forms": [{"form": "段階的", "label": "派生"}, {"form": "最終段階", "label": "派生"}, {"form": "初期段階", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の進み具合の区切りや状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35837, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今までのやり方を変えて、新しい技術や考え方を取り入れること。", "primary_collocate": null, "pronunciation": "かくしん", "ipa": "kakɯɕiɴ", "syllable_count": 4, "sentences": [{"text": "スタートアップは、革新的なアイデアを種として創業される。", "target_word": "革新", "complexity_tier": "T3", "furigana": "かくしんてき たね そうぎょう", "sentence_source": "mined"}, {"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "革新", "complexity_tier": "T3", "furigana": "ぎじゅつてき かくしん たん こうりつか どうぐ きょういく こうへいせい こべつさいてきか りょうりつ あら にんしきろんてき わくぐ こうちく え ほんしつてき きょういくてき しさ そん い", "sentence_source": "mined"}, {"text": "この会社は革新を大切にしている。", "target_word": "革新", "complexity_tier": "T3", "furigana": "かいしゃ かくしん たいせつ", "sentence_source": "generated"}, {"text": "町に小さな革新が起きた。", "target_word": "革新", "complexity_tier": "T3", "furigana": "まち ちい かくしん お", "sentence_source": "generated"}, {"text": "彼は教育の革新を目指している。", "target_word": "革新", "complexity_tier": "T3", "furigana": "かれ きょういく かくしん めざ", "sentence_source": "generated"}, {"text": "革新には時間とお金がかかる。", "target_word": "革新", "complexity_tier": "T3", "furigana": "かくしん じかん かね", "sentence_source": "generated"}, {"text": "新しい店は革新的なサービスを始めた。", "target_word": "革新", "complexity_tier": "T3", "furigana": "あたら みせ かくしんてき はじ", "sentence_source": "generated"}, {"text": "技術の革新で生活が便利になった。", "target_word": "革新", "complexity_tier": "T3", "furigana": "ぎじゅつ かくしん せいかつ べんり", "sentence_source": "generated"}, {"text": "古いやり方では革新は生まれない。", "target_word": "革新", "complexity_tier": "T3", "furigana": "ふる かた かくしん う", "sentence_source": "generated"}, {"text": "社長は工場の革新を進めている。", "target_word": "革新", "complexity_tier": "T3", "furigana": "しゃちょう こうじょう かくしん すす", "sentence_source": "generated"}], "morphological_forms": [{"form": "革新的", "label": "派生"}, {"form": "技術革新", "label": "派生"}, {"form": "革新する", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 古いやり方を新しく変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41341, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "必要な品物や資金を集めて準備すること。", "primary_collocate": null, "pronunciation": "ちょうたつ", "ipa": "tɕoːtatsɯ", "syllable_count": 4, "sentences": [{"text": "初期段階では、投資家からの資金調達を通じて事業の基盤を固め、市場での急速な成長を目指す。", "target_word": "調達", "complexity_tier": "T3", "furigana": "しょきだんかい とうしか しきんちょうたつ じぎょう きばん かた しじょう きゅうそく せいちょう めざ", "sentence_source": "mined"}, {"text": "ベンチャーキャピタルは、将来性のあるスタートアップへリスクを取って資金調達を行い、その成長を支援する重要な役割を担っている。", "target_word": "調達", "complexity_tier": "T3", "furigana": "しょうらいせい と しきんちょうたつ おこな せいちょう しえん じゅうよう やくわり にな", "sentence_source": "mined"}, {"text": "特に、初期段階のスタートアップ資金調達を担う彼らの役割は、単なる資本の提供にとどまらない。", "target_word": "調達", "complexity_tier": "T3", "furigana": "とく しょきだんかい しきんちょうたつ にな かれ やくわり たん しほん ていきょう", "sentence_source": "mined"}, {"text": "祭りの材料を地元で調達した。", "target_word": "調達", "complexity_tier": "T3", "furigana": "まつ ざいりょう じもと ちょうたつ", "sentence_source": "generated"}, {"text": "食料の調達はぼくの係だ。", "target_word": "調達", "complexity_tier": "T3", "furigana": "しょくりょう ちょうたつ かかり", "sentence_source": "generated"}, {"text": "部品の調達が遅れている。", "target_word": "調達", "complexity_tier": "T3", "furigana": "ぶひん ちょうたつ おく", "sentence_source": "generated"}, {"text": "必要な道具は自分で調達する。", "target_word": "調達", "complexity_tier": "T3", "furigana": "ひつよう どうぐ じぶん ちょうたつ", "sentence_source": "generated"}, {"text": "木材を調達するのに一週間かかった。", "target_word": "調達", "complexity_tier": "T3", "furigana": "もくざい ちょうたつ いっしゅうかん", "sentence_source": "generated"}, {"text": "調達できる量には限りがある。", "target_word": "調達", "complexity_tier": "T3", "furigana": "ちょうたつ りょう かぎ", "sentence_source": "generated"}, {"text": "父は会社で物の調達をしている。", "target_word": "調達", "complexity_tier": "T3", "furigana": "ちち かいしゃ もの ちょうたつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "調達する", "label": "派生"}, {"form": "資金調達", "label": "派生"}, {"form": "調達先", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 必要な物やお金を集めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
