INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39765, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "まちがいがなく、たしかで信頼できるようす。", "primary_collocate": null, "pronunciation": "かくじつ", "ipa": "ka.kɯ.dʑi.tsɯ", "syllable_count": 4, "sentences": [{"text": "誰に何を求めているか分析し、適切な言葉で発信することで、小さくても確実なファンを獲得できます。", "target_word": "確実", "complexity_tier": "T3", "furigana": "かくじつ", "sentence_source": "mined"}, {"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "確実", "complexity_tier": "T3", "furigana": "かくじつ", "sentence_source": "mined"}, {"text": "毎日練習して確実にうまくなった。", "target_word": "確実", "complexity_tier": "T3", "furigana": "かくじつ", "sentence_source": "generated"}, {"text": "それが一番確実な方法だと思う。", "target_word": "確実", "complexity_tier": "T3", "furigana": "かくじつ", "sentence_source": "generated"}, {"text": "彼の合格はもう確実だ。", "target_word": "確実", "complexity_tier": "T3", "furigana": "かくじつ", "sentence_source": "generated"}, {"text": "荷物は確実に届けてください。", "target_word": "確実", "complexity_tier": "T3", "furigana": "かくじつ", "sentence_source": "generated"}, {"text": "確実な答えはまだ出ていない。", "target_word": "確実", "complexity_tier": "T3", "furigana": "かくじつ", "sentence_source": "generated"}, {"text": "この計画なら成功は確実です。", "target_word": "確実", "complexity_tier": "T3", "furigana": "かくじつ", "sentence_source": "generated"}, {"text": "私は確実に約束を守る。", "target_word": "確実", "complexity_tier": "T3", "furigana": "かくじつ", "sentence_source": "generated"}, {"text": "明日は雨がほぼ確実らしい。", "target_word": "確実", "complexity_tier": "T3", "furigana": "かくじつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "確実な", "label": "活用"}, {"form": "確実に", "label": "活用"}, {"form": "確実だ", "label": "活用"}, {"form": "確実性", "label": "派生"}, {"form": "不確実", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | まちがいがなくたしかなさま", "collocate_grounding": {"statu