INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36873, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "化学肥料や農薬を使わず、自然の材料で育てたり作ったりすること。また、生物に由来する炭素の化合物。", "primary_collocate": null, "pronunciation": "ゆうき", "ipa": "jɯː.ki", "syllable_count": 3, "sentences": [{"text": "さらに、アミノ酸や有機酸が複雑に絡み合い、主食に奥深い風味と旨味の層を付与する。", "target_word": "有機", "complexity_tier": "T3", "furigana": "ゆうき", "sentence_source": "mined"}, {"text": "高校を卒業したばかりの10代の彼が選んだ道は、地方の有機農家で働くことでした。", "target_word": "有機", "complexity_tier": "T3", "furigana": "ゆうき", "sentence_source": "mined"}, {"text": "母は有機の野菜を選んで買う。", "target_word": "有機", "complexity_tier": "T3", "furigana": "ゆうき", "sentence_source": "generated"}, {"text": "この店は有機の食品だけを売っている。", "target_word": "有機", "complexity_tier": "T3", "furigana": "ゆうき", "sentence_source": "generated"}, {"text": "祖父は畑で有機の米を育てている。", "target_word": "有機", "complexity_tier": "T3", "furigana": "ゆうき", "sentence_source": "generated"}, {"text": "有機で育てたトマトは甘い。", "target_word": "有機", "complexity_tier": "T3", "furigana": "ゆうき", "sentence_source": "generated"}, {"text": "給食に有機の牛乳が出た。", "target_word": "有機", "complexity_tier": "T3", "furigana": "ゆうき", "sentence_source": "generated"}, {"text": "有機の肥料は土にやさしい。", "target_word": "有機", "complexity_tier": "T3", "furigana": "ゆうき", "sentence_source": "generated"}, {"text": "私たちは有機の綿でシャツを作った。", "target_word": "有機", "complexity_tier": "T3", "furigana": "ゆうき", "sentence_source": "generated"}, {"text": "有機にこだわる農家が増えている。", "target_word": "有機", "complexity_tier": "T3", "furigana": "ゆうき", "sentence_source": "generated"}], "morphological_forms": [{"form": "有機野菜", "label": "派生"}, {"form": "有機農業", "label": "派生"}, {"form": "有機物", "label": "派生"}, {"form": "有機的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自然の材料で作る・生物由来", "collocate_grounding": {"status": "no_source", "reason": "no col