INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35983, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つ以上のことが、同じ時に起こること。", "primary_collocate": null, "pronunciation": "どうじ", "ipa": "doːdʑi", "syllable_count": 3, "sentences": [{"text": "この取り組みは、単なる植物の栽培を超え、環境再生と社会的結束の醸成を同時に企図する点に特徴がある。", "target_word": "同時", "complexity_tier": "T3", "furigana": "どうじ", "sentence_source": "mined"}, {"text": "単なるエネルギー源に過ぎなかった穀物が、生命の維持と豊かな食体験を同時に叶える食文化へと昇華される。", "target_word": "同時", "complexity_tier": "T3", "furigana": "どうじ", "sentence_source": "mined"}, {"text": "二人は同時に手を挙げた。", "target_word": "同時", "complexity_tier": "T3", "furigana": "ふたり どうじ て あ", "sentence_source": "generated"}, {"text": "ドアが開くと同時に、犬が走り出した。", "target_word": "同時", "complexity_tier": "T3", "furigana": "あ どうじ いぬ はし だ", "sentence_source": "generated"}, {"text": "歌いながら同時にピアノを弾いている。", "target_word": "同時", "complexity_tier": "T3", "furigana": "うた どうじ ひ", "sentence_source": "generated"}, {"text": "二つの事件は同時に起きました。", "target_word": "同時", "complexity_tier": "T3", "furigana": "ふた じけん どうじ お", "sentence_source": "generated"}, {"text": "同時に二つのことはできない。", "target_word": "同時", "complexity_tier": "T3", "furigana": "どうじ ふた", "sentence_source": "generated"}, {"text": "ゴールは二人ほぼ同時だった。", "target_word": "同時", "complexity_tier": "T3", "furigana": "ふたり どうじ", "sentence_source": "generated"}, {"text": "映画と同時に本も発売された。", "target_word": "同時", "complexity_tier": "T3", "furigana": "えいが どうじ ほん はつばい", "sentence_source": "generated"}, {"text": "二人は同時に笑い出した。", "target_word": "同時", "complexity_tier": "T3", "furigana": "ふたり どうじ わら だ", "sentence_source": "generated"}], "morphological_forms": [{"form": "同時に", "label": "派生"}, {"form": "同時通訳", "label": "派生"}, {"form": "同時進行", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 同じ時に二つ以上が起こること", "collocate_grounding": {"status": "no_source",