INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35777, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "多くの人が住み、建物や道路がたくさんある大きな町。", "primary_collocate": null, "pronunciation": "とし", "ipa": "toɕi", "syllable_count": 2, "sentences": [{"text": "戦後の都市計画において、ブルータリズムは機能性を重視した新たな住宅様式として普及しました。", "target_word": "都市", "complexity_tier": "T3", "furigana": "とし", "sentence_source": "mined"}, {"text": "近年、パラメトリックデザインの理論は、都市主義の分野において重要な基盤となりつつあります。", "target_word": "都市", "complexity_tier": "T3", "furigana": "とし", "sentence_source": "mined"}, {"text": "デザイナーの直感に頼るのではなく、計算された論理によって、機能的かつ独創的な都市空間を創出することが目指されています。", "target_word": "都市", "complexity_tier": "T3", "furigana": "とし", "sentence_source": "mined"}, {"text": "東京は世界有数の大きな都市だ。", "target_word": "都市", "complexity_tier": "T3", "furigana": "とうきょう せかいゆうすう おお とし", "sentence_source": "generated"}, {"text": "この都市には人がたくさん住んでいる。", "target_word": "都市", "complexity_tier": "T3", "furigana": "とし ひと す", "sentence_source": "generated"}, {"text": "都市の空気はあまりきれいではない。", "target_word": "都市", "complexity_tier": "T3", "furigana": "とし くうき", "sentence_source": "generated"}, {"text": "いつか海外の都市で働きたい。", "target_word": "都市", "complexity_tier": "T3", "furigana": "かいがい とし はたら", "sentence_source": "generated"}, {"text": "大阪は西日本の中心的な都市です。", "target_word": "都市", "complexity_tier": "T3", "furigana": "おおさか にしにほん ちゅうしんてき とし", "sentence_source": "generated"}, {"text": "都市が広がり、森が減っている。", "target_word": "都市", "complexity_tier": "T3", "furigana": "とし ひろ もり へ", "sentence_source": "generated"}, {"text": "彼は都市より田舎の生活が好きだ。", "target_word": "都市", "complexity_tier": "T3", "furigana": "かれ とし いなか せいかつ す", "sentence_source": "generated"}], "morphological_forms": [{"form": "都市部", "label": "派生"}, {"form": "大都市", "label": "派生"}, {"form": "都市化", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 人と建物が多く集まる大きな町", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35941, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小さくて丸いしるし。", "primary_collocate": null, "pronunciation": "てん", "ipa": "teɴ", "syllable_count": 2, "sentences": [{"text": "紙にペンで小さな点を書いた。", "target_word": "点", "complexity_tier": "T3", "furigana": "かみ ちい てん か", "sentence_source": "generated"}, {"text": "地図の赤い点が駅です。", "target_word": "点", "complexity_tier": "T3", "furigana": "ちず あか てん えき", "sentence_source": "generated"}, {"text": "この字には点が二つある。", "target_word": "点", "complexity_tier": "T3", "furigana": "じ てん ふた", "sentence_source": "generated"}, {"text": "点と点を線でつないでください。", "target_word": "点", "complexity_tier": "T3", "furigana": "てん てん せん", "sentence_source": "generated"}, {"text": "てんとう虫の背中には黒い点がある。", "target_word": "点", "complexity_tier": "T3", "furigana": "むし せなか くろ てん", "sentence_source": "generated"}, {"text": "画面に白い点が見えている。", "target_word": "点", "complexity_tier": "T3", "furigana": "がめん しろ てん み", "sentence_source": "generated"}, {"text": "服にインクの点がついてしまった。", "target_word": "点", "complexity_tier": "T3", "furigana": "ふく てん", "sentence_source": "generated"}, {"text": "「犬」の点を忘れないで。", "target_word": "点", "complexity_tier": "T3", "furigana": "いぬ てん わす", "sentence_source": "generated"}, {"text": "遠くの船が点のように小さい。", "target_word": "点", "complexity_tier": "T3", "furigana": "とお ふね てん ちい", "sentence_source": "generated"}, {"text": "星が夜空に点を打ったように光る。", "target_word": "点", "complexity_tier": "T3", "furigana": "ほし よぞら てん う ひか", "sentence_source": "generated"}], "morphological_forms": [{"form": "点線", "label": "派生"}, {"form": "句読点", "label": "派生"}, {"form": "点々", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 小さく丸いしるし・ぽち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', 