INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35435, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとや活動を動かすもとになるもの。多く「原動力」の形で使う。", "primary_collocate": null, "pronunciation": "げんどう", "ipa": "ɡendoː", "syllable_count": 4, "sentences": [{"text": "既存の緑地と有機的にネットワークを形成することで生態系の回廊としての機能を補完し、ひいては地域全体の環境リテラシーを向上させる原動力となり得るのである。", "target_word": "原動", "complexity_tier": "T3", "furigana": "げんどう", "sentence_source": "mined"}, {"text": "このような活動は、個々の企業利益だけでなく、社会全体の経済発展を牽引する原動力ともなっている。", "target_word": "原動", "complexity_tier": "T3", "furigana": "げんどう", "sentence_source": "mined"}, {"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "原動", "complexity_tier": "T3", "furigana": "げんどう", "sentence_source": "mined"}, {"text": "夢が彼の原動力になっている。", "target_word": "原動", "complexity_tier": "T3", "furigana": "ゆめ かれ げんどうりょく", "sentence_source": "generated"}, {"text": "家族の笑顔が私の原動力です。", "target_word": "原動", "complexity_tier": "T3", "furigana": "かぞく えがお わたし げんどうりょく", "sentence_source": "generated"}, {"text": "若者の力が町を変える原動力だ。", "target_word": "原動", "complexity_tier": "T3", "furigana": "わかもの ちから まち か げんどうりょく", "sentence_source": "generated"}, {"text": "好奇心は学びの原動力と言える。", "target_word": "原動", "complexity_tier": "T3", "furigana": "こうきしん まな げんどうりょく い", "sentence_source": "generated"}, {"text": "仲間の存在がチームの原動力だ。", "target_word": "原動", "complexity_tier": "T3", "furigana": "なかま そんざい げんどうりょく", "sentence_source": "generated"}, {"text": "怒りを原動力にして練習した。", "target_word": "原動", "complexity_tier": "T3", "furigana": "いか げんどうりょく れんしゅう", "sentence_source": "generated"}, {"text": "ファンの声援が勝利の原動力となった。", "target_word": "原動", "complexity_tier": "T3", "furigana": "せいえん しょうり げんどうりょく", "sentence_source": "generated"}], "morphological_forms": [{"form": "原動力", "label": "派生"}, {"form": "原動機", "label": "派生"}, {"form": "原動機付自転車", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 活動を起こし動かすもと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35193, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるものが他のものに働きかけて、変化を起こすこと。", "primary_collocate": "与える", "pronunciation": "えいきょう", "ipa": "eːkʲoː", "syllable_count": 4, "sentences": [{"text": "一方で、農村経済全体を見ると、労働需要の質が変化するという社会経済的影響も無視できません。", "target_word": "影響", "complexity_tier": "T3", "furigana": "えいきょう", "sentence_source": "mined"}, {"text": "台風の影響で電車が止まった。", "target_word": "影響", "complexity_tier": "T3", "furigana": "たいふう えいきょう でんしゃ と", "sentence_source": "generated"}, {"text": "父は私に大きな影響を与えた。", "target_word": "影響", "complexity_tier": "T3", "furigana": "ちち わたし おお えいきょう あた", "sentence_source": "generated"}, {"text": "友だちの影響で野球を始めた。", "target_word": "影響", "complexity_tier": "T3", "furigana": "とも えいきょう やきゅう はじ", "sentence_source": "generated"}, {"text": "音楽は心に良い影響を与える。", "target_word": "影響", "complexity_tier": "T3", "furigana": "おんがく こころ よ えいきょう あた", "sentence_source": "generated"}, {"text": "その映画の影響は大きかった。", "target_word": "影響", "complexity_tier": "T3", "furigana": "えいが えいきょう おお", "sentence_source": "generated"}, {"text": "天気が気分に影響している。", "target_word": "影響", "complexity_tier": "T3", "furigana": "てんき きぶん えいきょう", "sentence_source": "generated"}, {"text": "彼女は兄から影響を受けている。", "target_word": "影響", "complexity_tier": "T3", "furigana": "かのじょ あに えいきょう う", "sentence_source": "generated"}, {"text": "スマホは目に悪い影響がある。", "target_word": "影響", "complexity_tier": "T3", "furigana": "め わる えいきょう", "sentence_source": "generated"}, {"text": "影響のある人になりたい。", "target_word": "影響", "complexity_tier": "T3", "furigana": "えいきょう ひと", "sentence_source": "generated"}], "morphological_forms": [{"form": "影響する", "label": "派生"}, {"form": "影響力", "label": "派生"}, {"form": "影響を与える", "label": "派生"}, {"form": "影響を受ける", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 他に働きかけ変化を起こすこと", 