INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35021, 3, 'prompt1_core', '{"pos": "代名詞", "semantic_class": "function", "definition": "そこにいるすべての人。みんな。", "primary_collocate": null, "pronunciation": "みな", "ipa": "mina", "syllable_count": 2, "sentences": [{"text": "みんなのことばがわかります。", "target_word": "みんな", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "みんなの町を、しっかり防衛します。", "target_word": "みんな", "complexity_tier": "T3", "furigana": "まち ぼうえい", "sentence_source": "mined"}, {"text": "昔はみんな同じ薬です。", "target_word": "みんな", "complexity_tier": "T3", "furigana": "むかし おな くすり", "sentence_source": "mined"}, {"text": "クラスのみんなで歌を歌った。", "target_word": "みんな", "complexity_tier": "T3", "furigana": "うた うた", "sentence_source": "generated"}, {"text": "みんな、もう帰りましたよ。", "target_word": "みんな", "complexity_tier": "T3", "furigana": "かえ", "sentence_source": "generated"}, {"text": "みんなが彼の話を聞いている。", "target_word": "みんな", "complexity_tier": "T3", "furigana": "かれ はなし き", "sentence_source": "generated"}, {"text": "みんなに手紙を書きました。", "target_word": "みんな", "complexity_tier": "T3", "furigana": "てがみ か", "sentence_source": "generated"}, {"text": "家族みんなで旅行に行く。", "target_word": "みんな", "complexity_tier": "T3", "furigana": "かぞく りょこう い", "sentence_source": "generated"}, {"text": "みんなと一緒なら楽しい。", "target_word": "みんな", "complexity_tier": "T3", "furigana": "いっしょ たの", "sentence_source": "generated"}, {"text": "みんなの意見を聞きたい。", "target_word": "みんな", "complexity_tier": "T3", "furigana": "いけん き", "sentence_source": "generated"}], "morphological_forms": [{"form": "みんな", "label": "派生"}, {"form": "皆さん", "label": "敬語形"}, {"form": "皆様", "label": "敬語形"}], "register": "plain", "sense_fingerprint": "代名詞 | その場や仲間のすべての人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5614974