INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35969, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ある目的のために、どうしても要ること。欠かせないこと。", "primary_collocate": null, "pronunciation": "ひつよう", "ipa": "çitsɯjoː", "syllable_count": 4, "sentences": [{"text": "ミニマリストの思想に基づき、必要な要素だけを残すことで、居住者はより穏やかな日常を送ることができます。", "target_word": "必要", "complexity_tier": "T3", "furigana": "ひつよう", "sentence_source": "mined"}, {"text": "旅行には必要な物だけを持っていく。", "target_word": "必要", "complexity_tier": "T3", "furigana": "ひつよう", "sentence_source": "generated"}, {"text": "この仕事には英語が必要だ。", "target_word": "必要", "complexity_tier": "T3", "furigana": "ひつよう", "sentence_source": "generated"}, {"text": "植物が育つには水が必要です。", "target_word": "必要", "complexity_tier": "T3", "furigana": "ひつよう", "sentence_source": "generated"}, {"text": "もう心配する必要はないよ。", "target_word": "必要", "complexity_tier": "T3", "furigana": "ひつよう", "sentence_source": "generated"}, {"text": "必要なら、いつでも手伝うよ。", "target_word": "必要", "complexity_tier": "T3", "furigana": "ひつよう", "sentence_source": "generated"}, {"text": "それは本当に必要なのか考えた。", "target_word": "必要", "complexity_tier": "T3", "furigana": "ひつよう", "sentence_source": "generated"}, {"text": "参加に予約は必要ありません。", "target_word": "必要", "complexity_tier": "T3", "furigana": "ひつよう", "sentence_source": "generated"}, {"text": "必要以上に買い物をしないようにしている。", "target_word": "必要", "complexity_tier": "T3", "furigana": "ひつよう", "sentence_source": "generated"}, {"text": "友だちの助けが必要になった。", "target_word": "必要", "complexity_tier": "T3", "furigana": "ひつよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "必要だ", "label": "活用"}, {"form": "必要な", "label": "活用"}, {"form": "必要性", "label": "派生"}, {"form": "不必要", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 目的のためにどうしても要ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted