INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37813, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の気持ちや思い。感情を感じる精神のはたらき。", "primary_collocate": null, "pronunciation": "こころ", "ipa": "kokoɾo", "syllable_count": 3, "sentences": [{"text": "これらは視覚的な雑音を減らし、心の豊かさを追求する手段となっています。", "target_word": "心", "complexity_tier": "T3", "furigana": "しかく ざつおん へ こころ ゆた ついきゅう しゅだん", "sentence_source": "mined"}, {"text": "彼女の言葉が心に残っている。", "target_word": "心", "complexity_tier": "T3", "furigana": "こころ", "sentence_source": "generated"}, {"text": "心をこめて手紙を書いた。", "target_word": "心", "complexity_tier": "T3", "furigana": "こころ", "sentence_source": "generated"}, {"text": "音楽を聞くと心が落ち着く。", "target_word": "心", "complexity_tier": "T3", "furigana": "こころ", "sentence_source": "generated"}, {"text": "その映画は私の心を動かした。", "target_word": "心", "complexity_tier": "T3", "furigana": "こころ", "sentence_source": "generated"}, {"text": "心の中でありがとうと言った。", "target_word": "心", "complexity_tier": "T3", "furigana": "こころ", "sentence_source": "generated"}, {"text": "彼は心の優しい人だ。", "target_word": "心", "complexity_tier": "T3", "furigana": "こころ", "sentence_source": "generated"}, {"text": "心から友だちを応援している。", "target_word": "心", "complexity_tier": "T3", "furigana": "こころ", "sentence_source": "generated"}, {"text": "緊張で心がどきどきした。", "target_word": "心", "complexity_tier": "T3", "furigana": "こころ", "sentence_source": "generated"}, {"text": "母の笑顔に心が温かくなった。", "target_word": "心", "complexity_tier": "T3", "furigana": "こころ", "sentence_source": "generated"}], "morphological_forms": [{"form": "心から", "label": "派生"}, {"form": "真心", "label": "派生"}, {"form": "心強い", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人の気持ちや思いを感じる精神", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, N