INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36033, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目で物を見て感じとる感覚やはたらき。", "primary_collocate": null, "pronunciation": "しかく", "ipa": "ɕikakɯ", "syllable_count": 3, "sentences": [{"text": "これらは視覚的な雑音を減らし、心の豊かさを追求する手段となっています。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "しかく", "sentence_source": "mined"}, {"text": "人は情報の多くを視覚から得る。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "しかく", "sentence_source": "generated"}, {"text": "ネコの視覚は暗い所でも働く。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "しかく", "sentence_source": "generated"}, {"text": "この絵は視覚に強く訴える。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "しかく", "sentence_source": "generated"}, {"text": "視覚と聴覚を使って学ぶ。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "しかく", "sentence_source": "generated"}, {"text": "彼は事故で視覚を失った。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "しかく", "sentence_source": "generated"}, {"text": "色は視覚に大きな影響を与える。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "しかく", "sentence_source": "generated"}, {"text": "視覚だけに頼ってはいけない。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "しかく", "sentence_source": "generated"}, {"text": "鳥の視覚はとても鋭い。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "しかく", "sentence_source": "generated"}, {"text": "図を使うと視覚で理解できる。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "しかく", "sentence_source": "generated"}], "morphological_forms": [{"form": "視覚的", "label": "派生"}, {"form": "視覚障害", "label": "派生"}, {"form": "視覚化", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 目で物を見て感じとる感覚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-4