INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36975, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "毎日のふだんの生活。いつも普通にくり返されること。", "primary_collocate": null, "pronunciation": "にちじょう", "ipa": "ɲitɕidʑoː", "syllable_count": 4, "sentences": [{"text": "ミニマリストの思想に基づき、必要な要素だけを残すことで、居住者はより穏やかな日常を送ることができます。", "target_word": "日常", "complexity_tier": "T3", "furigana": "にちじょう", "sentence_source": "mined"}, {"text": "彼は静かな日常を楽しんでいる。", "target_word": "日常", "complexity_tier": "T3", "furigana": "にちじょう", "sentence_source": "generated"}, {"text": "地震で日常が大きく変わった。", "target_word": "日常", "complexity_tier": "T3", "furigana": "にちじょう", "sentence_source": "generated"}, {"text": "旅行は日常から離れる時間だ。", "target_word": "日常", "complexity_tier": "T3", "furigana": "にちじょう", "sentence_source": "generated"}, {"text": "小さな幸せは日常の中にある。", "target_word": "日常", "complexity_tier": "T3", "furigana": "にちじょう", "sentence_source": "generated"}, {"text": "その出来事は日常のひとこまだ。", "target_word": "日常", "complexity_tier": "T3", "furigana": "にちじょう", "sentence_source": "generated"}, {"text": "早く元の日常に戻りたい。", "target_word": "日常", "complexity_tier": "T3", "furigana": "にちじょう", "sentence_source": "generated"}, {"text": "日常の会話なら英語で話せる。", "target_word": "日常", "complexity_tier": "T3", "furigana": "にちじょう", "sentence_source": "generated"}, {"text": "散歩は私の日常の一部です。", "target_word": "日常", "complexity_tier": "T3", "furigana": "にちじょう", "sentence_source": "generated"}, {"text": "忙しい日常を忘れて休んだ。", "target_word": "日常", "complexity_tier": "T3", "furigana": "にちじょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "日常的", "label": "派生"}, {"form": "日常生活", "label": "派生"}, {"form": "日常会話", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 毎日くり返されるふだんの生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'clau