INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35423, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の考え方や立場を基本として、行動や考えを進める方針や態度。", "primary_collocate": null, "pronunciation": "しゅぎ", "ipa": "ɕɯgi", "syllable_count": 2, "sentences": [{"text": "近年、パラメトリックデザインの理論は、都市主義の分野において重要な基盤となりつつあります。", "target_word": "主義", "complexity_tier": "T3", "furigana": "きんねん りろん としゅぎ ぶんや じゅうよう きばん", "sentence_source": "mined"}, {"text": "父は自分の主義を曲げない人だ。", "target_word": "主義", "complexity_tier": "T3", "furigana": "ちち じぶん しゅぎ ま ひと", "sentence_source": "generated"}, {"text": "借金をしないのが私の主義です。", "target_word": "主義", "complexity_tier": "T3", "furigana": "しゃっきん わたし しゅぎ", "sentence_source": "generated"}, {"text": "彼女の主義は、とても分かりやすい。", "target_word": "主義", "complexity_tier": "T3", "furigana": "かのじょ しゅぎ わ", "sentence_source": "generated"}, {"text": "その主義に、僕は賛成できない。", "target_word": "主義", "complexity_tier": "T3", "furigana": "しゅぎ ぼく さんせい", "sentence_source": "generated"}, {"text": "彼は主義を守って、肉を食べない。", "target_word": "主義", "complexity_tier": "T3", "furigana": "かれ しゅぎ まも にく た", "sentence_source": "generated"}, {"text": "主義が違っても、友達でいられる。", "target_word": "主義", "complexity_tier": "T3", "furigana": "しゅぎ ちが ともだち", "sentence_source": "generated"}, {"text": "二人は主義の違いで、よく議論する。", "target_word": "主義", "complexity_tier": "T3", "furigana": "ふたり しゅぎ ちが ぎろん", "sentence_source": "generated"}, {"text": "私は、無理をしない主義だ。", "target_word": "主義", "complexity_tier": "T3", "furigana": "わたし むり しゅぎ", "sentence_source": "generated"}, {"text": "彼の主義は、周りに理解されている。", "target_word": "主義", "complexity_tier": "T3", "furigana": "かれ しゅぎ まわ りかい", "sentence_source": "generated"}], "morphological_forms": [{"form": "主義者", "label": "派生"}, {"form": "主義主張", "label": "派生"}, {"form": "民主主義", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 行動の基本となる考え方や立場", "collocate_gr