INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35953, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "多くの事実や法則を筋道立てて説明した知識のまとまり。", "primary_collocate": null, "pronunciation": "りろん", "ipa": "ɾiɾoɴ", "syllable_count": 3, "sentences": [{"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "理論", "complexity_tier": "T3", "furigana": "りろん きばん たてもの こ さくしゃ いと こていてき いみ だつこうちく はいご しゃかいてき ぶんみゃく むじゅん う ぼ", "sentence_source": "mined"}, {"text": "企業はブランディングにおいて、色彩理論を巧みに利用している。", "target_word": "理論", "complexity_tier": "T3", "furigana": "きぎょう しきさい りろん たく りよう", "sentence_source": "mined"}, {"text": "近年、パラメトリックデザインの理論は、都市主義の分野において重要な基盤となりつつあります。", "target_word": "理論", "complexity_tier": "T3", "furigana": "きんねん りろん としゅぎ ぶんや じゅうよう きばん", "sentence_source": "mined"}, {"text": "この理論は、とても難しい。", "target_word": "理論", "complexity_tier": "T3", "furigana": "りろん むずか", "sentence_source": "generated"}, {"text": "兄は新しい理論を勉強している。", "target_word": "理論", "complexity_tier": "T3", "furigana": "あに あたら りろん べんきょう", "sentence_source": "generated"}, {"text": "理論だけでは、うまくいかない。", "target_word": "理論", "complexity_tier": "T3", "furigana": "りろん", "sentence_source": "generated"}, {"text": "先生がその理論を説明してくれた。", "target_word": "理論", "complexity_tier": "T3", "furigana": "せんせい りろん せつめい", "sentence_source": "generated"}, {"text": "理論と実験の結果が合っていた。", "target_word": "理論", "complexity_tier": "T3", "furigana": "りろん じっけん けっか あ", "sentence_source": "generated"}, {"text": "彼の理論に、多くの人が驚いた。", "target_word": "理論", "complexity_tier": "T3", "furigana": "かれ りろん おお ひと おどろ", "sentence_source": "generated"}, {"text": "この本で、音楽の理論を学べる。", "target_word": "理論", "complexity_tier": "T3", "furigana": "ほん おんがく りろん まな", "sentence_source": "generated"}], "morphological_forms": [{"form": "理論的", "label": "派生"}, {"form": "理論家", "label": "派生"}, {"form": "理論上", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 事実を体系的に説明する知識", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41345, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "会社や店などを計画を立てて運営し、管理すること。", "primary_collocate": null, "pronunciation": "けいえい", "ipa": "keːeː", "syllable_count": 4, "sentences": [{"text": "近年、精密農業の導入が小規模農家の経営に新たな可能性をもたらしています。", "target_word": "経営", "complexity_tier": "T3", "furigana": "きんねん せいみつ のうぎょう どうにゅう しょうきぼ のうか けいえい あら かのうせい", "sentence_source": "mined"}, {"text": "単なる出資にとどまらず、経営戦略やネットワークを提供することで、市場に新たな価値を生むイノベーションを加速させるのだ。", "target_word": "経営", "complexity_tier": "T3", "furigana": "たん しゅっし けいえい せんりゃく ていきょう しじょう あら かち う かそく", "sentence_source": "mined"}, {"text": "おじは駅前でパン屋を経営している。", "target_word": "経営", "complexity_tier": "T3", "furigana": "えきまえ や けいえい", "sentence_source": "generated"}, {"text": "店の経営は、思ったより大変だ。", "target_word": "経営", "complexity_tier": "T3", "furigana": "みせ けいえい おも たいへん", "sentence_source": "generated"}, {"text": "母は会社の経営を任されている。", "target_word": "経営", "complexity_tier": "T3", "furigana": "はは かいしゃ けいえい まか", "sentence_source": "generated"}, {"text": "経営がうまくいって、店が増えた。", "target_word": "経営", "complexity_tier": "T3", "furigana": "けいえい みせ ふ", "sentence_source": "generated"}, {"text": "彼は大学で経営を学んでいる。", "target_word": "経営", "complexity_tier": "T3", "furigana": "かれ だいがく けいえい まな", "sentence_source": "generated"}, {"text": "その会社は経営が苦しいそうだ。", "target_word": "経営", "complexity_tier": "T3", "furigana": "かいしゃ けいえい くる", "sentence_source": "generated"}, {"text": "将来は、自分で旅館を経営したい。", "target_word": "経営", "complexity_tier": "T3", "furigana": "しょうらい じぶん りょかん けいえい", "sentence_source": "generated"}, {"text": "祖父の経営する店は、とても古い。", "target_word": "経営", "complexity_tier": "T3", "furigana": "そふ けいえい みせ ふる", "sentence_source": "generated"}], "morphological_forms": [{"form": "経営する", "label": "派生"}, {"form": "経営者", "label": "派生"}, {"form": "経営的", "label": "派生"}], "