INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37765, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "周りの温度や光、音などの変化を感じ取って、電気の信号に変える装置。", "primary_collocate": null, "pronunciation": "せんさー", "ipa": "sensaː", "syllable_count": 4, "sentences": [{"text": "センサー等を用いた技術導入は、収量の安定化により収益性を向上させます。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "とう もち ぎじゅつ どうにゅう しゅうりょう あんていか しゅうえきせい こうじょう", "sentence_source": "mined"}, {"text": "近年、センサーやデータ解析技術を活用した「精密農業」が注目されています。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "きんねん かいせき ぎじゅつ かつよう せいみつ のうぎょう ちゅうもく", "sentence_source": "mined"}, {"text": "電子工作により、センサーやアクチュエータといった「感覚器官」と「筋肉」を物理的に実装する。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "でんし こうさく かんかく きかん きんにく ぶつりてき じっそう", "sentence_source": "mined"}, {"text": "このドアにはセンサーが付いている。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "つ", "sentence_source": "generated"}, {"text": "センサーが光を感じて、電気がついた。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "ひかり かん でんき", "sentence_source": "generated"}, {"text": "兄はロボットにセンサーを付けた。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "あに つ", "sentence_source": "generated"}, {"text": "センサーの調子が悪いみたいだ。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "ちょうし わる", "sentence_source": "generated"}, {"text": "手を出すと、センサーで水が出る。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "て だ みず で", "sentence_source": "generated"}, {"text": "新しいセンサーは、とても小さい。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "あたら ちい", "sentence_source": "generated"}, {"text": "車のセンサーが、人に反応した。", "target_word": "センサー", "complexity_tier": "T3", "furigana": "くるま ひと はんのう", "sentence_source": "generated"}], "morphological_forms": [{"form": "個", "label": "助数詞"}, {"form": "人感センサー", "label": "派生"}, {"form": "温度センサー", "label": "派生