INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36391, 3, 'prompt1_core', '{"pos": "接続詞", "semantic_class": "function", "definition": "二つの事柄を比べて、もう一つの面を述べるときに使う言葉。", "primary_collocate": null, "pronunciation": "いっぽう", "ipa": "ippoː", "syllable_count": 4, "sentences": [{"text": "一方で、農村経済全体を見ると、労働需要の質が変化するという社会経済的影響も無視できません。", "target_word": "一方", "complexity_tier": "T3", "furigana": "いっぽう", "sentence_source": "mined"}, {"text": "兄は明るい。一方、弟は静かだ。", "target_word": "一方", "complexity_tier": "T3", "furigana": "いっぽう あに あか おとうと しず", "sentence_source": "generated"}, {"text": "夏は暑い。一方で、冬はとても寒い。", "target_word": "一方", "complexity_tier": "T3", "furigana": "いっぽう なつ あつ ふゆ さむ", "sentence_source": "generated"}, {"text": "町は便利だ。その一方で、空気が悪い。", "target_word": "一方", "complexity_tier": "T3", "furigana": "いっぽう まち べんり くうき わる", "sentence_source": "generated"}, {"text": "姉は数学が得意だ。一方、私は苦手だ。", "target_word": "一方", "complexity_tier": "T3", "furigana": "いっぽう あね すうがく とくい わたし にがて", "sentence_source": "generated"}, {"text": "値段は安い。一方で、品質は低い。", "target_word": "一方", "complexity_tier": "T3", "furigana": "いっぽう ねだん やす ひんしつ ひく", "sentence_source": "generated"}, {"text": "東は晴れている。一方、西は雨だ。", "target_word": "一方", "complexity_tier": "T3", "furigana": "いっぽう ひがし は にし あめ", "sentence_source": "generated"}, {"text": "練習は楽しい。一方で、試合は緊張する。", "target_word": "一方", "complexity_tier": "T3", "furigana": "いっぽう れんしゅう たの しあい きんちょう", "sentence_source": "generated"}, {"text": "賛成の人もいる。一方、反対の人もいる。", "target_word": "一方", "complexity_tier": "T3", "furigana": "いっぽう さんせい ひと はんたい ひと", "sentence_source": "generated"}, {"text": "都会は人が多い。一方で、村は静かだ。", "target_word": "一方", "complexity_tier": "T3", "furigana": "いっぽう とかい ひと おお むら しず", "sentence_source": "generated"}], "morphological_forms": [{"form": "その一方で", "label": "派生"}, {"form": "一方では", "label": "派生"}, {"form": "他方", "label": "派生"}], "register": "formal", "sense_fingerprint": "接続詞 | 前の事柄と対比して別の面を述べる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35137, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "学んだり経験したりして得た、物事についての理解や情報。", "primary_collocate": null, "pronunciation": "ちしき", "ipa": "tɕiɕiki", "syllable_count": 3, "sentences": [{"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "知識", "complexity_tier": "T3", "furigana": "ちしき", "sentence_source": "mined"}, {"text": "現代の高等教育において、画一的な知識伝達モデルはもはやその有効性を維持し得ない。", "target_word": "知識", "complexity_tier": "T3", "furigana": "ちしき", "sentence_source": "mined"}, {"text": "彼は歴史の知識が豊富だ。", "target_word": "知識", "complexity_tier": "T3", "furigana": "ちしき かれ れきし ほうふ", "sentence_source": "generated"}, {"text": "本を読んで知識を増やしたい。", "target_word": "知識", "complexity_tier": "T3", "furigana": "ちしき ほん よ ふ", "sentence_source": "generated"}, {"text": "知識だけでは問題を解決できない。", "target_word": "知識", "complexity_tier": "T3", "furigana": "ちしき もんだい かいけつ", "sentence_source": "generated"}, {"text": "学校で得た知識を仕事に生かしている。", "target_word": "知識", "complexity_tier": "T3", "furigana": "ちしき がっこう え しごと い", "sentence_source": "generated"}, {"text": "宇宙についての知識が少しある。", "target_word": "知識", "complexity_tier": "T3", "furigana": "ちしき うちゅう すこ", "sentence_source": "generated"}, {"text": "先生は知識のある人を育てたい。", "target_word": "知識", "complexity_tier": "T3", "furigana": "ちしき せんせい ひと そだ", "sentence_source": "generated"}, {"text": "新しい知識は人生を豊かにする。", "target_word": "知識", "complexity_tier": "T3", "furigana": "ちしき あたら じんせい ゆた", "sentence_source": "generated"}, {"text": "料理の知識を友達に教えた。", "target_word": "知識", "complexity_tier": "T3", "furigana": "ちしき りょうり ともだち おし", "sentence_source": "generated"}], "morphological_forms": [{"form": "知識人", "label": "派生"}, {"form": "専門知識", "label": "派生"}, {"form": "予備知識", "label": "派生"}, {"form": "知識欲", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 学んで得た物事の理解や情報", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35659, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の大きさや範囲の広さの程度。", "primary_collocate": null, "pronunciation": "きぼ", "ipa": "kibo", "syllable_count": 2, "sentences": [{"text": "近年、精密農業の導入が小規模農家の経営に新たな可能性をもたらしています。", "target_word": "規模", "complexity_tier": "T3", "furigana": "きぼ", "sentence_source": "mined"}, {"text": "人為的な要因によって大気中に放出された過剰な温室効果ガスは、放射強制力を変化させ、全球規模での気候変動を加速させている。", "target_word": "規模", "complexity_tier": "T3", "furigana": "きぼ", "sentence_source": "mined"}, {"text": "この会社は規模が大きい。", "target_word": "規模", "complexity_tier": "T3", "furigana": "きぼ かいしゃ おお", "sentence_source": "generated"}, {"text": "祭りの規模は毎年大きくなっている。", "target_word": "規模", "complexity_tier": "T3", "furigana": "きぼ まつ まいとし ひろ", "sentence_source": "generated"}, {"text": "町は工場の規模を小さくした。", "target_word": "規模", "complexity_tier": "T3", "furigana": "きぼ まち こうじょう ちい", "sentence_source": "generated"}, {"text": "世界規模で環境問題を考えよう。", "target_word": "規模", "complexity_tier": "T3", "furigana": "きぼ せかい かんきょうもんだい かんが", "sentence_source": "generated"}, {"text": "規模の小さい店でも人気がある。", "target_word": "規模", "complexity_tier": "T3", "furigana": "きぼ ちい みせ にんき", "sentence_source": "generated"}, {"text": "地震の被害の規模を調べている。", "target_word": "規模", "complexity_tier": "T3", "furigana": "きぼ じしん ひがい しら", "sentence_source": "generated"}, {"text": "学校の規模に合った計画を立てる。", "target_word": "規模", "complexity_tier": "T3", "furigana": "きぼ がっこう あ けいかく た", "sentence_source": "generated"}, {"text": "大会は全国規模で行われた。", "target_word": "規模", "complexity_tier": "T3", "furigana": "きぼ たいかい ぜんこく おこな", "sentence_source": "generated"}], "morphological_forms": [{"form": "大規模", "label": "派生"}, {"form": "小規模", "label": "派生"}, {"form": "規模拡大", "label": "派生"}, {"form": "全国規模", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の大きさや範囲の程