INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35297, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しい機械や制度、方法などを取り入れて使い始めること。", "primary_collocate": null, "pronunciation": "どうにゅう", "ipa": "doːɲɯː", "syllable_count": 4, "sentences": [{"text": "近年、精密農業の導入が小規模農家の経営に新たな可能性をもたらしています。", "target_word": "導入", "complexity_tier": "T3", "furigana": "どうにゅう", "sentence_source": "mined"}, {"text": "センサー等を用いた技術導入は、収量の安定化により収益性を向上させます。", "target_word": "導入", "complexity_tier": "T3", "furigana": "どうにゅう", "sentence_source": "mined"}, {"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "導入", "complexity_tier": "T3", "furigana": "どうにゅう", "sentence_source": "mined"}, {"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "導入", "complexity_tier": "T3", "furigana": "どうにゅう", "sentence_source": "mined"}, {"text": "学校は新しい制度を導入した。", "target_word": "導入", "complexity_tier": "T3", "furigana": "どうにゅう がっこう あたら せいど", "sentence_source": "generated"}, {"text": "店にレジの機械が導入された。", "target_word": "導入", "complexity_tier": "T3", "furigana": "どうにゅう みせ きかい", "sentence_source": "generated"}, {"text": "会社はテレワークの導入を決めた。", "target_word": "導入", "complexity_tier": "T3", "furigana": "どうにゅう かいしゃ き", "sentence_source": "generated"}, {"text": "導入の費用が高くて困っている。", "target_word": "導入", "complexity_tier": "T3", "furigana": "どうにゅう ひよう たか こま", "sentence_source": "generated"}, {"text": "町は電気バスを導入している。", "target_word": "導入", "complexity_tier": "T3", "furigana": "どうにゅう まち でんき", "sentence_source": "generated"}, {"text": "新しい方法の導入に反対の人もいる。", "target_word": "導入", "complexity_tier": "T3", "furigana": "どうにゅう あたら ほうほう はんたい ひと", "sentence_source": "generated"}], "morphological_forms": [{"form": "導入する", "label": "派生"}, {"form": "導入した", "label": "活用"}, {"form": "導入される", "label": "活用"}, {"form": "導入部", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 新しい物事を取り入れて使い始めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35807, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "解決しなければならない問題や、取り組むべき目標。", "primary_collocate": null, "pronunciation": "かだい", "ipa": "kadai", "syllable_count": 3, "sentences": [{"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "課題", "complexity_tier": "T3", "furigana": "かだい", "sentence_source": "mined"}, {"text": "課題は自由な「お絵描き」だが、手には短くなった赤いクレヨンが握られている。", "target_word": "課題", "complexity_tier": "T3", "furigana": "かだい", "sentence_source": "mined"}, {"text": "環境問題は大きな課題だ。", "target_word": "課題", "complexity_tier": "T3", "furigana": "かだい かんきょうもんだい おお", "sentence_source": "generated"}, {"text": "チームで課題に取り組んでいる。", "target_word": "課題", "complexity_tier": "T3", "furigana": "かだい と く", "sentence_source": "generated"}, {"text": "今後の課題は人手不足の解消だ。", "target_word": "課題", "complexity_tier": "T3", "furigana": "かだい こんご ひとでぶそく かいしょう", "sentence_source": "generated"}, {"text": "先生から夏休みの課題が出た。", "target_word": "課題", "complexity_tier": "T3", "furigana": "かだい せんせい なつやす で", "sentence_source": "generated"}, {"text": "課題を一つずつ解決していこう。", "target_word": "課題", "complexity_tier": "T3", "furigana": "かだい ひと かいけつ", "sentence_source": "generated"}, {"text": "この町には多くの課題がある。", "target_word": "課題", "complexity_tier": "T3", "furigana": "かだい まち おお", "sentence_source": "generated"}, {"text": "彼は自分の課題をよく分かっている。", "target_word": "課題", "complexity_tier": "T3", "furigana": "かだい かれ じぶん わ", "sentence_source": "generated"}, {"text": "課題の多さに少し疲れた。", "target_word": "課題", "complexity_tier": "T3", "furigana": "かだい おお すこ つか", "sentence_source": "generated"}], "morphological_forms": [{"form": "課題解決", "label": "派生"}, {"form": "今後の課題", "label": "派生"}, {"form": "課題図書", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 解決や取り組みが必要な問題", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51562, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間のからだ。特に、心や精神に対して物としてのからだ。", "primary_collocate": null, "pronunciation": "にくたい", "ipa": "ɲikɯtai", "syllable_count": 4, "sentences": [{"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "にくたい", "sentence_source": "mined"}, {"text": "最初の一年は、美しい田園風景とは裏腹に、泥にまみれた過酷な肉体労働の連続でした。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "にくたい", "sentence_source": "mined"}, {"text": "多忙な現代の専門職に就く我々にとって、オフィスや書斎で迎える限られた昼食の時間はいかにして精神的・肉体的充足へと転換され得るだろうか。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "にくたい", "sentence_source": "mined"}, {"text": "彼は毎日肉体を鍛えている。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "にくたい かれ まいにち きた", "sentence_source": "generated"}, {"text": "肉体の疲れは寝れば取れる。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "にくたい つか ね と", "sentence_source": "generated"}, {"text": "心も肉体も健康でいたい。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "にくたい こころ けんこう", "sentence_source": "generated"}, {"text": "年を取ると肉体は弱くなる。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "にくたい とし と よわ", "sentence_source": "generated"}, {"text": "選手の肉体はとても強い。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "にくたい せんしゅ つよ", "sentence_source": "generated"}, {"text": "精神と肉体のバランスが大切だ。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "にくたい せいしん たいせつ", "sentence_source": "generated"}, {"text": "長い旅で肉体がくたくたになった。", "target_word": "肉体", "complexity_tier": "T3", "furigana": "にくたい なが たび", "sentence_source": "generated"}], "morphological_forms": [{"form": "肉体的", "label": "派生"}, {"form": "肉体労働", "label": "派生"}, {"form": "肉体美", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 精神に対する物質としての人のからだ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38343, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある設計やアイデアを、実際のシステムや仕組みとして作り上げること。", "primary_collocate": null, "pronunciation": "じっそう", "ipa": "dʑissoː", "syllable_count": 4, "sentences": [{"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "実装", "complexity_tier": "T3", "furigana": "しゃかいじっそう", "sentence_source": "mined"}, {"text": "新しい機能の実装に一週間かかった。", "target_word": "実装", "complexity_tier": "T3", "furigana": "あたら きのう じっそう いっしゅうかん", "sentence_source": "generated"}, {"text": "このアプリにはまだ検索が実装されていない。", "target_word": "実装", "complexity_tier": "T3", "furigana": "けんさく じっそう", "sentence_source": "generated"}, {"text": "彼はその考えをすぐに実装した。", "target_word": "実装", "complexity_tier": "T3", "furigana": "かれ かんが じっそう", "sentence_source": "generated"}, {"text": "実装の前に、設計をよく確かめよう。", "target_word": "実装", "complexity_tier": "T3", "furigana": "じっそう まえ せっけい たし", "sentence_source": "generated"}, {"text": "ログイン画面を実装している途中だ。", "target_word": "実装", "complexity_tier": "T3", "furigana": "がめん じっそう とちゅう", "sentence_source": "generated"}, {"text": "実装が終わったら、テストを始めます。", "target_word": "実装", "complexity_tier": "T3", "furigana": "じっそう お はじ", "sentence_source": "generated"}, {"text": "この案は実装が難しいと言われた。", "target_word": "実装", "complexity_tier": "T3", "furigana": "あん じっそう むずか い", "sentence_source": "generated"}, {"text": "チームで新しいゲームを実装できた。", "target_word": "実装", "complexity_tier": "T3", "furigana": "あたら じっそう", "sentence_source": "generated"}, {"text": "実装された機能はとても便利だ。", "target_word": "実装", "complexity_tier": "T3", "furigana": "じっそう きのう べんり", "sentence_source": "generated"}], "morphological_forms": [{"form": "実装する", "label": "派生"}, {"form": "実装した", "label": "活用"}, {"form": "社会実装", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 設計を実際の仕組みに作り上げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38231, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "状態や方向を変えて、別のものにすること。切り替えること。", "primary_collocate": null, "pronunciation": "てんかん", "ipa": "teŋkaɴ", "syllable_count": 4, "sentences": [{"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "転換", "complexity_tier": "T3", "furigana": "てんかん", "sentence_source": "mined"}, {"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "転換", "complexity_tier": "T3", "furigana": "てんかん", "sentence_source": "mined"}, {"text": "我々は、この不可逆的な変化の連鎖をどう受け止めるべきか、文明の存続をかけて抜本的な転換を迫られているのである。", "target_word": "転換", "complexity_tier": "T3", "furigana": "てんかん", "sentence_source": "mined"}, {"text": "多忙な現代の専門職に就く我々にとって、オフィスや書斎で迎える限られた昼食の時間はいかにして精神的・肉体的充足へと転換され得るだろうか。", "target_word": "転換", "complexity_tier": "T3", "furigana": "てんかん", "sentence_source": "mined"}, {"text": "会社は大きな方針の転換を決めた。", "target_word": "転換", "complexity_tier": "T3", "furigana": "かいしゃ おお ほうしん てんかん き", "sentence_source": "generated"}, {"text": "散歩で気分を転換しよう。", "target_word": "転換", "complexity_tier": "T3", "furigana": "さんぽ きぶん てんかん", "sentence_source": "generated"}, {"text": "車はそこで方向を転換した。", "target_word": "転換", "complexity_tier": "T3", "furigana": "くるま ほうこう てんかん", "sentence_source": "generated"}, {"text": "考え方の転換が必要だと思う。", "target_word": "転換", "complexity_tier": "T3", "furigana": "かんが かた てんかん ひつよう おも", "sentence_source": "generated"}, {"text": "この町は農業から観光へ転換している。", "target_word": "転換", "complexity_tier": "T3", "furigana": "まち のうぎょう かんこう てんかん", "sentence_source": "generated"}, {"text": "転換の時期が来たと彼は言った。", "target_word": "転換", "complexity_tier": "T3", "furigana": "てんかん じき き かれ い", "sentence_source": "generated"}], "morphological_forms": [{"form": "転換する", "label": "派生"}, {"form": "転換した", "label": "活用"}, {"form": "方向転換", "label": "派生"}, {"form": "気分転換", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 状態や方向を別のものへ変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37601, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や人が倒れたり、うまくいかなくなったりしないように、力を加えて安定させること。", "primary_collocate": null, "pronunciation": "ささえる", "ipa": "sasaeɾɯ", "syllable_count": 4, "sentences": [{"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "支える", "complexity_tier": "T3", "furigana": "ささ", "sentence_source": "mined"}, {"text": "特に注目すべきは、天井の重量を分散させる「リブ・ヴォールト」と、壁の外側から支える「フライング・バットレス」と呼ばれる技術です。", "target_word": "支える", "complexity_tier": "T3", "furigana": "ささ", "sentence_source": "mined"}, {"text": "この効率的な生産システムは、私たちの食生活を支える基盤となっているのです。", "target_word": "支える", "complexity_tier": "T3", "furigana": "ささ", "sentence_source": "mined"}, {"text": "太い柱が家の屋根を支えている。", "target_word": "支え", "complexity_tier": "T3", "furigana": "ふと はしら いえ やね ささ", "sentence_source": "generated"}, {"text": "転びそうな祖母を私が支えた。", "target_word": "支え", "complexity_tier": "T3", "furigana": "ころ そぼ わたし ささ", "sentence_source": "generated"}, {"text": "家族はいつも私を支えてくれる。", "target_word": "支え", "complexity_tier": "T3", "furigana": "かぞく わたし ささ", "sentence_source": "generated"}, {"text": "友だちに支えられて、最後まで走れた。", "target_word": "支え", "complexity_tier": "T3", "furigana": "とも ささ さいご はし", "sentence_source": "generated"}, {"text": "両手で重い箱を支える。", "target_word": "支える", "complexity_tier": "T3", "furigana": "りょうて おも はこ ささ", "sentence_source": "generated"}, {"text": "彼女は一人でチームを支えている。", "target_word": "支え", "complexity_tier": "T3", "furigana": "かのじょ ひとり ささ", "sentence_source": "generated"}, {"text": "この棒ではテントを支えられない。", "target_word": "支え", "complexity_tier": "T3", "furigana": "ぼう ささ", "sentence_source": "generated"}], "morphological_forms": [{"form": "支えた", "label": "活用"}, {"form": "支えて", "label": "活用"}, {"form": "支えない", "label": "活用"}, {"form": "支え", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 倒れないよう力を加えて保つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37227, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物を動かしたり、熱や光を発生させたりするための源となる力。電気やガソリン、太陽の光など、さまざまな形がある。", "primary_collocate": null, "pronunciation": "えねるぎー", "ipa": "eneɾɯɡiː", "syllable_count": 5, "sentences": [{"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "高温のオーブンへ投入された瞬間、生地は熱エネルギーによって急激に膨張します。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "単なるエネルギー源に過ぎなかった穀物が、生命の維持と豊かな食体験を同時に叶える食文化へと昇華される。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "太陽の光はエネルギーになる。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "たいよう ひかり", "sentence_source": "generated"}, {"text": "車を動かすにはエネルギーが必要だ。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "くるま うご ひつよう", "sentence_source": "generated"}, {"text": "エネルギーを大切に使いましょう。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "たいせつ つか", "sentence_source": "generated"}, {"text": "風の力でエネルギーを作っている。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "かぜ ちから つく", "sentence_source": "generated"}, {"text": "電気は便利なエネルギーの一つだ。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "でんき べんり ひと", "sentence_source": "generated"}, {"text": "この町では新しいエネルギーを使う。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "まち あたら つか", "sentence_source": "generated"}, {"text": "エネルギーの使いすぎが問題になっている。", "target_word": "エネルギー", "complexity_tier": "T3", "furigana": "つか もんだい", "sentence_source": "generated"}], "morphological_forms": [{"form": "エネルギー源", "label": "派生"}, {"form": "省エネルギー", "label": "派生"}, {"form": "太陽エネルギー", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物を動かし熱や光を生む源の力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37143, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "一人で、他に誰もいないこと。または、人数がひとりであること。", "primary_collocate": null, "pronunciation": "ひとり", "ipa": "çitoɾi", "syllable_count": 3, "sentences": [{"text": "記録的な暑さが続く夏の午後、公園の入り方で一人の少年が手作りのレモネードを販売していた。", "target_word": "一人", "complexity_tier": "T3", "furigana": "ひとり", "sentence_source": "mined"}, {"text": "森の奥深くに佇む、その赤いドアの小さな家は、かつて祖母が一人で暮らしていた場所だ。", "target_word": "一人", "complexity_tier": "T3", "furigana": "ひとり", "sentence_source": "mined"}, {"text": "私は一人で駅まで歩いた。", "target_word": "一人", "complexity_tier": "T3", "furigana": "わたし ひとり えき ある", "sentence_source": "generated"}, {"text": "教室には一人しか残っていない。", "target_word": "一人", "complexity_tier": "T3", "furigana": "きょうしつ ひとり のこ", "sentence_source": "generated"}, {"text": "一人の女の子が手をあげた。", "target_word": "一人", "complexity_tier": "T3", "furigana": "ひとり おんな こ て", "sentence_source": "generated"}, {"text": "週末は一人で映画を見に行く。", "target_word": "一人", "complexity_tier": "T3", "furigana": "しゅうまつ ひとり えいが み い", "sentence_source": "generated"}, {"text": "家族の中で、兄が一人だけ背が高い。", "target_word": "一人", "complexity_tier": "T3", "furigana": "かぞく なか あに ひとり せ たか", "sentence_source": "generated"}, {"text": "一人は寂しいけれど、静かでいい。", "target_word": "一人", "complexity_tier": "T3", "furigana": "ひとり さび しず", "sentence_source": "generated"}, {"text": "友だちが一人も来なくて悲しかった。", "target_word": "一人", "complexity_tier": "T3", "furigana": "とも ひとり こ かな", "sentence_source": "generated"}, {"text": "彼は一人で宿題を全部終わらせた。", "target_word": "一人", "complexity_tier": "T3", "furigana": "かれ ひとり しゅくだい ぜんぶ お", "sentence_source": "generated"}], "morphological_forms": [{"form": "一人で", "label": "派生"}, {"form": "一人暮らし", "label": "派生"}, {"form": "一人っ子", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人数がひとり・他に誰もいない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36297, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目的を達成するために、前もって手順や方法を考えること。また、その考え。", "primary_collocate": "立てる", "pronunciation": "けいかく", "ipa": "keːkakɯ", "syllable_count": 4, "sentences": [{"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかく", "sentence_source": "mined"}, {"text": "戦後の都市計画において、ブルータリズムは機能性を重視した新たな住宅様式として普及しました。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかく", "sentence_source": "mined"}, {"text": "夏休みの計画を友だちと立てた。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかく", "sentence_source": "generated"}, {"text": "旅行の計画は兄が考えている。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかく", "sentence_source": "generated"}, {"text": "雨のせいで計画が変わってしまった。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかく", "sentence_source": "generated"}, {"text": "その計画はとてもおもしろいと思う。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかく", "sentence_source": "generated"}, {"text": "先生に計画をくわしく説明した。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかく", "sentence_source": "generated"}, {"text": "文化祭の計画が少しずつ進んでいる。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかく", "sentence_source": "generated"}, {"text": "計画どおりに宿題を終えられた。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかく", "sentence_source": "generated"}, {"text": "新しい公園を作る計画があるらしい。", "target_word": "計画", "complexity_tier": "T3", "furigana": "けいかく", "sentence_source": "generated"}], "morphological_forms": [{"form": "計画する", "label": "派生"}, {"form": "計画的", "label": "派生"}, {"form": "計画書", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 前もって考える手順や方法", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36559, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "温度が低く、触れるとひんやりとした感触があること。", "primary_collocate": null, "pronunciation": "つめたい", "ipa": "tsɯmetai", "syllable_count": 4, "sentences": [{"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "冷たく", "complexity_tier": "T3", "furigana": "つめ", "sentence_source": "mined"}, {"text": "厳冬の冷たさなど意に介さず、ただ純粋に外で遊ぶための準備に余念がないのだ。", "target_word": "冷たさ", "complexity_tier": "T3", "furigana": "つめ", "sentence_source": "mined"}, {"text": "冷たい水を一気に飲んだ。", "target_word": "冷たい", "complexity_tier": "T3", "furigana": "つめ", "sentence_source": "generated"}, {"text": "冬の朝は川の水がとても冷たい。", "target_word": "冷たい", "complexity_tier": "T3", "furigana": "ふゆ あさ かわ みず つめ", "sentence_source": "generated"}, {"text": "風が冷たくて、手が赤くなった。", "target_word": "冷たく", "complexity_tier": "T3", "furigana": "かぜ つめ て あか", "sentence_source": "generated"}, {"text": "このジュースはまだ冷たくない。", "target_word": "冷たく", "complexity_tier": "T3", "furigana": "つめ", "sentence_source": "generated"}, {"text": "冷たいタオルを顔にあてている。", "target_word": "冷たい", "complexity_tier": "T3", "furigana": "つめ かお", "sentence_source": "generated"}, {"text": "雪にさわったら、すごく冷たかった。", "target_word": "冷たかった", "complexity_tier": "T3", "furigana": "ゆき つめ", "sentence_source": "generated"}, {"text": "冷たいアイスを食べられてうれしい。", "target_word": "冷たい", "complexity_tier": "T3", "furigana": "つめ た", "sentence_source": "generated"}, {"text": "窓ガラスが冷たくなっている。", "target_word": "冷たく", "complexity_tier": "T3", "furigana": "まど つめ", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷たかった", "label": "活用"}, {"form": "冷たくて", "label": "活用"}, {"form": "冷たくない", "label": "活用"}, {"form": "冷たさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 温度が低くひんやりしている", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52050, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "感情に左右されず、客観的で冷静な態度を保つさま。", "primary_collocate": null, "pronunciation": "れいてつ", "ipa": "ɾeːtetsɯ", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "冷徹に", "complexity_tier": "T3", "furigana": "れいてつ", "sentence_source": "mined"}, {"text": "さあ、この退廃的な美しさを纏い、冷徹な街路へ歩み出そうではないか。", "target_word": "冷徹な", "complexity_tier": "T3", "furigana": "れいてつ", "sentence_source": "mined"}, {"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "冷徹さ", "complexity_tier": "T3", "furigana": "れいてつ", "sentence_source": "mined"}, {"text": "監督は冷徹な判断で選手を選んだ。", "target_word": "冷徹な", "complexity_tier": "T3", "furigana": "れいてつ", "sentence_source": "generated"}, {"text": "彼は事実を冷徹に見つめている。", "target_word": "冷徹に", "complexity_tier": "T3", "furigana": "れいてつ", "sentence_source": "generated"}, {"text": "その記者の文章は冷徹だと言われる。", "target_word": "冷徹だ", "complexity_tier": "T3", "furigana": "れいてつ", "sentence_source": "generated"}, {"text": "冷徹な目で自分の失敗を考えた。", "target_word": "冷徹な", "complexity_tier": "T3", "furigana": "れいてつ", "sentence_source": "generated"}, {"text": "彼女の冷徹さにみんなおどろいた。", "target_word": "冷徹さ", "complexity_tier": "T3", "furigana": "れいてつ", "sentence_source": "generated"}, {"text": "社長は冷徹に数字だけを見ていた。", "target_word": "冷徹に", "complexity_tier": "T3", "furigana": "れいてつ", "sentence_source": "generated"}, {"text": "冷徹な意見だが、正しいと思う。", "target_word": "冷徹な", "complexity_tier": "T3", "furigana": "れいてつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷徹な", "label": "活用"}, {"form": "冷徹に", "label": "活用"}, {"form": "冷徹さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 感情に流されず冷静で客観的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35697, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "必要な物やサービスを、人や場所に届けること。", "primary_collocate": null, "pronunciation": "きょうきゅう", "ipa": "kʲoːkʲɯː", "syllable_count": 4, "sentences": [{"text": "また、限られた環境で効率的に生産を行う「資源管理」の観点からも、持続可能な食料供給の実現において重要な役割を果たしています。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう", "sentence_source": "mined"}, {"text": "さらに、こうした資金供給メカニズムは、エコシステム全体に好循環をもたらす。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう", "sentence_source": "mined"}, {"text": "地震で水の供給が止まってしまった。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう", "sentence_source": "generated"}, {"text": "この町は電気の供給が安定している。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう", "sentence_source": "generated"}, {"text": "野菜の供給が足りなくて値段が上がった。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう", "sentence_source": "generated"}, {"text": "工場が部品を供給している。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう", "sentence_source": "generated"}, {"text": "ガスの供給はもうすぐ元にもどる。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう", "sentence_source": "generated"}, {"text": "病院への薬の供給がおくれた。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう", "sentence_source": "generated"}, {"text": "食料を供給できる国は少ない。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう", "sentence_source": "generated"}, {"text": "供給が多いと、物は安くなる。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう", "sentence_source": "generated"}], "morphological_forms": [{"form": "供給する", "label": "派生"}, {"form": "供給源", "label": "派生"}, {"form": "供給量", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 必要な物を届けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53110, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "生物が子やたまごなどを体の外に出して増やすこと。", "primary_collocate": null, "pronunciation": "うむ", "ipa": "ɯmɯ", "syllable_count": 2, "sentences": [{"text": "日の出と共に目覚める鶏の健康こそが、栄養豊富な卵を産んでもらうための条件だからである。", "target_word": "産ん", "complexity_tier": "T3", "furigana": "う", "sentence_source": "mined"}, {"text": "うちのニワトリが毎朝卵を産む。", "target_word": "産む", "complexity_tier": "T3", "furigana": "う", "sentence_source": "generated"}, {"text": "ねこが子ねこを三びき産んだ。", "target_word": "産ん", "complexity_tier": "T3", "furigana": "う", "sentence_source": "generated"}, {"text": "カメは砂の中に卵を産む。", "target_word": "産む", "complexity_tier": "T3", "furigana": "う", "sentence_source": "generated"}, {"text": "この鳥は春に卵を産んでいる。", "target_word": "産ん", "complexity_tier": "T3", "furigana": "う", "sentence_source": "generated"}, {"text": "母は病院で弟を産んだ。", "target_word": "産ん", "complexity_tier": "T3", "furigana": "う", "sentence_source": "generated"}, {"text": "寒いと、鶏はあまり卵を産まない。", "target_word": "産ま", "complexity_tier": "T3", "furigana": "う", "sentence_source": "generated"}, {"text": "魚が川で卵を産むのを見た。", "target_word": "産む", "complexity_tier": "T3", "furigana": "う", "sentence_source": "generated"}, {"text": "犬が子犬を産んで、家がにぎやかだ。", "target_word": "産ん", "complexity_tier": "T3", "furigana": "う", "sentence_source": "generated"}, {"text": "卵を産める場所を鳥がさがしている。", "target_word": "産め", "complexity_tier": "T3", "furigana": "う", "sentence_source": "generated"}], "morphological_forms": [{"form": "産んだ", "label": "活用"}, {"form": "産んで", "label": "活用"}, {"form": "産まない", "label": "活用"}, {"form": "産まれる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 子や卵を体の外に出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', tr