INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39083, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある時代や場所で、多くの人に好まれる服装や身だしなみのスタイルのこと。", "primary_collocate": null, "pronunciation": "ふぁっしょん", "ipa": "ɸaʃːoɴ", "syllable_count": 4, "sentences": [{"text": "しかし現代ファッションの文脈では、この伝統的な職人技はデジタルデザインという新たなパラダイムと衝突し、あるいは融合しつつある。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "げんだい", "sentence_source": "mined"}, {"text": "姉はファッションにとても詳しい。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "あね くわ", "sentence_source": "generated"}, {"text": "今年のファッションは明るい色が多い。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "ことし あか いろ おお", "sentence_source": "generated"}, {"text": "ファッションの雑誌を毎月買っている。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "ざっし まいつき か", "sentence_source": "generated"}, {"text": "彼のファッションはいつもおしゃれだ。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "かれ", "sentence_source": "generated"}, {"text": "昔のファッションがまたはやっている。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "むかし", "sentence_source": "generated"}, {"text": "ファッションが好きで、服をよく見る。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "す ふく み", "sentence_source": "generated"}, {"text": "東京は若者のファッションの町だ。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "とうきょう わかもの まち", "sentence_source": "generated"}, {"text": "友だちとファッションについて話した。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "とも はな", "sentence_source": "generated"}, {"text": "ファッションで自分らしさを出せる。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "じぶん だ", "sentence_source": "generated"}], "morphological_forms": [{"form": "ファッション誌", "label": "派生"}, {"form": "ファッションショー", "label": "派生"}, {"form": "ファッションデザイナー", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | はやりの服