INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36037, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "制度や関係などを、しっかりと安定したものにすること。", "primary_collocate": null, "pronunciation": "かくりつ", "ipa": "kakɯɾitsɯ", "syllable_count": 4, "sentences": [{"text": "それは、確立された安住の地からの離脱であり、新たな社会的文脈における自己の再構築を迫られる、極めて重要な通過儀礼なのである。", "target_word": "確立", "complexity_tier": "T3", "furigana": "かくりつ あんじゅう ち りだつ あら しゃかいてき ぶんみゃく じこ さいこうちく せま きわ じゅうよう つうかぎれい", "sentence_source": "mined"}, {"text": "新しい制度の確立には時間がかかる。", "target_word": "確立", "complexity_tier": "T3", "furigana": "あたら せいど かくりつ じかん", "sentence_source": "generated"}, {"text": "信頼関係の確立が大切だ。", "target_word": "確立", "complexity_tier": "T3", "furigana": "しんらい かんけい かくりつ たいせつ", "sentence_source": "generated"}, {"text": "彼は自分のスタイルを確立した。", "target_word": "確立", "complexity_tier": "T3", "furigana": "かれ じぶん かくりつ", "sentence_source": "generated"}, {"text": "ルールの確立を目指している。", "target_word": "確立", "complexity_tier": "T3", "furigana": "かくりつ めざ", "sentence_source": "generated"}, {"text": "確立された方法で実験する。", "target_word": "確立", "complexity_tier": "T3", "furigana": "かくりつ ほうほう じっけん", "sentence_source": "generated"}, {"text": "チームは練習の型を確立できた。", "target_word": "確立", "complexity_tier": "T3", "furigana": "れんしゅう かた かくりつ", "sentence_source": "generated"}, {"text": "安全な仕組みの確立を急ぐ。", "target_word": "確立", "complexity_tier": "T3", "furigana": "あんぜん しく かくりつ いそ", "sentence_source": "generated"}, {"text": "確立は簡単ではない。", "target_word": "確立", "complexity_tier": "T3", "furigana": "かくりつ かんたん", "sentence_source": "generated"}, {"text": "地位を確立するまで努力した。", "target_word": "確立", "complexity_tier": "T3", "furigana": "ちい かくりつ どりょく", "sentence_source": "generated"}], "morphological_forms": [{"form": "確立する", "label": "派生"}, {"form": "確立した", "label": "活用"}, {"form": "確立される", "label": "活用"}], "register": "formal", "sense_fingerpri