INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35161, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "勉強をするために通う建物や施設。", "primary_collocate": null, "pronunciation": "がっこう", "ipa": "gakkoː", "syllable_count": 4, "sentences": [{"text": "高校生は学校でスポーツをします。", "target_word": "学校", "complexity_tier": "T3", "furigana": "こうこうせい がっこう", "sentence_source": "mined"}, {"text": "彼女の人生におけるこの学校の初日は、単なる物理的な場所の移動を意味するものではない。", "target_word": "学校", "complexity_tier": "T3", "furigana": "かのじょ じんせい がっこう しょにち たん ぶつりてき ばしょ いどう いみ", "sentence_source": "mined"}, {"text": "毎朝歩いて学校に行く。", "target_word": "学校", "complexity_tier": "T3", "furigana": "まいあさ ある がっこう い", "sentence_source": "generated"}, {"text": "学校は駅の近くにある。", "target_word": "学校", "complexity_tier": "T3", "furigana": "がっこう えき ちか", "sentence_source": "generated"}, {"text": "学校の図書館で本を読んだ。", "target_word": "学校", "complexity_tier": "T3", "furigana": "がっこう としょかん ほん よ", "sentence_source": "generated"}, {"text": "今日は学校が休みだ。", "target_word": "学校", "complexity_tier": "T3", "furigana": "きょう がっこう やす", "sentence_source": "generated"}, {"text": "新しい学校に慣れてきた。", "target_word": "学校", "complexity_tier": "T3", "furigana": "あたら がっこう な", "sentence_source": "generated"}, {"text": "弟は学校から帰ってきた。", "target_word": "学校", "complexity_tier": "T3", "furigana": "おとうと がっこう かえ", "sentence_source": "generated"}, {"text": "この学校には大きな庭がある。", "target_word": "学校", "complexity_tier": "T3", "furigana": "がっこう おお にわ", "sentence_source": "generated"}, {"text": "学校で友達と話している。", "target_word": "学校", "complexity_tier": "T3", "furigana": "がっこう ともだち はな", "sentence_source": "generated"}], "morphological_forms": [{"form": "校", "label": "助数詞"}, {"form": "小学校", "label": "派生"}, {"form": "学校生活", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 勉強するために通う施設", "collocate_grounding": {"status": "no_source", "reason": "no c