INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51542, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "決まった手順や形に従って行う、大切な意味を持つ行事や行動。", "primary_collocate": null, "pronunciation": "ぎしき", "ipa": "giɕiki", "syllable_count": 3, "sentences": [{"text": "彼にとって、毎朝のこの作業は生活のリズムを作る重要な儀式となっている。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "かれ まいあさ さぎょう せいかつ つく じゅうよう ぎしき", "sentence_source": "mined"}, {"text": "村で古い儀式が行われた。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "むら ふる ぎしき おこな", "sentence_source": "generated"}, {"text": "儀式は朝早く始まる。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "ぎしき あさはや はじ", "sentence_source": "generated"}, {"text": "結婚の儀式に参加した。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "けっこん ぎしき さんか", "sentence_source": "generated"}, {"text": "儀式の準備をしている。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "ぎしき じゅんび", "sentence_source": "generated"}, {"text": "それは大切な儀式だ。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "たいせつ ぎしき", "sentence_source": "generated"}, {"text": "儀式で静かに祈った。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "ぎしき しず いの", "sentence_source": "generated"}, {"text": "彼は儀式の意味を学んだ。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "かれ ぎしき いみ まな", "sentence_source": "generated"}, {"text": "毎年同じ儀式を続ける。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "まいとし おな ぎしき つづ", "sentence_source": "generated"}, {"text": "儀式が終わって皆帰った。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "ぎしき お みな かえ", "sentence_source": "generated"}], "morphological_forms": [{"form": "儀式的", "label": "派生"}, {"form": "件", "label": "助数詞"}], "register": "formal", "sense_fingerprint": "名詞 | 決まった形で行う大切な行事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'cla