INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52068, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ほかのことを考えず、一つのことに夢中になっている様子。", "primary_collocate": null, "pronunciation": "むしん", "ipa": "mɯɕiɴ", "syllable_count": 3, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "無心", "complexity_tier": "T3", "furigana": "ひ えんがわ おさな どうじ とうき はち う ひとかぶ しょくぶつ むしん まなざ そそ", "sentence_source": "mined"}, {"text": "秋の気配が色濃く漂う古びた縁側にて、一人の幼子が無心なる眼差しを向けているのは、掌に収められた一つの赤い果物である。", "target_word": "無心", "complexity_tier": "T3", "furigana": "あき けはい いろこ ただよ ふる えんがわ ひとり おさなご むしん まなざ む てのひら おさ ひと あか くだもの", "sentence_source": "mined"}, {"text": "我々大人が往々にして見落とす微小な営みを、彼は無心に、そして厳粛に刻み続けているのである。", "target_word": "無心", "complexity_tier": "T3", "furigana": "われわれ おとな おうおう みお びしょう いとな かれ むしん げんしゅく きざ つづ", "sentence_source": "mined"}, {"text": "子どもが無心に砂で遊んでいる。", "target_word": "無心", "complexity_tier": "T3", "furigana": "こ むしん すな あそ", "sentence_source": "generated"}, {"text": "彼女は無心に絵を描いていた。", "target_word": "無心", "complexity_tier": "T3", "furigana": "かのじょ むしん え か", "sentence_source": "generated"}, {"text": "無心に遊ぶ姿に心がなごんだ。", "target_word": "無心", "complexity_tier": "T3", "furigana": "むしん あそ すがた こころ", "sentence_source": "generated"}, {"text": "弟は無心に本を読んでいる。", "target_word": "無心", "complexity_tier": "T3", "furigana": "おとうと むしん ほん よ", "sentence_source": "generated"}, {"text": "無心になって木を彫り続けた。", "target_word": "無心", "complexity_tier": "T3", "furigana": "むしん き ほ つづ", "sentence_source": "generated"}, {"text": "練習では無心で球を打つ。", "target_word": "無心", "complexity_tier": "T3", "furigana": "れんしゅう むしん たま う", "sentence_source": "generated"}, {"text": "その無心な姿に感動した。", "target_word": "無心", "complexity_tier": "T3", "furigana": "むしん すがた かんどう", "sentence_source": "generated"}], "morphological_forms": [{"form": "無心に", "label": "活用"}, {"form": "無心な", "label": "活用"}, {"form": "無心だ", "label": "活用"}, {"form": "無心さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 何も考えず夢中になっている様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52118, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ほかのものがまざらず、心がきれいでうそや悪い考えがない様子。", "primary_collocate": null, "pronunciation": "じゅんすい", "ipa": "dʑɯɴsɯi", "syllable_count": 4, "sentences": [{"text": "それは、言葉を持たぬ者が自然と交わす、最も純粋な対話の形なのかもしれない。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "ことば も もの しぜん か もっと じゅんすい たいわ かたち", "sentence_source": "mined"}, {"text": "彼は純粋な心を持っている。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "かれ じゅんすい こころ も", "sentence_source": "generated"}, {"text": "子どもの目はとても純粋だ。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "こ め じゅんすい", "sentence_source": "generated"}, {"text": "純粋に音楽を楽しみたい。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "じゅんすい おんがく たの", "sentence_source": "generated"}, {"text": "この水は純粋で、何も入っていない。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "みず じゅんすい なに はい", "sentence_source": "generated"}, {"text": "彼女の純粋さに心を打たれた。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "かのじょ じゅんすい こころ う", "sentence_source": "generated"}, {"text": "純粋な気持ちで友達を助けた。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "じゅんすい きも ともだち たす", "sentence_source": "generated"}, {"text": "その質問は純粋な興味からだ。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "しつもん じゅんすい きょうみ", "sentence_source": "generated"}, {"text": "彼の夢はいつも純粋だった。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "かれ ゆめ じゅんすい", "sentence_source": "generated"}, {"text": "純粋に勝ちたいと思っている。", "target_word": "純粋", "complexity_tier": "T3", "furigana": "じゅんすい か おも", "sentence_source": "generated"}], "morphological_forms": [{"form": "純粋な", "label": "活用"}, {"form": "純粋に", "label": "活用"}, {"form": "純粋だ", "label": "活用"}, {"form": "純粋さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | まじりけがなく