INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52222, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "同じことがよく起こる様子。多くは「往々にして」の形で使う。", "primary_collocate": null, "pronunciation": "おうおう", "ipa": "oːoː", "syllable_count": 4, "sentences": [{"text": "我々成人が往々にして見落とす、静謐なる成長の過程を、彼はただ純粋な慈愛をもって見守っているのだ。", "target_word": "往々", "complexity_tier": "T3", "furigana": "われわれ せいじん おうおう みお せいひつ せいちょう かてい かれ じゅんすい じあい みまも", "sentence_source": "mined"}, {"text": "我々大人が往々にして見落とす微小な営みを、彼は無心に、そして厳粛に刻み続けているのである。", "target_word": "往々", "complexity_tier": "T3", "furigana": "われわれ おとな おうおう みお びしょう いとな かれ むしん げんしゅく きざ つづ", "sentence_source": "mined"}, {"text": "急ぐと往々にして失敗する。", "target_word": "往々", "complexity_tier": "T3", "furigana": "いそ おうおう しっぱい", "sentence_source": "generated"}, {"text": "うわさは往々にして間違っている。", "target_word": "往々", "complexity_tier": "T3", "furigana": "おうおう まちが", "sentence_source": "generated"}, {"text": "そういうことは往々にしてある。", "target_word": "往々", "complexity_tier": "T3", "furigana": "おうおう", "sentence_source": "generated"}, {"text": "初めは往々にして緊張するものだ。", "target_word": "往々", "complexity_tier": "T3", "furigana": "はじ おうおう きんちょう", "sentence_source": "generated"}, {"text": "往々にして人は見た目で決める。", "target_word": "往々", "complexity_tier": "T3", "furigana": "おうおう ひと み め き", "sentence_source": "generated"}, {"text": "疲れると往々にしてミスが出る。", "target_word": "往々", "complexity_tier": "T3", "furigana": "つか おうおう で", "sentence_source": "generated"}, {"text": "天気予報は往々にして外れる。", "target_word": "往々", "complexity_tier": "T3", "furigana": "てんきよほう おうおう はず", "sentence_source": "generated"}, {"text": "大事な物は往々にしてなくしやすい。", "target_word": "往々", "complexity_tier": "T3", "furigana": "だいじ もの おうおう", "sentence_source": "generated"}], "morphological_forms": [{"form": "往々にして", "label": "派生"}], "register": "formal", "sense_fingerprint": "副詞 | 物事がしばしばそうなる様子", "collocate_groun