INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36657, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある状態を変えずに、そのまま保つこと。", "primary_collocate": null, "pronunciation": "いじ", "ipa": "idʑi", "syllable_count": 2, "sentences": [{"text": "現代の高等教育において、画一的な知識伝達モデルはもはやその有効性を維持し得ない。", "target_word": "維持", "complexity_tier": "T3", "furigana": "げんだい こうとうきょういく かくいつてき ちしき でんたつ ゆうこうせい いじ え", "sentence_source": "mined"}, {"text": "単なるエネルギー源に過ぎなかった穀物が、生命の維持と豊かな食体験を同時に叶える食文化へと昇華される。", "target_word": "維持", "complexity_tier": "T3", "furigana": "たん げん す こくもつ せいめい いじ ゆた しょくたいけん どうじ かな しょくぶんか しょうか", "sentence_source": "mined"}, {"text": "しかし、その無骨な外観や維持管理の難しさから、現在ではその価値が再評価される一方で、取り壊されるケースも増えています。", "target_word": "維持", "complexity_tier": "T3", "furigana": "ぶこつ がいかん いじかんり むずか げんざい かち さいひょうか いっぽう と こわ ふ", "sentence_source": "mined"}, {"text": "健康の維持には運動が大切だ。", "target_word": "維持", "complexity_tier": "T3", "furigana": "けんこう いじ うんどう たいせつ", "sentence_source": "generated"}, {"text": "彼は一位を維持している。", "target_word": "維持", "complexity_tier": "T3", "furigana": "かれ いちい いじ", "sentence_source": "generated"}, {"text": "この車は維持費が高い。", "target_word": "維持", "complexity_tier": "T3", "furigana": "くるま いじひ たか", "sentence_source": "generated"}, {"text": "平和を維持するのは難しい。", "target_word": "維持", "complexity_tier": "T3", "furigana": "へいわ いじ むずか", "sentence_source": "generated"}, {"text": "部屋の温度を維持してください。", "target_word": "維持", "complexity_tier": "T3", "furigana": "へや おんど いじ", "sentence_source": "generated"}, {"text": "現状維持では成長できない。", "target_word": "維持", "complexity_tier": "T3", "furigana": "げんじょう いじ せいちょう", "sentence_source": "generated"}, {"text": "体重の維持に気をつけている。", "target_word": "維持", "complexity_tier": "T3", "furigana": "たいじゅう いじ き", "sentence_source": "generated"}], "morphological_forms": [{"form": "維持する", "label": "派生"}, {"form": "維持した", "label": "活用"}, {"form": "維持できる", "label": "活用"}, {"form": "維持費", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 状態を変えずにそのまま保つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51762, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "問題を解くための、計算や処理の決まった手順。", "primary_collocate": null, "pronunciation": "あるごりずむ", "ipa": "aɾɯɡoɾizɯmɯ", "syllable_count": 6, "sentences": [{"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "ぶんみゃくか じんこうちのう しゅうじゅくど ぶんせき つう がくしゅうしゃ にんち とくせい さいてきか きょうざい ていじ かのう どうにゅう きょういくがく かんてん きわ しさ と", "sentence_source": "mined"}, {"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "にっしょう かぜとお かんきょう へんすう にゅうりょく さいてき がいく はいち じどうてき せいせい しゅほう", "sentence_source": "mined"}, {"text": "このアルゴリズムは速く計算できる。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "はや けいさん", "sentence_source": "generated"}, {"text": "兄は新しいアルゴリズムを考えた。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "あに あたら かんが", "sentence_source": "generated"}, {"text": "アルゴリズムが動画を選んでいる。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "どうが えら", "sentence_source": "generated"}, {"text": "検索のアルゴリズムが変わった。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "けんさく か", "sentence_source": "generated"}, {"text": "授業でアルゴリズムを学んだ。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "じゅぎょう まな", "sentence_source": "generated"}, {"text": "アルゴリズムの説明は難しい。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "せつめい むずか", "sentence_source": "generated"}, {"text": "順番を決めるアルゴリズムを書く。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "じゅんばん き か", "sentence_source": "generated"}, {"text": "良いアルゴリズムで時間が減る。", "target_word": "アルゴリズム", "complexity_tier": "T3", "furigana": "よ じかん へ", "sentence_source": "generated"}], "morphological_forms": [{"form": "アルゴリズム的", "label": "派生"}, {"form": "探索アルゴリズム", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 問題を解く計算や処理の手順", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37303, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "建物や製品などを作る前に、形やしくみを計画して決めること。また、その計画。", "primary_collocate": null, "pronunciation": "せっけい", "ipa": "sekkeː", "syllable_count": 4, "sentences": [{"text": "大学教育の現場において、教授陣が個々の学修到達度を最大化するためにこのシステムを如何に設計し、運用するかが問われているのである。", "target_word": "設計", "complexity_tier": "T3", "furigana": "だいがくきょういく げんば きょうじゅじん ここ がくしゅう とうたつど さいだいか いか せっけい うんよう と", "sentence_source": "mined"}, {"text": "現実的な設計図とは異なるが、その絵には彼が求める理想の世界が詰まっている。", "target_word": "設計", "complexity_tier": "T3", "furigana": "げんじつてき せっけいず こと え かれ もと りそう せかい つ", "sentence_source": "mined"}, {"text": "父は家の設計をしている。", "target_word": "設計", "complexity_tier": "T3", "furigana": "ちち いえ せっけい", "sentence_source": "generated"}, {"text": "この橋は有名な人が設計した。", "target_word": "設計", "complexity_tier": "T3", "furigana": "はし ゆうめい ひと せっけい", "sentence_source": "generated"}, {"text": "設計を少し変えることにした。", "target_word": "設計", "complexity_tier": "T3", "furigana": "せっけい すこ か", "sentence_source": "generated"}, {"text": "新しい車の設計が終わった。", "target_word": "設計", "complexity_tier": "T3", "furigana": "あたら くるま せっけい お", "sentence_source": "generated"}, {"text": "彼女は学校を設計している。", "target_word": "設計", "complexity_tier": "T3", "furigana": "かのじょ がっこう せっけい", "sentence_source": "generated"}, {"text": "設計の仕事に興味がある。", "target_word": "設計", "complexity_tier": "T3", "furigana": "せっけい しごと きょうみ", "sentence_source": "generated"}, {"text": "この部屋は設計がよくできている。", "target_word": "設計", "complexity_tier": "T3", "furigana": "へや せっけい", "sentence_source": "generated"}, {"text": "ロボットの設計に一年かかった。", "target_word": "設計", "complexity_tier": "T3", "furigana": "いちねん", "sentence_source": "generated"}], "morphological_forms": [{"form": "設計する", "label": "派生"}, {"form": "設計した", "label": "活用"}, {"form": "設計図", "label": "派生"}, {"form": "設計者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物を作る前に形や仕組みを計画すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36935, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を考えるときの、特定の立場や視点。", "primary_collocate": null, "pronunciation": "かんてん", "ipa": "kanteɴ", "syllable_count": 4, "sentences": [{"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "観点", "complexity_tier": "T3", "furigana": "かんてん", "sentence_source": "mined"}, {"text": "また、限られた環境で効率的に生産を行う「資源管理」の観点からも、持続可能な食料供給の実現において重要な役割を果たしています。", "target_word": "観点", "complexity_tier": "T3", "furigana": "かんてん", "sentence_source": "mined"}, {"text": "色は単なる装飾ではなく、記号論の観点から特定のメッセージを伝える記号として機能するのだ。", "target_word": "観点", "complexity_tier": "T3", "furigana": "かんてん", "sentence_source": "mined"}, {"text": "安全の観点から、この道は使えない。", "target_word": "観点", "complexity_tier": "T3", "furigana": "あんぜん かんてん みち つか", "sentence_source": "generated"}, {"text": "彼の観点はとても新しい。", "target_word": "観点", "complexity_tier": "T3", "furigana": "かれ かんてん あたら", "sentence_source": "generated"}, {"text": "別の観点で考えてみよう。", "target_word": "観点", "complexity_tier": "T3", "furigana": "べつ かんてん かんが", "sentence_source": "generated"}, {"text": "観点が違うと、答えも変わる。", "target_word": "観点", "complexity_tier": "T3", "furigana": "かんてん ちが こた か", "sentence_source": "generated"}, {"text": "先生は生徒の観点を大切にする。", "target_word": "観点", "complexity_tier": "T3", "furigana": "せんせい せいと かんてん たいせつ", "sentence_source": "generated"}, {"text": "環境の観点で計画を見直した。", "target_word": "観点", "complexity_tier": "T3", "furigana": "かんきょう かんてん けいかく みなお", "sentence_source": "generated"}, {"text": "この観点は見落としていた。", "target_word": "観点", "complexity_tier": "T3", "furigana": "かんてん みお", "sentence_source": "generated"}], "morphological_forms": [{"form": "観点から", "label": "派生"}, {"form": "別の観点", "label": "派生"}, {"form": "観点別", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事を考えるときの立場や視点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36727, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を正しく理解したり、判断したりする心のはたらき。", "primary_collocate": null, "pronunciation": "にんち", "ipa": "ɲiɴtɕi", "syllable_count": 3, "sentences": [{"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "認知", "complexity_tier": "T3", "furigana": "にんち", "sentence_source": "mined"}, {"text": "その一つひとつの動作が、彼女の認知能力と社会性を育む養分となる。", "target_word": "認知", "complexity_tier": "T3", "furigana": "にんち", "sentence_source": "mined"}, {"text": "睡眠は認知の働きを助ける。", "target_word": "認知", "complexity_tier": "T3", "furigana": "すいみん にんち はたら たす", "sentence_source": "generated"}, {"text": "年をとると認知が遅くなる。", "target_word": "認知", "complexity_tier": "T3", "furigana": "とし にんち おそ", "sentence_source": "generated"}, {"text": "子どもの認知は遊びで育つ。", "target_word": "認知", "complexity_tier": "T3", "furigana": "こ にんち あそ そだ", "sentence_source": "generated"}, {"text": "音楽は認知によい影響がある。", "target_word": "認知", "complexity_tier": "T3", "furigana": "おんがく にんち えいきょう", "sentence_source": "generated"}, {"text": "彼は認知の研究をしている。", "target_word": "認知", "complexity_tier": "T3", "furigana": "かれ にんち けんきゅう", "sentence_source": "generated"}, {"text": "認知の力をゲームで調べた。", "target_word": "認知", "complexity_tier": "T3", "furigana": "にんち ちから しら", "sentence_source": "generated"}, {"text": "運動すると認知が良くなる。", "target_word": "認知", "complexity_tier": "T3", "furigana": "うんどう にんち よ", "sentence_source": "generated"}, {"text": "人の認知には限界がある。", "target_word": "認知", "complexity_tier": "T3", "furigana": "ひと にんち げんかい", "sentence_source": "generated"}], "morphological_forms": [{"form": "認知する", "label": "派生"}, {"form": "認知症", "label": "派生"}, {"form": "認知能力", "label": "派生"}, {"form": "認知的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事を理解し判断する心の働き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36185, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある状態や動作を中断せずに、次へ次へと進めること。", "primary_collocate": null, "pronunciation": "つづける", "ipa": "tsɯzɯkeɾɯ", "syllable_count": 4, "sentences": [{"text": "変化に適応し、自らの価値を高め続ける姿勢が、これからの職場では強く求められる。", "target_word": "続ける", "complexity_tier": "T3", "furigana": "つづ", "sentence_source": "mined"}, {"text": "毎日ピアノの練習を続ける。", "target_word": "続ける", "complexity_tier": "T3", "furigana": "まいにち れんしゅう つづ", "sentence_source": "generated"}, {"text": "彼は雨の中を走り続けた。", "target_word": "続けた", "complexity_tier": "T3", "furigana": "かれ あめ なか はし つづ", "sentence_source": "generated"}, {"text": "話を続けてください。", "target_word": "続けて", "complexity_tier": "T3", "furigana": "はなし つづ", "sentence_source": "generated"}, {"text": "仕事を続けるのは大変だ。", "target_word": "続ける", "complexity_tier": "T3", "furigana": "しごと つづ たいへん", "sentence_source": "generated"}, {"text": "三年間、日記を続けている。", "target_word": "続けて", "complexity_tier": "T3", "furigana": "さんねんかん にっき つづ", "sentence_source": "generated"}, {"text": "疲れても勉強を続けた。", "target_word": "続けた", "complexity_tier": "T3", "furigana": "つか べんきょう つづ", "sentence_source": "generated"}, {"text": "この運動なら長く続けられる。", "target_word": "続けられる", "complexity_tier": "T3", "furigana": "うんどう なが つづ", "sentence_source": "generated"}, {"text": "続ける力が大切だと思う。", "target_word": "続ける", "complexity_tier": "T3", "furigana": "つづ ちから たいせつ おも", "sentence_source": "generated"}, {"text": "彼女は黙って歩き続けた。", "target_word": "続けた", "complexity_tier": "T3", "furigana": "かのじょ だま ある つづ", "sentence_source": "generated"}], "morphological_forms": [{"form": "続けた", "label": "活用"}, {"form": "続けて", "label": "活用"}, {"form": "続けない", "label": "活用"}, {"form": "続けられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 動作や状態を止めずに進める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51552, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "心や目にうつったものが、とても良いと感じられるさま。", "primary_collocate": null, "pronunciation": "うつくしい", "ipa": "ɯtsɯkɯɕii", "syllable_count": 5, "sentences": [{"text": "中世ヨーロッパで発展したゴシック様式の大聖堂は、その圧倒的な高さと美しさで人々を魅了しました。", "target_word": "美し", "complexity_tier": "T3", "furigana": "うつく", "sentence_source": "mined"}, {"text": "最初の一年は、美しい田園風景とは裏腹に、泥にまみれた過酷な肉体労働の連続でした。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "うつく", "sentence_source": "mined"}, {"text": "山の上から見る海は美しい。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "やま うえ み うみ うつく", "sentence_source": "generated"}, {"text": "彼女は美しい声で歌った。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "かのじょ うつく こえ うた", "sentence_source": "generated"}, {"text": "秋の紅葉が美しかった。", "target_word": "美しかった", "complexity_tier": "T3", "furigana": "あき こうよう うつく", "sentence_source": "generated"}, {"text": "この町は夜が美しくて有名だ。", "target_word": "美しくて", "complexity_tier": "T3", "furigana": "まち よる うつく ゆうめい", "sentence_source": "generated"}, {"text": "美しい友情の話に感動した。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "うつく ゆうじょう はなし かんどう", "sentence_source": "generated"}, {"text": "庭の花が美しく咲いている。", "target_word": "美しく", "complexity_tier": "T3", "furigana": "にわ はな うつく さ", "sentence_source": "generated"}, {"text": "彼の字はとても美しい。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "かれ じ うつく", "sentence_source": "generated"}, {"text": "美しい景色を写真に撮った。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "うつく けしき しゃしん と", "sentence_source": "generated"}], "morphological_forms": [{"form": "美しかった", "label": "活用"}, {"form": "美しくて", "label": "活用"}, {"form": "美しくない", "label": "活用"}, {"form": "美しさ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形容詞 | 見て心にとても良いと感じる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36159, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が起こる、ほんのわずかな時間。", "primary_collocate": null, "pronunciation": "しゅんかん", "ipa": "ɕɯŋkaɴ", "syllable_count": 4, "sentences": [{"text": "高温のオーブンへ投入された瞬間、生地は熱エネルギーによって急激に膨張します。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "しゅんかん", "sentence_source": "mined"}, {"text": "ドアを開けた瞬間、猫が出た。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "あ しゅんかん ねこ で", "sentence_source": "generated"}, {"text": "ゴールの瞬間、みんなが叫んだ。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "しゅんかん さけ", "sentence_source": "generated"}, {"text": "その瞬間を写真に撮った。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "しゅんかん しゃしん と", "sentence_source": "generated"}, {"text": "あの瞬間は今も忘れない。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "しゅんかん いま わす", "sentence_source": "generated"}, {"text": "彼を見た瞬間、笑ってしまった。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "かれ み しゅんかん わら", "sentence_source": "generated"}, {"text": "幸せな瞬間がずっと続けばいい。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "しあわ しゅんかん つづ", "sentence_source": "generated"}, {"text": "勝った瞬間に涙が出た。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "か しゅんかん なみだ で", "sentence_source": "generated"}, {"text": "瞬間の判断がとても大事だ。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "しゅんかん はんだん だいじ", "sentence_source": "generated"}, {"text": "花火が開く瞬間を待つ。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "はなび ひら しゅんかん ま", "sentence_source": "generated"}], "morphological_forms": [{"form": "瞬間的", "label": "派生"}, {"form": "一瞬", "label": "派生"}, {"form": "瞬間移動", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事が起こるごく短い時間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41329, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンや酒などの発酵に使われる小さな生き物。糖を分けてアルコールと二酸化炭素を作る。", "primary_collocate": null, "pronunciation": "こうぼ", "ipa": "koːbo", "syllable_count": 3, "sentences": [{"text": "天然酵母を用いた製パンは、職人の緻密な管理が不可欠な工程です。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "てんねん こうぼ もち せい しょくにん ちみつ かんり ふかけつ こうてい", "sentence_source": "mined"}, {"text": "酵母の活動を観察しながら生地を仕上げ、いよいよ焼成へと進みます。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "こうぼ かつどう かんさつ きじ しあ しょうせい すす", "sentence_source": "mined"}, {"text": "静謐な工房において、作り手は野生酵母と乳酸菌の共生するサワードウの種起こしから営為を開始する。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "せいひつ こうぼう つく て やせい こうぼ にゅうさんきん きょうせい たねお えいい かいし", "sentence_source": "mined"}, {"text": "酵母がパンをふくらませる。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "こうぼ", "sentence_source": "generated"}, {"text": "母は自分で酵母を育てている。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "はは じぶん こうぼ そだ", "sentence_source": "generated"}, {"text": "この酵母は暖かい所でよく働く。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "こうぼ あたた ところ はたら", "sentence_source": "generated"}, {"text": "ビールを作るには酵母が必要だ。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "つく こうぼ ひつよう", "sentence_source": "generated"}, {"text": "酵母を入れて生地を一時間置いた。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "こうぼ い きじ いちじかん お", "sentence_source": "generated"}, {"text": "理科の授業で酵母を観察した。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "りか じゅぎょう こうぼ かんさつ", "sentence_source": "generated"}, {"text": "酵母の量で味が変わるそうだ。", "target_word": "酵母", "complexity_tier": "T3", "furigana": "こうぼ りょう あじ か", "sentence_source": "generated"}], "morphological_forms": [{"form": "天然酵母", "label": "派生"}, {"form": "酵母菌", "label": "派生"}, {"form": "パン酵母", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 発酵に使う微生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39715, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "指の先の部分。", "primary_collocate": null, "pronunciation": "ゆびさき", "ipa": "jɯbisaki", "syllable_count": 4, "sentences": [{"text": "指先で色を擦り混ぜ、重ね塗りをする技法によって、私は心の中の風景を絵として表現している。", "target_word": "指先", "complexity_tier": "T3", "furigana": "ゆびさき いろ こす ま かさ ぬ ぎほう わたし こころ なか ふうけい え ひょうげん", "sentence_source": "mined"}, {"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "指先", "complexity_tier": "T3", "furigana": "ゆびさき つう つた きじ びみょう だんりょく はっこう しんこう ぐあい ゆいいつ らしんばん かれ おんど しつど へんすう ちみつ せいぎょ びせいぶつ め み しず たいわ こころ", "sentence_source": "mined"}, {"text": "寒くて指先が冷たくなった。", "target_word": "指先", "complexity_tier": "T3", "furigana": "さむ ゆびさき つめ", "sentence_source": "generated"}, {"text": "彼女は指先がとても器用だ。", "target_word": "指先", "complexity_tier": "T3", "furigana": "かのじょ ゆびさき きよう", "sentence_source": "generated"}, {"text": "紙で指先を切ってしまった。", "target_word": "指先", "complexity_tier": "T3", "furigana": "かみ ゆびさき き", "sentence_source": "generated"}, {"text": "指先でスマホの画面に触れる。", "target_word": "指先", "complexity_tier": "T3", "furigana": "ゆびさき がめん ふ", "sentence_source": "generated"}, {"text": "ピアノを弾く指先が美しい。", "target_word": "指先", "complexity_tier": "T3", "furigana": "ひ ゆびさき うつく", "sentence_source": "generated"}, {"text": "指先に小さなけがをした。", "target_word": "指先", "complexity_tier": "T3", "furigana": "ゆびさき ちい", "sentence_source": "generated"}, {"text": "手袋をしても指先は寒い。", "target_word": "指先", "complexity_tier": "T3", "furigana": "てぶくろ ゆびさき さむ", "sentence_source": "generated"}, {"text": "職人の指先の動きを見ている。", "target_word": "指先", "complexity_tier": "T3", "furigana": "しょくにん ゆびさき うご み", "sentence_source": "generated"}], "morphological_forms": [{"form": "指", "label": "派生"}, {"form": "本", "label": "助数詞"}], "register": "plain", "sense_fingerprint": "名詞 | 手や足の指の先端部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
